WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[29088] = { title = "Hyena Extermination", description = "Hey {name}, we've got a real problem here. There's an overpopulation of hyenas just west of the Sludge Fen, and they're starting to become a menace.\n\nIf I have to listen to them caterwauling one more night, I just might go crazy! Vernon over there says the hyenas might even have made off with one of his stabled pigs. We can't have that happening.\n\nCan you go thin out the hyena numbers? You'll find them parading in broad daylight to the west.", objectives = "" }
WordHunterWoW_QuestEN[29089] = { title = "Sludge Beast!", description = "Whatever is lurking around the Sludge Fen, it doesn't appear to be human. Judging from the remains around its tracks, it's also dangerous.\n\nYou decide to follow the tracks down to the bottom of the lake and look for the creature's resting place.", objectives = "" }
WordHunterWoW_QuestEN[29090] = { title = "A Burning Threat", description = "While we cast our eyes toward the cataclysm, who watches our backs? While our leaders take up arms against Deathwing, the Burning Blade plots our downfall.\n\nEven as we speak, they are gathering recruits and supplies at the farm to the southwest. I care not to meet death at the hands of the Burning Legion. It's time we take matters into our own hands.\n\n{name}, will you help me keep the vigil? Go and slaughter their ranks before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[29091] = { title = "Freedom Movement", description = "", objectives = "" }
WordHunterWoW_QuestEN[29092] = { title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", objectives = "" }
WordHunterWoW_QuestEN[29093] = { title = "Cruisin' the Chasm", description = "One of my friends says that a steam tank mechanic in Westfall lets visitors use his choppers. My friend even got to ride one!\n\nI've seen people ride by the orphanage in choppers. They're real loud and just about the fastest thing I've ever seen! I want to try one out!\n\nCould we go to Sentinel Hill in Westfall and ride one of those choppers? Please? I promise to behave myself and we could see the crazy giant hole left when the world changed!", objectives = "" }
WordHunterWoW_QuestEN[29094] = { title = "The Short Way Home", description = "Looks like your work here is done, {class}. You'd better head back to the Crossroads.\n\nLuckily for you, my Silver Bullet X-831 prototype is finished, and she's ready for a test drive. Whaddaya say you do me one last favor and take her for a little spin?\n\nOne of my assistants will accompany you. Your sweet, sweet ride is waiting on the platform behind me. Just hop on when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[29095] = { title = "Report to Thork", description = "Now that the threat here has been stilled, you should return to the Crossroads. Thork would like to speak to you.\n\nFarewell, friend.", objectives = "" }
WordHunterWoW_QuestEN[29096] = { title = "Mor'shan Caravan Pick-Up", description = "Rocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.", objectives = "" }
WordHunterWoW_QuestEN[29100] = { title = "Bwemba's Spirit", description = "Dese be troublin' times for us Darkspear.  Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we can.  But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn da people.  But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI gonna bind my spirit wit' ya.  When ya get to Stranglethorn, I be able to aid ya.", objectives = "" }
WordHunterWoW_QuestEN[29101] = { title = "Punting Season", description = "Baby turtles are sweet, even if they can be somewhat bitey.\n\n<Mylune holds up a bandaged finger.>\n\nBut they're so slow with their tiny little legs, they can't escape the fire creatures who are attacking Hyjal!\n\n<Mylune claps her hands together.>\n\nPLEASE save them, {name}! Pick up the wee turtles and punt them into the water of the Ashen Lake. Don't worry about the kicking, they have hard shells.\n\nThey also have hard teeth, so don't pick them up by the mouth.", objectives = "" }
WordHunterWoW_QuestEN[29102] = { title = "To Fort Livingston", description = "Da first place we check gonna be da place most likely to be attacked first.  You call it Fort Livingston.\n\nFort Livingston be surrounded by troll ruins... It make for an easy target.\n\nMaybe we find da emissary dere.  Hopefully it ain't too late.", objectives = "" }
WordHunterWoW_QuestEN[29103] = { title = "Serpents and Poison", description = "Because of the emissary's warning we were able to gather more adventurers to help defend.  But we thought we were going to be fighting trolls.\n\nInstead we found ourselves overwhelmed by serpents!\n\nThey seem to have come from everywhere.  We are barely able to hold on, and I only suspect it's going to get worse.\n\nHelp us and eliminate the serpents and perhaps your troll friend here can use some magic to cure the poisoned.", objectives = "" }
WordHunterWoW_QuestEN[29104] = { title = "Spirits Are With Us", description = "Dere was somethin' not right about dem serpents, {name}.  Dere was a trace of some bad mojo in da poison an' dat don't happen naturally.\n\nDa bonfire in da middle of da camp, we can use dat to perform a ritual.\n\nWhatever be makin' dese serpents attack, dey probably still watchin' over dem.\n\nDa only problem, {name}, is dat I only be here in spirit form.  I need you to be my hands.  I need you to go to da fire an' prepare it for me.  Den I'll handle da rest.", objectives = "" }
WordHunterWoW_QuestEN[29105] = { title = "Nesingwary Will Know", description = "Great, just what we need, the Gurubashi on the rampage using serpents to lead the charge.  Well at least we know that much.\n\nIt's probably a safe bet that the hunters at Nesingwary's Expedition have some insight into this.  If they don't they at least know how to fight the serpents.\n\nHead there and let them know what you saw here.  Let them know that the trolls are using serpents as their weapon.", objectives = "" }
WordHunterWoW_QuestEN[29106] = { title = "The Biggest Diamond Ever!", description = "I heard that Magni Bronzebeard, who used to be the king of Ironforge, turned into a giant diamond! Is that true? How does someone just turn into a diamond? Maybe you have to be a king and that's why no one's done it before.\n\nCan we go see him? He should be in the part of Ironforge called Old Ironforge underneath the High Seat.", objectives = "" }
WordHunterWoW_QuestEN[29109] = { title = "Mor'shan Caravan Pick-Up", description = "The battle in Ashenvale rages on without relent. Our forces at the Mor'shan Ramparts are in desperate need of reinforcements and supplies.\n\nWe have a major shipment of medicines and food headed north, and I need a capable {class} like you to guard it.\n\nRocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.", objectives = "" }
WordHunterWoW_QuestEN[29110] = { title = "Mor'shan Caravan Rescue", description = "They took Balgor and the caravan supplies from our very doorstep!\n\nThose supplies are vital for our victory against the Alliance in Ashenvale, and Balgor...if anything happens to my dear little brother, I will rip every Burning Blade member to shreds myself.\n\n{name}, I need you to rescue Balgor and the captured caravan. Follow the path just north of us, up onto Dreadmist Peak. Do not let any of those Burning Blade dogs live.", objectives = "" }
WordHunterWoW_QuestEN[29111] = { title = "Mor'shan Caravan Delivery", description = "You've managed to stir the Burning Blade's nest. Our scouts report that they are gathering for an attack.\n\nYou must complete the caravan's journey before they arrive. The supplies are packed, the kodos are rested, and I hope you don't mind but I made a few adjustments to your gun.\n\nIf you meet up with any resistance, shoot first and ask questions later.\n\nQuickly! They come! Speak to me when you are ready to leave.", objectives = "" }
WordHunterWoW_QuestEN[29112] = { title = "Demon Seed", description = "Listen {name}, we can't leave quite yet. I managed to overhear their plans while they were preparing for the ritual sacrifice.\n\nThey're planning to use a powerful artifact called the Demon Seed to launch a full scale attack on the Horde. They're keeping it under close guard over in that cave.\n\nIf you can get your hands on the Demon Seed, we should take it to my sister Nagala. She'll know what to do with it.", objectives = "" }
WordHunterWoW_QuestEN[29114] = { title = "Track the Tracker", description = "We've been fending off serpents for days now, {name}.  But the serpents are nothing compared to what else is out in that jungle.\n\nWe hunters are being hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer headed off to the east, perhaps you can find them there.", objectives = "" }
WordHunterWoW_QuestEN[29115] = { title = "The Hunter's Revenge", description = "The beast that's been hunting us... I've been hunting it.\n\nWe call him Mauti.  He's a clever one.  But he made a grave mistake when he killed my brother.  Now that mistake is going to cost him.  Ol' Direhammer has got his scent.\n\nI've noticed him roaming just above Kurzen's Compound.  If we act fast, we can take him down.\n\nAre you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29116] = { title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[29117] = { title = "Let's Go Fly a Kite", description = "The other day, when some of us were out with the matron, I saw a gnome pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time.\n\nI think the gnome's name was Craggle Wobbletop or something like that. If we can find him, could we get some kites and fly them together? I saw him walking around the canals outside the Trade District.", objectives = "" }
WordHunterWoW_QuestEN[29118] = { title = "Follow That Cat", description = "The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[29119] = { title = "You Scream, I Scream...", description = "There's a brand new ice cream shop in Stormwind, and it's not just any old ice cream either. This ice cream is made by mages! You don't think I'm going to be hungry fifteen minutes after eating it, do you?\n\nI bet it tastes really good. Let's go try it!\n\nI heard some of the other kids talking about it, and they were saying the store is called The Cone of Cold and it's over near the Blue Recluse in the Mage Quarter.", objectives = "" }
WordHunterWoW_QuestEN[29120] = { title = "Mauti", description = "I got da feeling dat somethin' ain't right wit' dat panther, {name}.  It ain't natural.  I gonna need to perform some rituals over da body.  Put Mauti down, an' den let's see what we can find out, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29121] = { title = "Bury Me With Me Boots...", description = "Ah... It's you, {name}.  Mauti... He's dead?  Then my brother has been avenged.  I've only one request from ya... This scamp here, he's been pawing at me bare feet.  No dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.", objectives = "" }
WordHunterWoW_QuestEN[29122] = { title = "Echoes of Nemesis", description = "<Mylune's voice sings like a melody in your head.>\n\nRemember that awful fire turtle, Nemesis, from the Firelands? He's dead now (yay!) but echoes of him keep trying to break through to Mount Hyjal.\n\nGo to the shores of the Ashen Lake and speak with my friend Tooga. Let him know you're ready to fight an echo of Nemesis, and the turtles will draw him into this world. Then you can hit him! Hard!\n\nHide inside of Tooga's shell if he starts to erupt.", objectives = "" }
WordHunterWoW_QuestEN[29123] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "" }
WordHunterWoW_QuestEN[29124] = { title = "Warn the Rebel Camp", description = "Dis death ain't be in vain, {name}.  We figure out dat Kilnara be on da prowl.  Tings don't look good.\n\nWe better check out da Rebel Camp to da north.  Maybe we find my contact dere.", objectives = "" }
WordHunterWoW_QuestEN[29125] = { title = "Between the Trees", description = "Spirit fragments of Malorne - seen to us mortals as ghostly white deer - still frolic through these forests. While Malorne is no longer with us, these pieces of his spirit may be of use to us.\n\nTravel east and walk among the trees. If you are able to get close enough to one of the spirit fragments, it will bestow its power to you.\n\nOh, and take this staff. You may need it later.", objectives = "" }
WordHunterWoW_QuestEN[29126] = { title = "The Power of Malorne", description = "<Matoclaw's voice continues.>\n\nThe portal that opened up to our east is guarded by a powerful flamewaker by the name of Galenges. We will need all of Malorne's help in defeating him.\n\nDo you remember the staff that I gave you? Place it in the pile of ash in front of the portal. Then pray that Malorne comes to your aid.", objectives = "" }
WordHunterWoW_QuestEN[29127] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "" }
WordHunterWoW_QuestEN[29128] = { title = "The Protectors of Hyjal", description = "We need to place pressure on the assault camp at Sethria's Roost. Ragnaros' minions are using this area as a point to push their battlefront beyond the bounds of Hyjal. I'm putting you in charge of a small squad to deal with them.\n\nI have selected an elite group of fighters to assist you. Travel to Sethria's Roost. Your compatriots have been instructed to meet you once you arrive. Then put an end to the elementals' assault.", objectives = "" }
WordHunterWoW_QuestEN[29129] = { title = "A Legendary Engagement", description = "A pleasure, {class}.\n\n<Ziradormi smiles.>\n\nIt was kind of you to arrive so quickly.\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would counsel you not to take this invitation lightly. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once.\n\nSpeak to me when you are ready and I shall personally deliver you.", objectives = "" }
WordHunterWoW_QuestEN[29131] = { title = "Defend the Rebel Camp", description = "We are in trouble here, {name}.  Your troll friend has been through here and warned us that things were going to get serious, but I didn't think it would be this bad.\n\nWe are doing our best to hold off these trolls.  But any help you can offer would greatly help.", objectives = "" }
WordHunterWoW_QuestEN[29132] = { title = "A Legendary Engagement", description = "I expected that I would find you here, {class}. But then, we of the bronze flight have somewhat of an advantage when it comes to such things.\n\n<Coridormi smiles.>\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would counsel you not to take this invitation lightly, {name}. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once.\n\nSpeak to me when you are ready and I shall personally deliver you.", objectives = "" }
WordHunterWoW_QuestEN[29133] = { title = "To the Digsite", description = "The other Darkspear emissary was here briefly.  He was eager to get to the next location and warn them.   I sent him on a flight to the Explorers' League Digsite in the Cape of Stranglethorn.  I hope he wasn't too late.\n\nI will give you use of one of my gryphons, a direct flight there.\n\nTalk to me when you are ready to go, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29134] = { title = "A Wrinkle in Time", description = "Listen carefully, {class}, for though we are only beginning, time already grows short and the consequences of our failure are unfathomable.\n\nAn event in the recent past has been obscured from my vision by the most powerful of magics. Its impact, however, has not.\n\nIf action is not taken to change the course of this timeline's future, the outcome is clear.\n\nBrace yourself, mortal, and behold the future of Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[29135] = { title = "All-Seeing Eye", description = "I perceive the questions that burn within your mind and I must confess that I share in your uncertainty... a rare position for one such as I, and a most unsettling one.\n\nAs I scour time to find traces of this obscured event, you must aid me in the creation of an Eye, both to test your worthiness, and to provide an essential tool in the unraveling of this mystery.\n\nVenture into the Plane of Fire, {class}, and gather Eternal Embers. Bring them to me with Sands of Time and I will create the Eye.", objectives = "" }
WordHunterWoW_QuestEN[29137] = { title = "Breach in the Defenses", description = "Lava worms are bursting through the ground behind our lines, breaking our formations and allowing elementals to slip through. You'll find them scattered throughout our entire front to the north, and upon the Ashen Fields further out.\n\nStomp them back into their holes.", objectives = "" }
WordHunterWoW_QuestEN[29138] = { title = "Burn Victims", description = "We have warriors out in the field who are falling wounded, and many of our druids are too busy fighting to give them proper aid. I need you to go to the north, towards the Ashen Fields, and tend their wounds at least enough that they can make it back to safety.\n\nIf you haven't any bandages or healing spells, I had Rayne put together this salve, which should prove sufficient to get them on their feet.", objectives = "" }
WordHunterWoW_QuestEN[29139] = { title = "Aggressive Growth", description = "Our warriors are doing everything they can to hold back the elementals, but their numbers are endless. We need to do something to slow down the assault.\n\nFind some suitable patches of dirt or ash out on the Ashen Fields to our north and plant these seeds. They will grow deadly vines that may slow down our enemies a bit. It's not much, but every bit helps.", objectives = "" }
WordHunterWoW_QuestEN[29141] = { title = "The Harder They Fall", description = "Molten Behemoths have joined the elementals upon the battlefield. They are crushing our front lines. I need you to halt their momentum.\n\nYou'll find the beasts slow and clumsy. They can easily be outmaneuvered, but they will pack a devastating punch if they hit you. Be nimble, {class}.", objectives = "" }
WordHunterWoW_QuestEN[29142] = { title = "Traitors Return", description = "The Druids of the Flame assault our front line, {name}.\n\nThese vile creatures have turned their backs on Elune's teachings and worship instead the Fire Lord, Ragnaros. Twisted by his insane power, they desire nothing more than to bury us in ash.\n\nWe must counter their attack immediately!", objectives = "" }
WordHunterWoW_QuestEN[29143] = { title = "Wisp Away", description = "The fire elementals are pouring out of portals on the far side of the Ashen Fields. We need someone to close them. Cut off some of their reinforcements.\n\nBanishing these kinds of elemental magics is something our wisps are perfectly suited for. One will come with you. Lead it to a portal and keep it alive until it finishes.", objectives = "" }
WordHunterWoW_QuestEN[29144] = { title = "Clean Up in Stormwind", description = "Greetings, {class}!  Are you enjoying Hallow's End?  It seems that in response to our stink bombing the Undercity, the Horde has decided to stink bomb our city.  The stink bombs they drop are more potent than the ones used in the past.  The power of pine won't be enough.  We will need something with a little more power.  Use this Arcane Cleanser to remove the stink bombs from the city.", objectives = "" }
WordHunterWoW_QuestEN[29145] = { title = "Opening the Door", description = "You're a bit late. Hamuul, Malfurion, and some of our esteemed guests have already traveled to the invasion point, atop that cliff.\n\nOur gate to the Firelands is not yet completed, but it will be shortly. The sooner we can break through, the better.\n\nGo on! Hamuul will be expecting you.", objectives = "" }
WordHunterWoW_QuestEN[29146] = { title = "Ridin' the Rocketway", description = "I heard that the goblins, built a crazy road in Azshara and it's just for rockets! Can you imagine? Ever since I heard about it, I've wanted to pay a visit. I asked Matron Battlewail about it and she said it's called the Rocketway!\n\nShe even told me they're working on a prototype rocket with two seats. D'you wanna go there and see if we can try it out? I bet the experimental rocket is near the Secret Lab at the south end of the Rocketway...", objectives = "" }
WordHunterWoW_QuestEN[29147] = { title = "Call the Flock", description = "Today, we have an opportunity to make another assault against one of Ragnaros' greater minions: Millagazor. However, we first need to get some assistance.\n\n<Matoclaw holds up a large, silky feather.>\n\nUse this artifact to invoke the power of Aviana. Once you have done so, travel northwest and gather some of her flock by calling out to them.\n\nOnce you have done so, we may proceed against Millagazor.", objectives = "" }
WordHunterWoW_QuestEN[29148] = { title = "Wings Aflame", description = "<Matoclaw's voice continues to echo within your head.>\n\nMillagazor is a creature of flame, but in many ways, he is not unlike the birds of this land. As such, Aviana's artifacts may still have the power to summon him.\n\nThe fiery portal to the west is where you will find him. Use the quill near the portal's entrance, then prepare for a fierce battle.", objectives = "" }
WordHunterWoW_QuestEN[29149] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "" }
WordHunterWoW_QuestEN[29150] = { title = "Voodoo Zombies", description = "Da people... Dey all zombies, voodoo zombies!  Dis ain't gonna be pretty, {name}.\n\nYou gotta kill dem.\n\nBut once dey killed, dere is a moment where I can save dem.  Change dem back into da person dey were before.\n\nWe gotta act fast.  Da zombies don' rest.", objectives = "" }
WordHunterWoW_QuestEN[29151] = { title = "Bad Supplies", description = "Some of da survivors mentioned food, {name}.  We better check da food supplies.  I gotta a bad feelin' about dis.", objectives = "" }
WordHunterWoW_QuestEN[29152] = { title = "Making Contact", description = "You aren't one of the zombies...\n\nA troll?  I did see one, just before the outbreak...  He warned us, told us to be on our guard... But it was too late.\n\nYour troll friend headed to Booty Bay to warn them...", objectives = "" }
WordHunterWoW_QuestEN[29153] = { title = "Booty Bay's Interests", description = "Look, {name}.  You've helped out plenty so far, but that's not going to be enough.  I need these crazy trolls stopped, or at least stopped from getting into Booty Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll treat you right.", objectives = "" }
WordHunterWoW_QuestEN[29154] = { title = "Booty Bay's Interests", description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted.  Or that it is at least halted at the gates of Booty Bay.\n\nI want action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll make sure you get paid.", objectives = "" }
WordHunterWoW_QuestEN[29155] = { title = "A Shiny Reward", description = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your prize, {class}.", objectives = "" }
WordHunterWoW_QuestEN[29156] = { title = "The Troll Incursion", description = "A group of trolls, claiming to represent the Darkspear tribe, have arrived at Stormwind Harbor.  Our guards are keeping them at bay, for now.\n\nThe Stormwind Harbor Guards are seeking seasoned adventurers for help in removing the trolls from the harbor.  Report to Commander Sharp at Stormwind Harbor.", objectives = "" }
WordHunterWoW_QuestEN[29157] = { title = "The Zandalari Menace", description = "The Zandalar trolls are on the move in Stranglethorn Vale!\n\nIf you wish to help the Darkspear trolls, report to Bwemba in Orgrimmar's Valley of Spirits.", objectives = "" }
WordHunterWoW_QuestEN[29158] = { title = "The Zandalar Representative", description = "{class}!  Heed my call.  Stranglethorn Vale has need of your assistance! Long ago you helped da Zandalar out before.  We not be forgetting your deeds.  It be because of your past help dat we come to you for help.  Come to me at the harbor.", objectives = "" }
WordHunterWoW_QuestEN[29159] = { title = "Pyrorachnophobia", description = "We've fought hard to secure this area, but our foothold is tenuous.\n\nOur scouts report that the area around us is teeming with vicious fire spiders. They are the spawn of the vicious brood widow, Beth'tilac.\n\nHelp us hold our line by clearing the area of Cinderweb Spinners or Cinderweb Creepers. It will drive her mad to see her children slain.", objectives = "" }
WordHunterWoW_QuestEN[29160] = { title = "Egg-stinction", description = "We have a real problem on our hands. Not only are the nearby spiders vicious and predatory, their numbers appear to be endless.\n\nWe need to stop the growth of their army. Cut their heads off in the egg, not on the battlefield.\n\nThe Cinderweb Spinners' eggs are laid among the stone pillars to the north. Collect 20 eggs and bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[29161] = { title = "Those Bears Up There", description = "Oh, raspberries! Just when we had saved the last bear cub from the treetops, the fires returned and scared them again!\n\nI don't know if you know this, but baby bears are precious and soft.\n\nGo to the Whistling Grove, far to the northwest. Climb the trees, grab the bear cubs, and chuck them - gently! - to the soft target in the center of the grove.\n\n<Without warning, Mylune suddenly smashes you against her bosom and begins sobbing.>\n\nLil' b-b-b-baby bears! Save them, {name}!", objectives = "" }
WordHunterWoW_QuestEN[29162] = { title = "Nature's Blessing", description = "<Mylune's voice rings in your head, like the sound of birds chirping.>\n\nI love all creatures of the forest, even spiders, despite the fact that they are icky. But the spiders from the Firelands are worse than icky. They're burny, and don't belong here.\n\nFind the fire portal in the western Regrowth, and use the gem I gave you earlier to force it open. When a fire spider emerges, step on it! Unless it's big. Then, do something {class}y to it.\n\nOh, and use the gem if spider venom makes you woozy!", objectives = "" }
WordHunterWoW_QuestEN[29163] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "" }
WordHunterWoW_QuestEN[29164] = { title = "Perfecting Your Howl", description = "The wolf ancient, Lo'gosh - or, if you prefer, Goldrinn - has many weapons available to him, but always the most underestimated is his howl. Today, we will use this weapon to summon and defeat Lylagar, one of the lieutenants of flame that lurk within the Firelands.\n\nDefeat any of the creatures of flame within the Regrowth, and then use the Fang of the Wolf while standing atop their corpse. Soon, your howl will echo across all of Kalimdor.", objectives = "" }
WordHunterWoW_QuestEN[29165] = { title = "The Call of the Pack", description = "<Matoclaw continues:>\n\nThe easternmost portal of flame is the domain of Lylagar. Stand before the portal, deliver a challenging howl, and then force the fiery beast to submit.", objectives = "" }
WordHunterWoW_QuestEN[29166] = { title = "Supplies for the Other Side", description = "One of the biggest dangers that our druids face when fighting within the Firelands is simple dehydration. Our proveditors spend a significant amount of time preparing canteens for the troops on the other side. We do have other methods, however.\n\nIn the greener thickets to the east, you should still find some blueroot vines which have not yet burned. These plants hold a tremendous amount of water in their roots - and also provide some energy for the weary soldier.", objectives = "" }
WordHunterWoW_QuestEN[29169] = { title = "The Beasts Within", description = "<Maywiki shuffles nervously.>\n\nAfter the fall of Hakkar, the city of the Gurubashi fell into disrepair, and the jungle claimed most of Zul'Gurub for its own.  Several powerful beasts now reside in the cracks and hollows of the ancient city.\n\nWe have seen the powers that the Gurubashi priests wield - they turn the very plantlife against us with their venomous concoctions.  Please, heroes, dispose of these beasts, before they become mindless agents of Jin'Do and his minions!", objectives = "" }
WordHunterWoW_QuestEN[29172] = { title = "The Beasts Within", description = "<Bloodslayer T'ara eyes you for a moment.>\n\nAfter de fall of Hakkar, de city of de Gurubashi fell into disrepair, and de jungle claimed most of Zul'Gurub for its own. Some powerful beasts now be livin' in da cracks an' hollows of de ancient city. \n\nWe seen de powers dem Gurubashi priests wield - dey turn de very plantlife against us wit' venomous concoctions. You tink you be strong? Dispose of dese beasts, before dey become mindless agents of Jin'do.", objectives = "" }
WordHunterWoW_QuestEN[29173] = { title = "Secondary Targets", description = "Da Gurubashi trolls gathered dere most powerful allies ta rebuild Zul'Gurub an' re-take Stranglethorn Vale.\n\nChief among dem be two monstrous trolls: Kaulema da Mover an' Mor'Lek da Dismantler, an' a powerful soul-stealer called Mortaxx.\n\nDey don't be leaders of da Gurubashi, but killing dem powerful minions gonna help us prevent da rise of da Gurubashi.", objectives = "" }
WordHunterWoW_QuestEN[29174] = { title = "Break Their Spirits", description = "A city like Zul'Gurub is similar to one of the many towering trees you see nearby.\n\nThe trunk may be thick, and the canopy vast and leafy, but without nutrients from the roots far below, the tree will wither and fall.\n\nJin'Do's army is fed largely by the actions of two minor Gurubashi trolls.  Sever these roots, and the city will fall all the easier.", objectives = "" }
WordHunterWoW_QuestEN[29175] = { title = "Break Their Spirits", description = "A city like Zul'Gurub be similar ta one of de many towering trees you see nearby.\n\nDe trunk may be thick, and de canopy vast and leafy, but without nutrients from de roots far below, de tree gonna wither and fall.\n\nJin'do's army be fed largely by de actions of a couple a' minor Gurubashi trolls.  Sever dem roots, and de city gonna fall.", objectives = "" }
WordHunterWoW_QuestEN[29176] = { title = "The Fallen Chieftain", description = "Matron Battlewail says that when Cairne Bloodhoof died, the Horde lost a 'voice of wisdom'. I don't know what that means, but I always wanted to meet him. Some of the other orphans even have his hoofprint.\n\nWould you take me with you to Mulgore? Our tutor says tauren bring their dead to a place called Red Rocks to honor them. We should go there and see if we can find Cairne.", objectives = "" }
WordHunterWoW_QuestEN[29177] = { title = "Vigilance on Wings", description = "The agents of Twilight continue their assault within this pocket of the Firelands. We must not let our offensive fall! Take wing, and destroy as many of those lancers as you can!\n\nDo not forget to pick up and equip your lance first.", objectives = "" }
WordHunterWoW_QuestEN[29179] = { title = "Hostile Elements", description = "The elementals continue to press on us, and I do not expect them to subside any time soon.\n\nYou'll find them pouring across the Ashen Fields to the north. Thin their ranks.", objectives = "" }
WordHunterWoW_QuestEN[29181] = { title = "Druids of the Talon", description = "Skylord Omnuron and his Druids of the Talon have been a fearsome force for us back in Hyjal. I know that they prefer the familiar skies of that battlefield, but the time may come when we need them here nonetheless.\n\nIf you get your hands on enough marks, you should appeal to Omnuron that his druids should be on the main front. Omnuron watches out for his own, but he also understands the importance of this effort.", objectives = "" }
WordHunterWoW_QuestEN[29182] = { title = "Flight of the Storm Crows", description = "Many of the Druids of the Talon have made their way to the Molten Front, at your beckoning. You should go to Skylord Omnuron at Malfurion's Breach and see how their wings are faring in those burning skies.", objectives = "" }
WordHunterWoW_QuestEN[29185] = { title = "Daily Tier 2 Heroic (1st)", description = "", objectives = "" }
WordHunterWoW_QuestEN[29186] = { title = "The Hex Lord's Fetish", description = "Dis new warlord of da Amani, he be nothin' but an overgrown brute without da protection of a strong witch doctor and he has just dat.\n\nDa new warlord's ally be Hex Lord Malacrass, da most feared witch doctor to walk among da Amani in decades. Without da hex lord's say-so, Daakara won't be submitting his people to da control of da Zandalari.\n\nDefeat Hex Lord Malacrass, bring me his favorite fetish, and I be seein' that ya get a fittin' reward.", objectives = "" }
WordHunterWoW_QuestEN[29189] = { title = "Wicked Webs", description = "Some of our scouts have not reported back for duty. We fear they have succumbed to the deadly spiders in the vicinity.\n\nHope may not be lost, however. The spiders often wrap up their live prey in cocoons for later consumption.\n\nGo search the pillars to the north for cocooned victims. You may yet be able to save some of our brethren.", objectives = "" }
WordHunterWoW_QuestEN[29190] = { title = "Let's Go Fly a Kite", description = "The other day, when some of us were out with the matron, I saw a goblin pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time.\n\nI think the goblin's name was Blax Bottlerocket or something. If we can find him, could we get some kites and fly them together? I saw him pushing his cart around the Drag.", objectives = "" }
WordHunterWoW_QuestEN[29191] = { title = "You Scream, I Scream...", description = "There's a brand new ice cream shop in Orgrimmar, and it's not just any old ice cream either. This ice cream is made by a crazy goblin mage! You don't think it's going to disappear if I don't finish it in fifteen minutes, do you?\n\nI bet it tastes really good. Let's go try it!\n\nI heard some of the other kids talking about it, and they were saying the store is called the Cone of Cold and it's in the Orgrimmar Embassy.", objectives = "" }
WordHunterWoW_QuestEN[29192] = { title = "The Wardens are Watching", description = "We must tread carefully, {class}. Fandral's Druids of the Flame practice their fiery magic beyond the pillars to the north.\n\nI need you to capture one of those druids alive for questioning. We must seize every opportunity to learn of their plans.\n\nOne of my wardens will accompany you. Follow her instructions if you wish to survive.", objectives = "" }
WordHunterWoW_QuestEN[29193] = { title = "On a Wing and a Prayer", description = "Time well spent, mortal.\n\nWhile you struggled in the Plane of Fire, my watchers and I were able to determine when and, most importantly, where our vision was obscured.\n\nWe discovered that the shroud was placed over the Nexus, far to the north in the realm of the blue dragonflight.\n\nI have attuned the Timeless Eye to show you the occurrences that remain hidden to us here.\n\nBring it to Coldarra at once and seek out a place suitable for its activation.\n\nGo, child. Time is of the essence...", objectives = "" }
WordHunterWoW_QuestEN[29194] = { title = "Through a Glass, Darkly", description = "<Tarecgosa listens as you explain your presence in Coldarra.>\n\nYour tale rings true, {class}. Much has changed since the death of Malygos - little of it for the better.\n\nI know of the device you carry, and I recognize Anachronos' magic in its creation. There is but one place in all of Coldarra that would allow this Timeless Eye to be used discreetly.\n\nYou will require my assistance if you hope to succeed. Speak with me again inside the Nexus and you shall have it.", objectives = "" }
WordHunterWoW_QuestEN[29195] = { title = "A Ritual of Flame", description = "We appear to have everything under control. Our invasion portal to the Firelands will be opened momentarily, and the elementals have not put up much fight.\n\nAssist our druids by dispatching the last few of these elementals. Then, once the gate has been opened, we can make our move.", objectives = "" }
WordHunterWoW_QuestEN[29196] = { title = "To the Sanctuary!", description = "We should not worry about this \"Druid of the Flame\" for the time being. We must be concerned with the continuance of our operation.\n\nReturn to Matoclaw at the Sanctuary of Malorne. If Ragnaros was prepared for our arrival, then I anticipate that his forces will launch a counterattack soon.", objectives = "" }
WordHunterWoW_QuestEN[29197] = { title = "Caught Unawares", description = "Our invasion plan looks to have backfired. Several of our birds have already reported in, speaking of fires breaking out across the vales of central Hyjal.\n\nNow, many of our druids are stranded out in the field, unprepared for such a large-scale attack. Thisalee was near Ashen Lake, and several others were out in the Regrowth, to the northeast.\n\nGo, {name}! Find them, and make sure that they do not succumb to this backdraft!", objectives = "" }
WordHunterWoW_QuestEN[29198] = { title = "The Sanctuary Must Not Fall", description = "Malfurion is working on a miracle for us. He believes that, in this time of peril, he can resurrect Malorne to protect the Sanctuary. I have faith in him.\n\nIn the meantime, we need to hold this perimeter. Stand by, and make sure no harm befalls my fellow arch druid.", objectives = "" }
WordHunterWoW_QuestEN[29199] = { title = "Calling for Reinforcements", description = "We suffered heavy losses during the backdraft after our invasion attempt. Our second attempt cannot fail.\n\nWe need reinforcements before we attempt another invasion. Please, {name}, work with Matoclaw to obtain enough resources to afford reinforcements. Then, we take our second and final stab at the Firelands.", objectives = "" }
WordHunterWoW_QuestEN[29200] = { title = "Leyara", description = "Before we depart, {name}, I have another matter to which you should attend.\n\nA Druid of the Flame has been spotted in the ruins to the northwest. I suspect it is the same one that attacked us at the portal several days ago. Now would be an ideal time to see what it is that she truly wants... and if necessary, dispose of her.\n\nSee to this flame druid, then we can continue on our planned course.", objectives = "" }
WordHunterWoW_QuestEN[29201] = { title = "Through the Gates of Hell", description = "There will be time to mourn for Hamuul later. His is the first of many inevitable casualties in this war.... but our attack cannot wait, nor should the momentum we have gained over the last several days be wasted.\n\nThe portal atop Nordune Ridge is now open. Our reinforcements are prepared, and they await only my order to pass through the portal.\n\nWe will meet again on the other side of the portal. Once there, we shall ensure that our foothold is secure.", objectives = "" }
WordHunterWoW_QuestEN[29202] = { title = "The Fate of Runetotem", description = "I apologize for speaking curtly with you earlier. The loss of Hamuul was shocking to me, and difficult to cope with.\n\nThey brought in his body while you were away. He is alive, but - as you might imagine - he is very, very badly burned.\n\nThe scars are deep. He may not live.\n\nI have arranged for some of our finest healers to attend to him. If it is not too much to ask, would you speak with Dorda'en Nightweaver? He and his fellow attendants may need your help.", objectives = "" }
WordHunterWoW_QuestEN[29203] = { title = "Into the Depths", description = "Leyara has been spotted in the Igneous Depths. A group of Shadow Wardens has cornered her.\n\nGo there immediately. I will join you as soon as I make one necessary preparation.", objectives = "" }
WordHunterWoW_QuestEN[29205] = { title = "The Forlorn Spire", description = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise.\n\nGo there and escort one of her druids to the tower with any forces that she can spare. You'll have quite a fight ahead of you - make sure the druid lives to see the end of it or they'll not be able to seize the tower.", objectives = "" }
WordHunterWoW_QuestEN[29206] = { title = "Into the Fire", description = "Skylord Omnuron and his druids are seeking to push through the Furnace to our northwest. They've been able to fly over the dangers, but they really need someone on the ground to help them secure the territory past the fire... someone like you.\n\nIf you want to aid the Druids of the Talon, wait for one of Omnuron's Windcallers to start pushing through the fire, stay close to him, and keep him safe from any attackers within the flames.", objectives = "" }
WordHunterWoW_QuestEN[29208] = { title = "An Old Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[29210] = { title = "Enduring the Heat", description = "Shalis has gone with one of our druids to stop a Druid of the Flame that is performing a summoning ritual in the Igneous Depths, below us. They have been tasked with killing the druid, but I need you to stop the ritual.\n\nYou'll find the entrance to the cavern east of the Magma Springs. Once inside, you'll see 8 blue runes spread throughout the cavern. You can use these runes to protect you from the fiery creatures, but you need to stamp all of them out to end the ritual. You will need to be swift.", objectives = "" }
WordHunterWoW_QuestEN[29211] = { title = "Solar Core Destruction", description = "The fight has taken us to Fandral's doorstep. His druids are channeling energies of the Firelands into a vessel called the Solar Core.\n\nShould this vessel detonate on Azeroth, none of us will have a home to return to.\n\nWe need to strike at the Solar Core now, while it is still vulnerable. You can find the infernal device to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[29213] = { title = "How's the Hunter Holding Up?", description = "Tings ain't looking good.  Dat panther was under some powerful magic.  We better check on dat hunter an' see how he be doin'.", objectives = "" }
WordHunterWoW_QuestEN[29214] = { title = "The Shadow Wardens", description = "The Shadow Wardens are back in the Regrowth. I know that they take the loss of Fandral from their custody very seriously, so it wouldn't take much prodding to bring them to the Firelands to hunt the Druids of the Flame, and perhaps aid us otherwise in the process.\n\nShould you come upon enough marks, you should seek out Captain Saynna Stormrunner at the Sanctuary of Malorne and secure her aid.", objectives = "" }
WordHunterWoW_QuestEN[29215] = { title = "The Hunt Begins", description = "The Shadow Wardens have joined the fight at the Molten Front, on your request. You should find Captain Saynna Stormrunner and see to it that they've found a way to best apply their skills.", objectives = "" }
WordHunterWoW_QuestEN[29217] = { title = "The Captive Scouts", description = "After we arrived, I dispatched my scouts to learn more about da Zandalari presence here in Zul'Aman. Many returned with useful information, but four still be missin'. If we do not act quickly, da new warlord's lieutenants will offer dem as sacrifices in honor of da Zandalari emissaries.\n\nFind my scouts, {name}, and free dem before da priests offer dem as sacrifices!", objectives = "" }
WordHunterWoW_QuestEN[29218] = { title = "Marks of the World Tree", description = "", objectives = "" }
WordHunterWoW_QuestEN[29219] = { title = "Bwemba's Spirit", description = "Dese be troublin' times for us Darkspear.  Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we can.  But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn da people.  But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI gonna bind my spirit wit' ya.  When ya get to Stranglethorn, I be able to aid ya.", objectives = "" }
WordHunterWoW_QuestEN[29220] = { title = "To Bambala", description = "Da first place we check gonna be da place most likely to be attacked first, Bambala.\n\nBambala be dangerously close to da troll city Zul'Gurub... It make for an easy target.\n\nMaybe we find da emissary dere.  Hopefully it ain't too late.", objectives = "" }
WordHunterWoW_QuestEN[29221] = { title = "Serpents and Poison", description = "Da warning helped, {name}.\n\nWe gathered more Headhunters to help defend.  But Headhunters... Dey not used to hunting heads on serpents.  So we soon be overwhelmed.  Dese serpents, dey seem to come from everywhere.  An' it probably only gonna get worse.\n\nHelp us and kill da serpents and have Bwemba use her mojo to cure da ones dat are sick from poison.", objectives = "" }
WordHunterWoW_QuestEN[29222] = { title = "Spirits Are With Us", description = "Dere was something about da way da serpents attacked, {name}.  Something unnatural...  Even da poison had a hint of some bad mojo.\n\nDere be a shrine near here wit' a bonfire.  We can use dat to perform a ritual.\n\nWhatever be makin' dese serpents attack, dey probably still watchin' over dem.\n\nDa only problem, {name}, is dat I only be here in spirit form.  I need you to be my hands.  I need you to go to da fire an' prepare it for me.  Den I'll handle da rest.", objectives = "" }
WordHunterWoW_QuestEN[29223] = { title = "Nesingwary Will Know", description = "So da Gurubashi be on da rampage an' dey usin' serpents to lead da charge.\n\nYou know who be good at keepin' da animal population in check?  Da hunters at Nesingwary's Expedition.\n\nHead over dere and see how dey doin'.  See if dey know a good way to get rid of da serpents.\n\nIf dey don't know, den you gotta at least warn dem dat dese serpents, it ain't all natural.", objectives = "" }
WordHunterWoW_QuestEN[29225] = { title = "Actionable Intelligence", description = "<Tarecgosa listens intently as you describe your vision.>\n\nImpossible!\n\nNot even Arygos would dare to go to such lengths.\n\nI do not question your integrity, {class}, but you must understand - your mortal mind can easily be deceived.\n\nRegardless, Kalecgos must be informed of these events. You must travel to Nordrassil at once to seek him out.\n\nI shall remain here to conceal the evidence of our activities. Speak of this to no one else!", objectives = "" }
WordHunterWoW_QuestEN[29226] = { title = "Track the Tracker", description = "We've been fending off serpents for days now, {name}.  But the serpents are nothing compared to what else is out in that jungle.\n\nWe hunters are being hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer headed off to the east, perhaps you can find them there.", objectives = "" }
WordHunterWoW_QuestEN[29227] = { title = "The Hunter's Revenge", description = "The beast that's been hunting us... I've been hunting it.\n\nWe call him Mauti.  He's a clever one.  But he made a grave mistake when he killed my brother.  Now that mistake is going to cost him.  Ol' Direhammer has got his scent.\n\nI've noticed him roaming just above Kurzen's Compound.  If we act fast, we can take him down.\n\nAre you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29228] = { title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[29229] = { title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[29230] = { title = "Mauti", description = "I got da feeling dat somethin' ain't right wit' dat panther, {name}.  It ain't natural.  I gonna need to perform some rituals over da body.  Put Mauti down, an' den let's see what we can find out, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29231] = { title = "How's the Hunter Holding Up?", description = "Tings ain't looking good.  Dat panther was under some powerful magic.  We better check on dat hunter an' see how he be doin'.", objectives = "" }
WordHunterWoW_QuestEN[29232] = { title = "Bury Me With Me Boots...", description = "Ah... It's you, {name}.  Mauti... He's dead?  Then my brother has been avenged.  I've only one request from ya... This scamp here, he's been pawing at me bare feet.  No dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.", objectives = "" }
WordHunterWoW_QuestEN[29233] = { title = "Warn Grom'gol", description = "Dis death ain't be in vain, {name}.  We figure out dat Kilnara be on da prowl.  Tings don't look good.\n\nWe better check out Grom'gol Base Camp to da west.  Maybe we find my contact dere.", objectives = "" }
WordHunterWoW_QuestEN[29234] = { title = "Delegation", description = "I am duty-bound to look into your claims immediately, {race}, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the World Tree's branch.", objectives = "" }
WordHunterWoW_QuestEN[29235] = { title = "Defend Grom'gol", description = "I hope you like to fight, {name}.  Your troll friend has been through here and warned us that the Gurubashi were on the rampage.  I never thought the battle would be this glorious though.\n\nCome, join in our fight and let's show these Gurubashi trolls the might of the Horde!", objectives = "" }
WordHunterWoW_QuestEN[29236] = { title = "To Hardwrench Hideaway", description = "Bwemba...  Is that you?\n\nYour contact was here.  He was eager to get to the next location and warn them.  And really, who could blame him?  I gave him use of a wyvern to reach the goblins of Hardwrench Hideaway, in the Cape of Stranglethorn.\n\nI will give you use of one of my wyverns to reach Hardwrench.\n\nTalk to me when you are ready to go, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29237] = { title = "Voodoo Zombies", description = "Da people... Dey all zombies, voodoo zombies!  Dis ain't gonna be pretty, {name}.\n\nYou gotta kill dem.\n\nBut once dey killed, dere is a moment where I can save dem.  Change dem back into da person dey were before.\n\nWe gotta act fast.  Da zombies don' rest.", objectives = "" }
WordHunterWoW_QuestEN[29238] = { title = "Bad Supplies", description = "Some of da survivors mentioned food, {name}.  We better check da food supplies.  I gotta a bad feelin' about dis.", objectives = "" }
WordHunterWoW_QuestEN[29239] = { title = "Nordrassil's Bough", description = "Much has transpired since last we spoke.\n\nI have taken it upon myself to visit the Nexus and recover Anachronos's artifact, but not before using it for myself. Now I too have witnessed that which you have seen.\n\nBefore discussing the matter further, allow me to express my gratitude to you for your assistance, both here and in the Plane of Fire.", objectives = "" }
WordHunterWoW_QuestEN[29240] = { title = "Emergency Extraction", description = "Now, back to the matter at hand...\n\nI am convinced that the vision in the Nexus is one of Deathwing's illusions designed to bring conflict into our flight at a very fragile time.\n\nThe Worldbreaker would only be strengthened were we to fall to infighting.\n\nStill, a gnawing sense of unease tempts me to take a path of caution.\n\nIt would be wise for me to take Tarecgosa and withdraw until the time of choosing.", objectives = "" }
WordHunterWoW_QuestEN[29241] = { title = "Break the Godbreaker", description = "<Bloodslayer Zala points at the temple in the distance.>\n\nWhen Jin'do was last ripped from dis world, he survived as a shade, weak and broken, in da spirit world.\n\nBut Jin'do always had power over da spirits.  One by one, he broke dem to his will, and wit' each soul devoured, Jin'do got closer ta' rippin' a hole through to dis world.\n\nTa be here now...\n\nDa spirits be wit' us, we must end Jin'do.", objectives = "" }
WordHunterWoW_QuestEN[29242] = { title = "Putting a Price on Priceless", description = "Listen, friend.  I don't know you, and you don't know me.  But as long as we're both here, there's something Revilgaz wanted me to mention.\n\nMaybe you're taking a stroll through this troll-infested jungle-ocalypse.  Maybe you happen to find a priceless troll artifact or two.  Maybe you bring it back to me and I accidentally leave behind a little present for ya'.\n\nIf you must know, it's for a project.  And no, you can't ask what the project is.", objectives = "" }
WordHunterWoW_QuestEN[29243] = { title = "Strike at the Heart", description = "One of Ragnaros' Lieutenants has shown itself at Ragnaros' Reach.  It is time to strike. Captain Saynna has requested that you be there to help see the fight through.\n\nWitherbranch and some others will have joined the battle by the time you arrive.  You should make haste to the northwest and find them.", objectives = "" }
WordHunterWoW_QuestEN[29245] = { title = "The Mysterious Seed", description = "A small, dried acorn has fallen out of the Flame Druid's robe.\n\nWhy would a Druid of the Flame be carrying it around?\n\nPerhaps someone at Malfurion's Breach would like to see it.", objectives = "" }
WordHunterWoW_QuestEN[29246] = { title = "Relieving the Pain", description = "The Arch Druid has an immense tolerance for pain. I've treated burn victims that spend twenty-two hours a day screaming in pain, and their burns weren't even half as bad as what Hamuul has suffered.\n\nNevertheless, I can sense that he is in greater discomfort than normal today. Bring me the hearts of the large fire elementals to the southeast. I can use them to prepare a soothing salve for our patient.", objectives = "" }
WordHunterWoW_QuestEN[29247] = { title = "Treating the Wounds", description = "We have an ample supply of medical supplies here at the Sanctuary, but we mustn't lose sight of the fact that we are at war. Hamuul isn't the only person who has need of bandages.\n\nThe fiery behemoths that roam Sethria's Roost wear flame-resistant wrappings that will serve Hamuul as ably as any bandage. Bring me those wrappings, and I will prepare them for use on the Arch Druid.", objectives = "" }
WordHunterWoW_QuestEN[29248] = { title = "Releasing the Pressure", description = "Having been burned so badly, Arch Druid Hamuul is suffering from edema - swelling of the body's tissues. It takes a great deal of his attendants' effort to keep his swelling down enough for him to breathe.\n\nNormally, to reduce this swelling, we make cuts in his flesh, but he is weak, {name}. I cannot cut him today. I need your help.\n\nFlamewaker scales will aid with the swelling, but you need a lot of them.", objectives = "" }
WordHunterWoW_QuestEN[29249] = { title = "Planting Season", description = "The acorn seems to be unharmed.\n\n<Avrilla shrugs.>\n\nNo point in beating around the bush. Let's plant it and see what comes out.\n\nLuckily for you, we brought some leftover soil with us to help establish our base.\n\nYou'll find the soil at the graveyard directly east.", objectives = "" }
WordHunterWoW_QuestEN[29250] = { title = "Making Contact", description = "You aren't one of the zombies...\n\nA troll?  I did see one, just before the outbreak...  He warned us, told us to be on our guard... But it was too late.\n\nYour troll friend headed to Booty Bay to warn them...", objectives = "" }
WordHunterWoW_QuestEN[29251] = { title = "Booty Bay's Interests", description = "Look, {name}.  You've helped out plenty so far, but that's not going to be enough.  I need these crazy trolls stopped, or at least stopped from getting into Booty Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll treat you right.", objectives = "" }
WordHunterWoW_QuestEN[29252] = { title = "Booty Bay's Interests", description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted.  Or that it is at least halted at the gates of Booty Bay.\n\nI want action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll make sure you get paid.", objectives = "" }
WordHunterWoW_QuestEN[29253] = { title = "A Shiny Reward", description = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your prize, {class}.", objectives = "" }
WordHunterWoW_QuestEN[29254] = { title = "Little Lasher", description = "The little red flower wiggles its tendrils happily. It seems to like you!\n\nPerhaps Avrilla would like to see what grew out of the acorn.", objectives = "" }
WordHunterWoW_QuestEN[29255] = { title = "Embergris", description = "The Crimson Lasher has developed some cracking blisters on its vines. Without treatment, this condition could be life threatening.\n\nLuckily, the Charred Soldiers and Charred Vanquishers in the area produce a waxy substance known as Embergris, which should soothe the Lasher's pain.\n\nBring me some of this substance, and kill those nasty fire elementals while you're at it.", objectives = "" }
WordHunterWoW_QuestEN[29257] = { title = "Steal Magmolias", description = "We've discovered a new species of flower growing in the Magma Springs to the north. Amazingly, they sustain themselves in pure molten lava!\n\nPlease go and retrieve some specimens for me. I'm sure that further study of these plants will shed some light on your little friend here.\n\nSpeaking of which, he seems quite eager to go with you. Let's hope he behaves himself.", objectives = "" }
WordHunterWoW_QuestEN[29261] = { title = "Zul'Aman Voodoo", description = "The maker of this voodoo pile perished in the process.  Perhaps if you could finish it, the spirits would protect you instead....", objectives = "" }
WordHunterWoW_QuestEN[29262] = { title = "Zul'Gurub Voodoo", description = "This potent pile of voodoo witchery emanates strong mojo...", objectives = "" }
WordHunterWoW_QuestEN[29263] = { title = "A Bitter Pill", description = "As far as I'm concerned, there's no problem that can't be solved with bombs. And if a bomb doesn't solve your problem on the first try... use a bigger bomb.\n\nSo there's this big worm that's been eating people near the lava pools up north. Search for breath bubbles to find it. Attack it until it prepares to bite, then place this bomb down in front of it. Then sit back and watch the fireworks.\n\nHmm... there was one other thing I wanted to say... oh yeah! Don't get eaten.", objectives = "" }
WordHunterWoW_QuestEN[29264] = { title = "Flamewakers of the Molten Flow", description = "Of all Ragnaros' minions, the flamewakers appear to be the most devoted. Most of them dwell within this cave, preparing for another attack. Our foothold may be strong, but we will not tolerate any surprise attacks from these worms.\n\nNo, we will strike first.\n\nTear them apart, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29265] = { title = "Fire Flowers", description = "My fellow druid, Choluna, has asked us to collect any specimens of plant life that we might find here in the Firelands...\n\n...I don't know whose idea it was to bring scholars to a warfront.\n\nNevertheless, you will already be in the cave - killing things - so be on the lookout for anything growing out of the ground.", objectives = "" }
WordHunterWoW_QuestEN[29267] = { title = "Some Good Will Come", description = "So much violence, so much death.  Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it.\n\nWill you take a pause from the violence to help care for a panther cub?", objectives = "" }
WordHunterWoW_QuestEN[29268] = { title = "Some Good Will Come", description = "So much violence, so much death.  Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it.\n\nWill you take a break from the violence and help care for a panther cub?", objectives = "" }
WordHunterWoW_QuestEN[29269] = { title = "At One", description = "I was charged with her protection, yet it was she who sacrificed herself for my sake.\n\nI cannot bear to lose her, {name}. I must make a solemn request of you.\n\nNever has a mortal borne the essence of a true dragon, but with your permission I would make an exception.\n\nPlease, while there is life in her, will you allow me to bind Tarecgosa to you? ", objectives = "" }
WordHunterWoW_QuestEN[29270] = { title = "Time Grows Short", description = "Tarecgosa is bound to you, {name}, but only temporarily. An aspect's power is required to permanently seal her essence.\n\nMalygos's successor will not be chosen until Azeroth's moons next eclipse, and the bond you share will not last until then.\n\nFortunately, there is a way to buy us the time we need. Powerful elements exist that can extend the ritual's effects. Some of these can be found in the Plane of Fire, with which you've become familiar.\n\nObtain them, {class}, and sustain Tarecgosa until the eclipse.", objectives = "" }
WordHunterWoW_QuestEN[29272] = { title = "Need... Water... Badly...", description = "Need... water... badly...", objectives = "" }
WordHunterWoW_QuestEN[29273] = { title = "How Hot", description = "The fire hawks of Fireplume Peak can withstand incredible temperatures. While you'll often find them circling the skies above, they're also known to swim in molten lava.\n\nIsn't that right, Anren?\n\nWe'd like to know just how hot that lava can get. Fireplume Peak has three large lava pools. Use this to measure the temperature of each.", objectives = "" }
WordHunterWoW_QuestEN[29274] = { title = "Hounds of Shannox", description = "On the Firelands' largest island, our troops have been having trouble against Shannox, the flamewaker hunter. Not only does he have impeccable aim, but he keeps trained hounds that give our troops no end of trouble.\n\nTholo, in all his wisdom, thinks it would be a good idea to study the biology of these hounds. I, of course, agree with Tholo.\n\nYou will find several hounds in the Molten Flow, beneath the Furnace. We will need their ashes to study.", objectives = "" }
WordHunterWoW_QuestEN[29275] = { title = "Fandral's Methods", description = "The Druids of the Flame... an order of druids that, up until a few weeks ago, Tholo and I had never even heard of. Now, under the leadership of Fandral Staghelm, they threaten our mission's success with their mastery of fire.\n\nIt would appear that they store some supplies in the Igneous Depths, to the northeast. Perhaps, if we can get some of those supplies, we will have more luck when we take the fight to Fandral.", objectives = "" }
WordHunterWoW_QuestEN[29276] = { title = "The Flame Spider Queen", description = "The Widow's Clutch, to the northeast, is named after Beth'tilac, the enormous queen of the flame spiders. Her webs and her poison are a nagging threat to our main offensive force.\n\nWe believe that if we study the flame spiders here on the Molten Front, we can use that information to find success against Beth'tilac. Use whatever methods you can to gather their venom and their web fluid, then return to my trusted friend Anren.", objectives = "" }
WordHunterWoW_QuestEN[29278] = { title = "Living Obsidium", description = "Have you seen those fireballs falling out of the sky? I saw one crash in the fields to the north, and the rock that landed was made of pure Living Obsidium!\n\nI can use the material to craft ultra-sturdy heat proof armor and weapons for our troops. Can you bring me a lode?\n\nGo to the Magma Springs and touch one of the magnetic stones. Just watch where you're standing when the rain of fire hits, and gather up the rocks before they crumble from the impact.", objectives = "" }
WordHunterWoW_QuestEN[29279] = { title = "Filling the Moonwell", description = "We've constructed this moonwell, but it serves little purpose until it is filled with the sacred waters of the Well of Eternity.\n\nWith an active moonwell, we would be able to bless our food stores, and we may also be able to use the blessing to offer you some protection from fire as well.\n\nWhen you've obtained enough marks, speak to Matoclaw at the Sanctuary of Malorne. She'll be able to secure transport of the sacred waters.", objectives = "" }
WordHunterWoW_QuestEN[29280] = { title = "Nourishing Waters", description = "I have dispatched the sacred moonwell waters to Malfurion's Breach, as you requested. Ayla is well trained in tending to them. You should return to her and see the boons she weaves for you there.", objectives = "" }
WordHunterWoW_QuestEN[29281] = { title = "Additional Armaments", description = "These druids be lackin' the tools ta properly handle the job out 'ere. I got meself a buddy back at day ol' stag shrine through the portal though. If we were ta be gettin' reunited, we'd sure have some real toys ta use against ol' Ragboy and 'is cronies.\n\nTake some of dem mark things an' go find Matoclaw. Ask her fer Ricket. We need'r here so we can be causin' some real trouble. ", objectives = "" }
WordHunterWoW_QuestEN[29282] = { title = "Well Armed", description = "Ricket should be at Malfurion's Breach with Damek, as you requested. I'm not sure you fully know what you're getting into with those two though.\n\nSpeaking of which, you should probably go check on them... make sure they haven't managed to blow up the Sentinel Tree itself. As long as you keep them busy with the elementals, the chances of \"accidents\" at the breach should lessen dramatically.", objectives = "" }
WordHunterWoW_QuestEN[29283] = { title = "Calling the Ancients", description = "The ancients await in Hyjal. The Firelands will prove a dangerous place for them considering their... composition, but their strength will be of great use to us if we are to face any of Ragnaros' lieutenants.\n\nGather your marks, and seek out Elderlimb at the Sanctuary of Malorne. If they are to march with us, he would be the one leading them through the portal.", objectives = "" }
WordHunterWoW_QuestEN[29284] = { title = "Aid of the Ancients", description = "The ancients have seen the value of your wisdom, and have set root at Malfurion's Breach. You should seek out Elderlimb. I am certain he would like to hear from you.", objectives = "" }
WordHunterWoW_QuestEN[29285] = { title = "Alignment", description = "The time of choosing has arrived, {name}.\n\nWhile only members of the blue dragonflight may attend, Tarecgosa's binding makes your presence requisite.\n\nI must ask that you take on her form and vote on her behalf.\n\nDo not tarry. The moment of the eclipse draws near....", objectives = "" }
WordHunterWoW_QuestEN[29287] = { title = "Peaked Interest", description = "These fire hawks are beings of fire, but they exhibit much of the same behavior that we've seen in birds back home. It makes me wonder from where they originate.\n\nBack to the point - I think we might be able to train them. Domesticate them if you will. Use them against our enemies.\n\nI'd like you to retrieve one of their eggs from the top of Fireplume Peak. If you can bring it back to me safely, I will see to the rest.", objectives = "" }
WordHunterWoW_QuestEN[29288] = { title = "Starting Young", description = "Our scouts are bringing back reports of fire hawk hatchlings all over the peak... their eggs must have hatched very recently. Better yet, it seems that they're extremely docile.\n\nI know it may sound a strange and perhaps unsavory request, but if you were able to bring some of those hatchlings back to me, I might be able to train them to aid us in our war efforts.\n\nAre you willing?", objectives = "" }
WordHunterWoW_QuestEN[29289] = { title = "Mother's Malice", description = "Unsurprisingly, their matriarch has taken offense to us taking her young to train for our own uses. It's understandable... and a bit tragic actually. We are very much the villains in this exchange.\n\nNow is not the time for such thoughts. These creatures are beings of fire, and on more than one occasion, they've claimed the lives of our kin. With their matriarch angered, the danger has grown immensely.\n\nI need someone to quiet her rage, and I fear you may be the most capable.", objectives = "" }
WordHunterWoW_QuestEN[29290] = { title = "Fire in the Skies", description = "Look at that! It's incredible! Born less than two days ago and already full grown. Sadly, I suspect their life cycle is similarly short, so we'll have to take advantage of any time we have.\n\nHis training went remarkably well. I want you to be the one to take him out and unleash him on the bulk of the enemy forces gathered near Ragnaros' keep.\n\nShow no mercy, {race}.", objectives = "" }
WordHunterWoW_QuestEN[29293] = { title = "Singed Wings", description = "Many of our Storm Crows have gone ahead to scout the peak and attempt to retrieve some of the fire hawk eggs, but to very little success I'm afraid. The thermals make it nearly impossible to fly safely, and the fire hawks aren't exactly friendly either.\n\nI need you to head over there and rescue any druids that you can. I've got splints, bandages, burn salves, smelling salts... anything you'll need to get them back on their feet, assuming they're still alive. Please hurry and help anyone you can find.", objectives = "" }
WordHunterWoW_QuestEN[29295] = { title = "The Bigger They Are", description = "You're not going to take on fiery behemoths wearing THAT, are you? If you aren't wearing my obsidium crafted goods, you're going to burn right up! And even if you are, you can never have enough of the good stuff.\n\nLook brother, I can craft you the best armor that gold can buy, but I need pure, unsmelted Living Obsidium first.\n\nThe Obsidium Punishers on Fireplume Peak are literally made of the stuff. Go kill them and gather their pieces.", objectives = "" }
WordHunterWoW_QuestEN[29296] = { title = "Territorial Birds", description = "The fire hawks are upset by our continued presence. They're getting extremely hostile, and not just in the usual territorial ways. I worry that if we leave them unchecked, they will soon be joining the assault on our tree, and I'm not sure we're capable of handling that.\n\nGo across the way to Fireplume Peak and do what you have to to keep them in check. I'm far more concerned with our safety right now than theirs, so be decisive about it.", objectives = "" }
WordHunterWoW_QuestEN[29297] = { title = "Bye Bye Burdy", description = "Staghelm's druids are putting up a fierce fight at Wildflame Point to the northeast.\n\nThe druids fly above us in fire crow form, then strike when we least expect it. Worst part is, they know exactly how to stay out of our reach!\n\nWe would be totally helpless, except Damek lent me his trusty harpoon. He says these weapons will fly straight and true even in this super dense air.\n\nTake the dwarf's weapon and shoot some birds out of the sky!", objectives = "" }
WordHunterWoW_QuestEN[29298] = { title = "A Smoke-Stained Locket", description = "This locket has a few small leaf-shaped carvings etched into its face, but any other details have been rubbed away with time, or burned away with fire. It appears to be druidic in nature.\n\nMost druids pass through Moonglade during their training. If anybody can help you decipher where this locket came from, it would be Rabine Saturna of Nighthaven.", objectives = "" }
WordHunterWoW_QuestEN[29299] = { title = "Some Like It Hot", description = "I've been making progress in my research, {name}. Based on what we've witnessed in the local flora, it's quite possible that your Lasher also accepts superheated liquids as a principal source of nutrition.\n\nI'd like you to help me with a little experiment. The Emberspit Scorpions that inhabit the Magma Springs to the north spew out burning pools of fire during combat.\n\nTake the Lasher and observe his reaction to the scorpions' Ember Pools.", objectives = "" }
WordHunterWoW_QuestEN[29302] = { title = "Unlocking the Secrets Within", description = "The initials seem to have worn off of this locket, but I can sense a power within it that suggests only one possible owner:\n\nLeyara, the Druid of the Flame.\n\nStand back, and we shall see what surprises this locket contains.", objectives = "" }
WordHunterWoW_QuestEN[29303] = { title = "Tragedy and Family", description = "You were insightful to bring this locket to me, {name}. I am among the few who know where Valstann's body lays.\n\nYou can find his resting site in a small graveyard, southeast of Astranaar, in Ashenvale. Bring this locket to the site, and it may unlock more memories.\n\nFarewell, {name}, and good luck on your journey.", objectives = "" }
WordHunterWoW_QuestEN[29304] = { title = "The Dogs of War", description = "Our forces are falling beneath an unleashed monstrosity - Charhounds from the molten depths.\n\nThese dogs fear nothing and will not stop until their lust for blood is satisfied. Our forces are barely holding them back.\n\nGo join the defenders in the Ashen Fields or in the Molten Flow. Perhaps you can make a dent in their numbers.", objectives = "" }
WordHunterWoW_QuestEN[29305] = { title = "Strike at the Heart", description = "One of Ragnaros' Lieutenants has shown himself at Ragnaros' Reach, the walled area to our northeast.\n\nI hoped to send you as soon as you returned, but I suspect Witherbranch and some of our forces have already joined the fight by now. You should hurry.\n\nYou should be able to drop down the cliff wall right here and reach them quickly.", objectives = "" }
WordHunterWoW_QuestEN[29307] = { title = "Heart of Flame", description = "You are the first mortal to witness a dragon council, {name}, and among the only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home.\n\nI would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen next we meet, I will be able to suitably thank you for all that you have done.", objectives = "" }
WordHunterWoW_QuestEN[29308] = { title = "Heart of Flame", description = "You are the first mortal to witness a dragon council, {name}, and among the only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home.\n\nI would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen next we meet, I will be able to suitably thank you for all that you have done.", objectives = "" }
WordHunterWoW_QuestEN[29309] = { title = "The Stuff of Legends", description = "It is an honor to make your acquaintance, {race}.\n\nYour deeds echo in the ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[29310] = { title = "The Tipping Point", description = "On the day when Leyara attacked Hamuul, she was waiting near some ruins in Hyjal, northwest of the Regrowth. She acted strangely at the time: calm, silent, and staring off into the distance. Perhaps that location is of some importance to her.\n\nThe locket might react if brought to that location.", objectives = "" }
WordHunterWoW_QuestEN[29311] = { title = "The Rest is History", description = "In her memories, Leyara spoke of Malfurion. The tragedies of her past - at least, in her opinion - are largely due to his actions.\n\nMalfurion must remember Leyara from before she became a Druid of the Flame. You resolve to bring the locket to him in the Firelands. Hopefully he can answer any remaining questions.", objectives = "" }
WordHunterWoW_QuestEN[29312] = { title = "The Stuff of Legends", description = "It is an honor to make your acquaintance, {race}.\n\nYour deeds echo in the ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[29313] = { title = "The Secret to Perfect Kimchi", description = "My family has been making the best kimchi in Darnassus since the city was founded, {name}. The secret is something simple, but it makes all the difference.\n\nWe bury the jars in the ground until it's ready to serve and my latest batch has just reached that point. You can find the jars buried in earthen mounds all over the city. Would you help me gather them while the contents are just right?", objectives = "" }
WordHunterWoW_QuestEN[29314] = { title = "Remembering the Ancestors", description = "The living are not the only ones who require sustenance. One of my duties is to prepare the rice cakes that are left for the ancestors. Normally, my senior apprentice has the honor of taking the cakes to the Temple of the Moon for blessing and then presenting them to the ancestors. Since she is out of the city today, would you mind performing the duty in her place?", objectives = "" }
WordHunterWoW_QuestEN[29315] = { title = "Fungus Among Us", description = "Some chefs complain that our beloved Undercity doesn't boast the ingredients to create truly fine fare.\n\nSuch mewling little cretins. Delicious delights abound!\n\nGather some of the rank, slimy Sewer Caps growing in Undercity's northwest sewer line and return them to me.", objectives = "" }
WordHunterWoW_QuestEN[29316] = { title = "Back to Basics", description = "There are certain things that everyone needs, from the basic household cook to the master chef. One of the city's most important staples is rice flour. Most families keep at least one basket of rice in their houses and the residents of the Craftsmen's Terrace and Tradesmen's Terrace are no different.\n\nI often ask my students to help with the task of pounding rice into flour since it's good practice and an endless task. Why don't you give it a try?", objectives = "" }
WordHunterWoW_QuestEN[29317] = { title = "Fish Head", description = "There was an... incident... with an orc guard and one of Master Apothecary Faranell's abominations.\n\nApparently, the Kor'kron Overseer chopped its head clean off and kicked it into the slime.\n\nFaranell's apprentices searched for hours but they can't find the thing. Care to try fishing it up? I'm sure the old fellow'd be grateful.", objectives = "" }
WordHunterWoW_QuestEN[29318] = { title = "Ribs for the Sentinels", description = "One of my responsibilities is to feed the sentinels of Darnassus while they're on duty. It's a time-consuming task, but one I'm happy to undertake. It's also a great way to practice your skills. Would you mind helping me with today's meal? Simply take these ribs, cook them near a stove or fire, and distribute them to sentinels throughout the city.", objectives = "" }
WordHunterWoW_QuestEN[29319] = { title = "Tadpole Terror", description = "Some of our apothecaries took to dumping their more volatile waste chemicals into Stillwater Pond and... well, let's just say that no one wants to know how big mutant flesh-eating toads can grow.\n\nWould you consider fishing up some giant flesh-eating tadpoles before it gets to that? Just don't try to handle them with your bare hands.", objectives = "" }
WordHunterWoW_QuestEN[29320] = { title = "Like Pike?", description = "You've fished in Brightwater Lake, yes?\n\nThe prize catch there is one of the lake's massive corpse-fed pikes. However, they only bite on a very specific type of bait... corpse worms.\n\nSearch the graves in the courtyard up top and you should find some.", objectives = "" }
WordHunterWoW_QuestEN[29321] = { title = "Happy as a Clam Digger", description = "It seems like everyone I know loves clams, but I can't stand them! They're smelly and slimy, and harvesting them means digging through mud. Give me a fishing pole and some bait any day.\n\nStill, I want to surprise my brother with a bucket of fresh clams. I'd reward you if you were willing to gather those clams for me.\n\nJust go through the portal to Rut'theran Village and look for the clams in the shallows near the shore.", objectives = "" }
WordHunterWoW_QuestEN[29322] = { title = "Time for Slime", description = "It takes a special sort of fisherman to reap the bounty of Undercity's burbling slime troughs. Think you can handle gathering some of the squirming, sentient slime mold slithering about down there?\n\nYou can try to fish them up, but they're wily; you might be better off just diving into the ooze and grabbing them.\n\nRemember, they're only useful alive and intact... who'd want to eat a dead slime mold?! Disgusting.", objectives = "" }
WordHunterWoW_QuestEN[29323] = { title = "Stocking Up", description = "We've used up most of our food stores in taking care of refugees and feeding those whose homes and livelihoods were destroyed. If we don't replenish our stores, we'll all be in danger next time there's a bad storm or a Horde invasion.\n\nPerhaps you'd be willing to help me build up our stock of lake whitefish. You can catch it anywhere in Darnassus, and once it's dried, it'll keep until it's needed.", objectives = "" }
WordHunterWoW_QuestEN[29324] = { title = "The Sister's Pendant", description = "Have you met Sister Aquinne? She and I trained together in Dolanaar, and she recently came to the city to study at the Temple of the Moon. We decided to go for a boat ride, but the clumsy oarsman managed to capsize the craft!\n\nWhen we got back to the shore, Aquinne's moon pendant was missing. The lakes in Darnassus are full of giant catfish who will gobble up anything shiny!\n\nI've been catching them nonstop, hoping to find the one with her pendant. I don't suppose you want to help?", objectives = "" }
WordHunterWoW_QuestEN[29325] = { title = "A Slippery Snack", description = "Have you ever eaten octopus meat? It takes some getting used to, but it's my favorite! I even know some people who like to eat the whole thing while it's alive!\n\nI don't plan on trying that anytime soon, but I am out of fresh octopi at the moment. Will you help me gather some more? They live in the shallow water off the shore near Rut'theran Village.", objectives = "" }
WordHunterWoW_QuestEN[29326] = { title = "The Nordrassil Summit", description = "Hello, {class}! My brothers and sisters of the Earthen Ring have spoken well of your deeds in the wake of the Cataclysm. But much remains to be done if we are to heal this broken world.\n\nWalk with me, friend. Preparations for a ceremony are underway, a ritual that I hope will be a turning point in our battle against the Twilight's Hammer.\n\nWhen all is done, you will be able to spread the word about our triumph here.", objectives = "" }
WordHunterWoW_QuestEN[29327] = { title = "Elemental Bonds: Doubt", description = "I do know the one you seek... but I do not know if it is wise for you to follow him. He has cast himself into the cyclone. The winds now tear at his body and mind, leaving nothing but shreds of flesh and doubt.\n\nChasing after him would only expose you to the same fate. The wind's edge leaves nothing uncut.\n\nYou have been warned. Now what will you do?", objectives = "" }
WordHunterWoW_QuestEN[29328] = { title = "Elemental Bonds: Desire", description = "Once again, {class}, I cannot do this without your help. I will try to quiet this tempest, but you will need to fight back the unstable elementals that whirl around it. Only then can we free Go'el!", objectives = "" }
WordHunterWoW_QuestEN[29329] = { title = "Elemental Bonds: Patience", description = "With the Stonemother's blessing, I can take us to where Go'el is being held.\n\nWe must be careful. The Twilight's Hammer has agents all around. You help me hold them off while I attempt to get through to Go'el!\n\nSpeak with me when you are ready, and I will take you to him.", objectives = "" }
WordHunterWoW_QuestEN[29330] = { title = "Elemental Bonds: Fury", description = "The totems, {name}! We need to activate them, or Go'el is lost!\n\nKill the elementals next to each of my totems, located around the edges of this plateau. Once all four totems are activated, we should be able to free the last piece of Go'el's soul!", objectives = "" }
WordHunterWoW_QuestEN[29331] = { title = "Elemental Bonds: The Vow", description = "Before he passed through the portal to Mount Hyjal, Thrall asked you to follow him. There is something he would like you to witness.", objectives = "" }
WordHunterWoW_QuestEN[29332] = { title = "Lily, Oh Lily", description = "The lilies that grow around Stillwater Pond can be rendered down into a delightful broth.\n\nWell... by \"delightful,\" I mean \"won't immediately sicken any orc who drinks it.\"\n\nWhy don't you go gather some for me, hmmm? Just watch out for the giant flesh-eating tadpoles.", objectives = "" }
WordHunterWoW_QuestEN[29333] = { title = "Escargot A Go-Go", description = "The orc guards are always grumbling about bland and moldering Undercity fare - as if it's OUR fault they can't get by on a diet of mushrooms and old corpses - so I think it's time they learn just the sort of exotic delights we can cook up when we've a mind to.\n\nGather some of the freshwater snails ambling about beneath Brightwater Lake and I'll show them what a true culinary master can create.", objectives = "" }
WordHunterWoW_QuestEN[29334] = { title = "Roach Coach", description = "For all the grousing those Kor'kron Overseers do about Undercity food, there's ONE thing they'll eat in spades: My sister Audrey's Thrice-Spiced Crunchy Stew.\n\nIts popularity means she's always running low on ingredients. Could you gather some for her at the coach she sells them from?\n\nYou'll find traps all over the city; just take their contents to Audrey and she'll handle the rest!", objectives = "" }
WordHunterWoW_QuestEN[29335] = { title = "Into Slashing Winds", description = "{class}, I refuse to believe my Go'el is lost forever. His spirit has been scattered across the elemental planes. If even a part of him still exists, we can find him, but I will need your help.\n\nWe will start with the plane of air.\n\nSpeak to me and we will travel to the Vortex Pinnacle together. We must speak with an elemental, Cyclonas. He's capricious, but he sees everything in the realm of air. If my love is there, Cyclonas will know what's become of him.", objectives = "" }
WordHunterWoW_QuestEN[29336] = { title = "Into Coaxing Tides", description = "Go'el must be in the plane of water... the Abyssal Maw itself! I shudder to imagine what fate awaits him there.\n\nFind the elemental, Hydrius, near the Abyssal Breach. He knows of Go'el and is sympathetic to our fight against Ragnaros. If anyone can help you there, it's him.\n\nI will meet you beneath the tides of Vashj'ir, {race}...", objectives = "" }
WordHunterWoW_QuestEN[29337] = { title = "Into Constant Earth", description = "Time is short! My love lies in Deepholm. I will take us there when you are ready, and we will speak with Therazane the Stonemother.", objectives = "" }
WordHunterWoW_QuestEN[29338] = { title = "Into Unrelenting Flame", description = "We must travel now to the Firelands. Within that realm, Go'el's burning spirit could become as terrible as Ragnaros himself! Prepare yourself, for we will be alone in a hostile world.\n\nSpeak with me when you are ready... and may the ancestors protect us! ", objectives = "" }
WordHunterWoW_QuestEN[29339] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[29340] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[29341] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[29342] = { title = "Cold Water Fishing", description = "The best tastin' fish live in the cold waters o' Dun Morogh, {name}, an' don't let anyone else tell ye otherwise! Me favorite, an' the most popular one in Ironforge, is the arctic char, which only comes from our ancestral lands.\n\nI like tae think o' it as Ironforge's gift t' the world!\n\nWhy don't ye try yer hand at catchin' a few yerself? The best place tae find 'em is down in Helm's Bed Lake, in the eastern end o' Dun Morogh.", objectives = "" }
WordHunterWoW_QuestEN[29343] = { title = "One fer the Ages", description = "I'm sure by now ye've heard the tale o' Old Ironjaw, the most famous and elusive fish in the waters o' Ironforge's Forlorn Cavern. Well, in his many years, he's been responsible for the rise o' many young ironjaws. Don't let the name fool ye, {name}, these young'uns are every bit as clever as their dad, but somewhat lackin' in experience.\n\nWith skill an' patience, ye could probably catch one, an' when ye do, bring it to the museum in Ironforge's Library an' put it on display fer all to see!", objectives = "" }
WordHunterWoW_QuestEN[29344] = { title = "Fish fer Squrky", description = "Hae I introduced ye tae me pet, Squrky? I'm teachin' him tae fish all proper-like. Fer now, I've been feedin' him minnows fished from the pool in this cavern.\n\nMaybe ye'd like tae give it a try? Just cast yer lure in the pool over there and feed Squrky any minnows ye happen tae fish up. He'll love ye ferever!", objectives = "" }
WordHunterWoW_QuestEN[29345] = { title = "Pond Predators", description = "A well-meaning goblin visitor introduced Azshara snakeheads to our waters and now they're overrunning the pond.\n\nPlease, if you can catch some of these voracious predatory fish before they eat every smallfish and mud snapper in Thunder Bluff, I'd be terribly grateful.", objectives = "" }
WordHunterWoW_QuestEN[29346] = { title = "The Ring's the Thing", description = "One of the Forsaken from the Pools of Vision came to me and said he'd lost his ring to a blind cavefish in the waters there.\n\nOr perhaps it was his finger. It was hard to tell; his jaw did not move and his Orcish was no better than mine.\n\nIn any case, I thought it would be a kind gesture towards our unusual visitors to catch and gut cavefish until the ring - or finger - was found.\n\nWould you help?", objectives = "" }
WordHunterWoW_QuestEN[29347] = { title = "Live Bait", description = "If ye've ever fished fer crayfish, ye know they respond best to live bait, an' the more bait, the better. Would ye like to test my new bait? Simply smear this on yerself an' hop into Helm's Bed Lake in eastern Dun Morogh.\n\nAfter ye've got the catch, take it to me friend, Cook Ghilm at Gol'Bolar Quarry, west of the lake. He's an expert at cookin' those oversized bugs!", objectives = "" }
WordHunterWoW_QuestEN[29348] = { title = "The Race to Restock", description = "Thunder Bluff's fishing pond is being overrun with voracious Azshara snakeheads; there are hardly any smallfish or mud snappers left.\n\nWe already have fishers trying to kill as many snakeheads as they can, but can you assist us in our restocking efforts?\n\nIf you could gather some fish from Stonebull Lake and bring them here to Thunder Bluff, I would be very grateful.", objectives = "" }
WordHunterWoW_QuestEN[29349] = { title = "Craving Crayfish", description = "One of the great delicacies of Mulgore is the crayfish that dwell in our lakes and streams. They are particularly popular during weddings or the celebration of a birth.\n\nWould you help me catch some of these crafty crustaceans for the cooking pots of Thunder Bluff?\n\nYou can fish them up from Stonebull Lake, or simply dive in and grab them.", objectives = "" }
WordHunterWoW_QuestEN[29350] = { title = "The Gnomish Bait-o-Matic", description = "One o' the gnomish engineerin' trainers gave me a blueprint fer a fancy lure he says'll help me catch fish faster and keep 'em from gettin' away. The whole thing sounds a mite silly if ye ask me, but I'll try anythin' once.\n\nHere are the blueprints. Ye're going to need shiny baubles, which ye can buy from my assistant inside the buildin', a hair trigger ye can buy from an engineerin' supplier in Tinker Town, and a few rat traps from the Deeprun Tram.", objectives = "" }
WordHunterWoW_QuestEN[29351] = { title = "A Round for the Guards", description = "The guards who defend Ironforge put their lives on the line against our many enemies, and it's up to us to take care of them.\n\nToday, their rations consist of two dwarven favorites, haggis and Ironforge pale ale. Would ye be so kind as to help me distribute them? That way, everyone gets his food in a timely manner and we can move on to other tasks.", objectives = "" }
WordHunterWoW_QuestEN[29352] = { title = "A Fowl Shortage", description = "Oh, no, {name}, this is going to be a disaster if we don't find some chicken soon... Ye just cannae make cock-a-leekie soup without the chicken! It's not possible!\n\nThere's still time to make the soup and broth if ye can find some fresh chicken. Will ye help me? There are usually a few chickens running around outside the front entrance to the city. If ye can get yer hands on, say, six o' them, that should save me soup.", objectives = "" }
WordHunterWoW_QuestEN[29353] = { title = "Keepin' the Haggis Flowin'", description = "The haggis must flow. Aye, it's a figure o' speech, for haggis'll ne'er flow! Ye dinnae want to know what'll happen if the people o' Ironforge don't get their haggis.\n\nI'm working on the next batch, but I'm still missing a couple of ingredients.\n\nSognar Cliffbeard is the meat vendor in the Military Ward, an' he'll sell you the big bag o' sheep innards I need. Ye can buy mild spices from any cooking supplier and ye can find sacks o' oatmeal in any inn or among the supplies  in the city.", objectives = "" }
WordHunterWoW_QuestEN[29354] = { title = "Shiny Baubles", description = "One of a fisher's most simple and effective tools is the shiny bauble; affixed to a line, even the most novice angler has a chance at a catch.\n\nWith all the fishing going on of late, though, Thunder Bluff is in woefully short supply!\n\nMight I ask you to collect shiny stones from around the base of the central rise? Bring them to Nahari Cloudchaser so that she might craft more shiny baubles with them.", objectives = "" }
WordHunterWoW_QuestEN[29355] = { title = "Can't Get Enough Spice Bread", description = "It might seem like a basic thing, {name}, but spice bread is a longtime favorite in Ironforge. Some days, I have trouble keeping up!\n\nWould ye like to cook some to practice yer skills an' help meet the demand? Ye can buy all the ingredients ye'll need from me brother, Emrul Riknussun, who is downstairs.", objectives = "" }
WordHunterWoW_QuestEN[29356] = { title = "I Need to Cask a Favor", description = "My stocks o' IPA, that's Ironforge Pale Ale for ye novices, are gettin' low. Luckily, the brewery isn't too far away an' they should have a new cask o' Drugan's IPA waitin' fer us. That Drugan's a genius of a brewer, I tell ye.\n\nI won't be able to get down to Kharanos meself today, but perhaps ye can dash down there, pick up the new cask an' run it back 'ere? What d'ye say?", objectives = "" }
WordHunterWoW_QuestEN[29357] = { title = "Spice Bread Aplenty", description = "Isn't it amazing how something as simple as spice bread is used every day in Darnassus? When I'm not seeing to my other responsibilities, I like to bake spice bread to hone my skills as a cook and practice my technique.\n\nWhy don't you give it a try? You should be able to get your ingredients here in the shop.\n\nNo matter how much we make, it never goes to waste. Bring me your loaves when you're done and I'll have someone share them with our friends, the Gilneans.", objectives = "" }
WordHunterWoW_QuestEN[29358] = { title = "Pining for Nuts", description = "The Shu'halo use pine nuts in so MANY dishes: meat, fish, vegetables, even baked into breads or sprinkled over sweet pastries.\n\nThe Earth Mother has blessed us in that the very BEST pine nuts come from the trees upon these very mesas. Simply gather pine cones and toast them over a cooking fire to release the nuts within.\n\nWould you please be so kind as to gather some? There are hardly ever enough to go around...", objectives = "" }
WordHunterWoW_QuestEN[29359] = { title = "An Old Favorite", description = "Herring is one of the most sought-after fish in Darnassus, but not just any herring. The Kaldorei herring is native only to the waters surrounding Teldrassil.\n\nI try to keep a good supply of it because it's so versatile! I just finished smoking a batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch Kaldorei herring by fishing in Rut'theran Village.", objectives = "" }
WordHunterWoW_QuestEN[29360] = { title = "Would You Like Some Flies With That?", description = "It's not always about making food for the orcs, {class}.  This time, it's about making food for what will hopefully be their replacements.\n\nWe need to start small, we need to catch flies.  Flies love rotting meat, and we love rotting meat... as projectile weapons!\n\nCheck out the Meat Wagons for any extra bits of meat.  Where you find the meat, you'll find the flies.\n\nBring me 25 bloated flies, and then I can start on the next stage of our cooking plan.", objectives = "" }
WordHunterWoW_QuestEN[29361] = { title = "Moat Monster!", description = "Sometimes fishing means throwing something back, {class}.\n\nWe've been overfeeding these frogs for just that occasion.  We've fed these frogs bloated spiders, that were fed bloated flies, and now, we are going to feed a real monster.\n\nThe moat above, in the Ruins of Lordaeron, is home to our very own moat monster.\n\nToday is feeding day.  But we must train it as well.  In this bag, you will find a decoy kit and some bloated frogs.  Use the decoy kit, then toss the frogs to the monster when it appears.", objectives = "" }
WordHunterWoW_QuestEN[29362] = { title = "\"Magic\" Mushrooms", description = "You know of the Pools of Vision, yes?\n\nThere is a sort of mushroom that grows there... not the tough, rank fungi that dominates the place, but smaller, more delicate caps that grow beneath them.\n\nThey are rare and quite delicious, adding a flavor to meat dishes that one might even call magical.\n\n...what? No, really. They just taste good. That's it.", objectives = "" }
WordHunterWoW_QuestEN[29363] = { title = "Mulgore Spice Bread", description = "I am often asked, \"Aska, who is making all this Mulgore spice bread?!\"\n\nIt is a reasonable question. Our fine and noble bread is traded in countless settlements in the most far-away lands, even by our staunchest foes. IT'S JUST THAT GOOD.\n\nAnd the answer...?\n\nIt is \"YOU.\" Please take this packet of Mulgore spices and use it to turn bland, boring spice bread into MULGORE spice bread!", objectives = "" }
WordHunterWoW_QuestEN[29364] = { title = "Corn Mash", description = "One of Thunder Bluff's most important staples is cornmeal; bowls of corn may be found in nearly every home.\n\nWith so many of the local mills under constant attack by harpies, gnolls, reckless mining companies and Earth Mother knows what else, I often ask my students to help with the task of grinding corn into cornmeal.\n\nWould you care to help?", objectives = "" }
WordHunterWoW_QuestEN[29365] = { title = "Perfectly Picked Portions", description = "Even the novice cook knows that a great dish begins with great ingredients.\n\nI have standing orders with merchants throughout Thunder Bluff, but I'd like to see how well you do at selecting the very best of what they have to offer.\n\nPlease make the rounds and gather perfect portions of meat, fish, vegetables and herbs from local merchant stalls.", objectives = "" }
WordHunterWoW_QuestEN[29371] = { title = "A Time to Lose", description = "Well met, {class}. As we attempt to embrace the Wickerman ceremony, it is no surprise that the Horde would attempt to ruin our celebration.\n\nNow the prudent course of action may be to rise above the conflict and simply ignore the attacks.\n\nI admire those that take that high road, but I cannot help them.  But for those that seek to strike back... I can help them.  If you are interested, {class}, take this Dousing Agent and use it on the Horde's Wickerman in the Ruins of Lordaeron.", objectives = "" }
WordHunterWoW_QuestEN[29374] = { title = "Stink Bombs Away!", description = "The foolish Alliance have employed hags to fuel an attack on our city.  Well, as my sister once told me, \"Turnabout is fair play.\"\n\nWe will gladly return the favor.  Speak with my sister, and she will provide you with a broomstick flight over Stormwind.  While over Stormwind, drop stink bombs on the city and on the people.  Make them suffer!\n\nWe will show those hags in Stormwind who is the most powerful.", objectives = "" }
WordHunterWoW_QuestEN[29375] = { title = "Clean Up in Undercity", description = "Greetings, {class}!  Are you enjoying Hallow's End?  It seems that in response to our stink bombing Stormwind, the Alliance has decided to stink bomb our city.\n\nFortunately, we have magics that can handle the stink the Alliance bring us.  Use this Arcane Cleanser to remove the stink bombs from the city.", objectives = "" }
WordHunterWoW_QuestEN[29376] = { title = "A Time to Build Up", description = "We burn the effigy of the Wickerman as a symbol of our struggle against those who would oppose us. We wear the ashes of the burnt Wickerman as a symbol of our neverending fight against those who would enslave us.\n\nUse the bonfire nearby and ignite the Wickerman.  Then take the ashes that lay nearby and spread them across your face.\n\nThese gestures will serve as a reminder to our enemies that we shall never yield.", objectives = "" }
WordHunterWoW_QuestEN[29377] = { title = "A Time to Break Down", description = "Well met, {class}. As we revel in the Wickerman ceremony, it comes as no surprise that the Alliance would attempt to ruin our celebration.\n\nWe have an opportunity to make them pay.  If you are interested, {class}, take this Dousing Agent and use it on the Alliance's Wickerman in front of Stormwind.\n\nExtinguish their flame and revel in their misery, {class}.", objectives = "" }
WordHunterWoW_QuestEN[29382] = { title = "Thanks, But No Thanks", description = "A holiday sweater may not be for everyone.\n\nThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.\n\nAll exchanges are final.", objectives = "" }
WordHunterWoW_QuestEN[29383] = { title = "Thanks, But No Thanks", description = "A holiday sweater may not be for everyone.\n\nThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.\n\nAll exchanges are final.", objectives = "" }
WordHunterWoW_QuestEN[29385] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[29387] = { title = "Guardians of Hyjal: Firelands Invasion!", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal immediately.", objectives = "" }
WordHunterWoW_QuestEN[29388] = { title = "Guardians of Hyjal: Firelands Invasion!", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied champions of the Horde should report to the Sanctuary of Malorne in Mount Hyjal immediately.", objectives = "" }
WordHunterWoW_QuestEN[29389] = { title = "Guardians of Hyjal: Firelands Invasion!", description = "Your work has given us the advantage we need to mobilize against the denizens of the Firelands. We are gathering our invasion force just south of our position.\n\nWe could use your strength again, {race}. Speak with Matoclaw at the Sanctuary of Malorne. She is coordinating the invasion effort.", objectives = "" }
WordHunterWoW_QuestEN[29390] = { title = "Guardians of Hyjal: Call of the Ancients", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.\n\nWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Lo'gosh, Tortolla, Aviana, and Aessina.\n\nNew travelers to Mount Hyjal may look for a Warchief's Command to Hyjal on any Horde call board.", objectives = "" }
WordHunterWoW_QuestEN[29392] = { title = "Missing Heirlooms", description = "The last of my belongings were supposed to be arriving from Theramore today. The ship has arrived, but I haven't heard from the courier. The crate he was transporting had items that've been in my family for generations.\n\nWill you go down to Stormwind Harbor and see what's keeping him?", objectives = "" }
WordHunterWoW_QuestEN[29393] = { title = "Brew For Brewfest", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", objectives = "" }
WordHunterWoW_QuestEN[29394] = { title = "Brew For Brewfest", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", objectives = "" }
WordHunterWoW_QuestEN[29396] = { title = "A New Supplier of Souvenirs", description = "<sigh>\n\nDon't talk to me about last year's stein...\n\nI think our shady stein suppliers were somehow involved with that Twilight Hammer cult non-sense that errupted just before the elementals invaded.\n\nAnd that's why we have a new supplier and a better stein!\n\nHere's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "" }
WordHunterWoW_QuestEN[29397] = { title = "A New Supplier of Souvenirs", description = "The less said about last year's stein, the better, {name}.  I'll tell you this, our previous supplier, they were shady.  Turns out they were involved in some cultist activities...\n\nWe can't work with people who are trying to destroy the world!!\n\nSo we have a new supplier and a new stein.\n\nTake this voucher to Belbi Quikswitch  near the back of the Brewfest camp.  She'll give you your free Brewfest stein.  She'll also handle any and all other Brewfest transactions that come up during the holiday.", objectives = "" }
WordHunterWoW_QuestEN[29398] = { title = "Fencing the Goods", description = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished.\n\nAs you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", objectives = "" }
WordHunterWoW_QuestEN[29399] = { title = "Shopping Around", description = "I told the 'gentleman' that there might be a shop more suited to his needs in the Dwarven District. It's called the Shady Lady and you can find the entrance near the Canals on the western side of the district.\n\nQuincy Cutler is your man. He trades in merchandise an honest broker would never touch!", objectives = "" }
WordHunterWoW_QuestEN[29400] = { title = "A Season for Celebration", description = "Well met, {class}.\n\nHallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken.\n\nTravel to the Ruins of Lordaeron and speak to Darkcaller Yanka. She can tell you more about the Wickerman ceremony.", objectives = "" }
WordHunterWoW_QuestEN[29401] = { title = "Blown Away", description = "Please, mister, you just gotta help me!\n\nMy pa brought me a bunch of balloons from the Darkmoon Faire. Best... gift... EVER! They're magical, you know, and never lose their floatiness!\n\nThere's just one thing...\n\nA big ol' gust of wind blew 'em right outta my hands. They're scattered all over Orgrimmar!\n\nI'd chase after 'em myself, but this city's so big I'd get lost for sure.\n\nCan you round 'em up for me before they float away?\n\nPlease?", objectives = "" }
WordHunterWoW_QuestEN[29402] = { title = "Taking Precautions", description = "I'd be wary of anyone identifying himself as the rightful owner of the crate and its contents. He didn't warn you of the danger?\n\nHere's a better idea: let's work together to recover the crate and ensure that its contents can't hurt anyone. To protect ourselves, we're going to need a draught made from a few ingredients that can be found around the city.\n\nAcquire some strange dust, get vials from an alchemy merchant, and pick some blood nettle from the fields north of the city.", objectives = "" }
WordHunterWoW_QuestEN[29403] = { title = "The Collector's Agent", description = "According to Quincy, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara.\n\nThe archmage's faithful servant is to meet with the man who has the crate in the catacombs beneath the Cathedral of Light.\n\nYou must get there in time to intercept the exchange and retrieve the crate before it is lost to Xylem forever. When you have the crate, meet me at the Golden Keg.", objectives = "" }
WordHunterWoW_QuestEN[29404] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[29405] = { title = "The Lesson of the Iron Staff", description = "To train, first you must be properly equipped. Retrieve a weapon from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", objectives = "" }
WordHunterWoW_QuestEN[29406] = { title = "The Lesson of the Sandy Fist", description = "I'd like to observe you putting your new weapon to use, my young student. This will aid me in determining what degree of training will be best suited to your talents.\n\nWe have many training targets in the training grounds below. Practice your attacks upon them, and return to me once you're feeling comfortable with your new weapon.", objectives = "" }
WordHunterWoW_QuestEN[29407] = { title = "The First Sign of Winter", description = "At the stream below rests a single lotus flower. Within this lotus lies a sign of things to come. Bring it to me that I might show you.", objectives = "" }
WordHunterWoW_QuestEN[29408] = { title = "The Lesson of the Burning Scroll", description = "Every wisdom has a time and place, and times are changing for those of us living here on Shen-zin Su. For this lesson, I would ask two things of you.\n\nFor the first, I hold a flame in my hand. Gather your wits, and when you think you are ready, attempt to snatch the flame.\n\nShould you succeed, I want you to then climb to the top of this temple and burn the Edict of Temperance that you find there.", objectives = "" }
WordHunterWoW_QuestEN[29409] = { title = "The Disciple's Challenge", description = "{name}, I see great strength and great courage in you, and an unsurpassed purity of soul.\n\nThe hour is young, but I think you may be ready to face a greater challenge.\n\nGo to the bottom of the stairs, and cross the bridge. There, you will find Jaomin Ro, one of our eldest students. Challenge and defeat him in honorable combat, and this first phase of your training will be complete.", objectives = "" }
WordHunterWoW_QuestEN[29410] = { title = "Aysa of the Tushui", description = "In such a short time, you've shown me that you have the potential to be a great {class}. The training grounds are behind you, but now you must prove yourself by facing a far greater challenge, one that none of my students have accomplished.\n\nI want you to return Huo, the spirit of fire, to the Temple of Five Dawns.\n\nMy two other most gifted students will help you in this task. The first is Aysa Cloudsinger. Seek her out at the pool to the west.", objectives = "" }
WordHunterWoW_QuestEN[29411] = { title = "What Now?", description = "You've finally found the crate that Anson sent you to retrieve. However, it appears the archaeology student's warnings about the nature of the crate's contents were correct.\n\nThere's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Hudson Barnes, who believes it better to keep the crate's contents locked away?", objectives = "" }
WordHunterWoW_QuestEN[29412] = { title = "Blown Away", description = "Please, mister, you just gotta help me!\n\nFather bought me a bunch of balloons from the Darkmoon Faire. They're magical, you know, and never lose their floatiness!\n\nThere's just one thing...\n\nA gust of wind blew them out of my hands. They're scattered all over Stormwind!\n\nI'd chase after them myself, but this city's so big I'd get lost for sure.\n\nCan you find them for me before they float away?\n\nPlease?", objectives = "" }
WordHunterWoW_QuestEN[29413] = { title = "The Creepy Crate", description = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems bonded to you and now it's yours.", objectives = "" }
WordHunterWoW_QuestEN[29414] = { title = "The Way of the Tushui", description = "It's a pleasure to meet you, {class}. I am Aysa, of the Tushui.\n\nI've spent much time in thought since Master Shang told me we would be searching for Huo, the spirit of fire. I know where he resides, but not how to reach him. The answers are close, however.\n\nCome with me to the Cave of Meditation nearby. It is a place of great wisdom. I will meditate there, open my mind, and the path shall find us.", objectives = "" }
WordHunterWoW_QuestEN[29415] = { title = "Missing Heirlooms", description = "I told that courier to take the zeppelin, but no, he had to use the goblin ship! Well, now he's late and my precious family heirlooms are with him.\n\nIf you're willing to help, would you go down to the docks east of Orgrimmar, board the goblin ship and see what's keeping him?", objectives = "" }
WordHunterWoW_QuestEN[29416] = { title = "Fencing the Goods", description = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished.\n\nAs you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", objectives = "" }
WordHunterWoW_QuestEN[29417] = { title = "The Way of the Huojin", description = "We call those vicious monkeys swinging into town hozen. They keep to themselves normally, but they know something bad is coming, so they're here to steal our supplies.\n\nIn situations like this, the clear answer is the only answer. These monkeys will leave when we force them to leave! To not defend our town and those we love would be the only true crime. Thus is the way of the Huojin.", objectives = "" }
WordHunterWoW_QuestEN[29418] = { title = "Kindling the Fire", description = "Now that that's done with, let's get to it then!\n\nHuo, the spirit of fire, hungers for dry dogwood root kindling. It grows among the trees south of the village. It should be easy enough for you to gather some.", objectives = "" }
WordHunterWoW_QuestEN[29419] = { title = "The Missing Driver", description = "My driver went running off after the sprites just after they attacked. I don't think they'll really do him any harm, but I need him back to help me clean up the mess by the cart.\n\nHe chased them off towards the cliffs to the north. If you head that direction, you should find him quickly.", objectives = "" }
WordHunterWoW_QuestEN[29420] = { title = "The Spirit's Guardian", description = "You've done very well this far, my student. You have the materials you need to rekindle Huo, the spirit of fire.\n\nIn the cave to the southwest he awaits, but he is guarded by Master Li Fei, the pandaren elder you met in the Cave of Meditation. Go to Master Li Fei with the offerings. Prove yourself, then meet with Huo.", objectives = "" }
WordHunterWoW_QuestEN[29421] = { title = "Only the Worthy Shall Pass", description = "It is time for you to face me. With these three fires illuminating your potential, we will see with certainty whether your resolved soul is truly worthy of passing.", objectives = "" }
WordHunterWoW_QuestEN[29422] = { title = "Huo, the Spirit of Fire", description = "You are worthy of passing, {class}.\n\nHuo, the spirit of fire rests in the chamber beyond. Let him feast upon the kindling you've gathered, and use the wind to fan his flames. Doing so should endear you to him. Once he is ignited, if he is willing, lead him to the Temple of Five Dawns, the building standing high in the center of the island.", objectives = "" }
WordHunterWoW_QuestEN[29423] = { title = "The Passion of Shen-zin Su", description = "<Huo bounces around excitedly, ready to follow you.>\n\n<Master Shang Xi told you to bring Huo to meet him at the Temple of Five Dawns in the center of the island. Your next destination lies before you.>", objectives = "" }
WordHunterWoW_QuestEN[29424] = { title = "Items of Utmost Importance", description = "Amberleaf scamps swarmed my cart and stole most of the training supplies I was bringing up to the training grounds. They've always been troublemakers, but they've never been this aggressive before. I don't know what happened.\n\nPlease, help me recover my supplies.", objectives = "" }
WordHunterWoW_QuestEN[29425] = { title = "Shopping Around", description = "Look, I told that shady character that there might be a shop more open to his, uh, wares in the Drag. Droffer's and Son Salvage is the name of the place.\n\nLook for Dran Droffers. He oversees the 'salvage' of rare and valuable objects from all over Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[29426] = { title = "Taking Precautions", description = "So someone else hired you to retrieve this crate? I don't like the sound of that.\n\nThat crate's contents belong in the care of the Reliquary. The items it holds are very powerful and very dangerous.\n\nWe have to find the meeting that Dran set up between the thief and the collector, but first, we'll need to protect ourselves from the effects of handling that crate.\n\nAcquire some strange dust, get vials from an alchemy merchant, and pick some blood nettle in the Valley of Wisdom.", objectives = "" }
WordHunterWoW_QuestEN[29427] = { title = "The Collector's Agent", description = "According to Dran, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara.\n\nThe archmage's faithful servant is to meet with the man who has the crate in a secluded corner of the courtyard in the Ruins of Lordaeron.\n\nQuickly, take the zeppelin to Tirisfal Glade!\n\nYou must get there in time to intercept the exchange and retrieve the crate before Xylem gets his hands on it. If you can get the crate, meet me at the Wyvern's Tail in the Valley of Honor.", objectives = "" }
WordHunterWoW_QuestEN[29428] = { title = "What Now?", description = "You've finally found the crate that Edgar Goodwin sent you to retrieve. However, it appears the Reliquary representative's warnings about the nature of the crate's contents were correct.\n\nThere's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Delian Sunshade, who believes it better to keep the crate's contents locked away?", objectives = "" }
WordHunterWoW_QuestEN[29429] = { title = "The Creepy Crate", description = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems bonded to you and now it's yours.", objectives = "" }
WordHunterWoW_QuestEN[29430] = { title = "A Friend in Need", description = "You know, I haven't seen Anson out here yet.\n\nLately, he's been spending all his time drinking himself into a stupor at the Gilded Rose.\n\nSomething must really be bothering him! Would you mind checking in on him?", objectives = "" }
WordHunterWoW_QuestEN[29431] = { title = "A Friend in Need", description = "There's something wrong with my friend, Edgar. Normally, he loves the Hallow's End festivities, but he's been sullen and reclusive lately.\n\nHe spends all his time in the Broken Tusk in Orgrimmar drinking with the orcs. Would you mind stopping by and seeing if there's anything you can do to cheer him up?", objectives = "" }
WordHunterWoW_QuestEN[29433] = { title = "Test Your Strength", description = "For some people, it's all fun and games until someone gets hurt.  I call those people, weak.\n\nTo be the strongest, you have to hurt someone or something.  You hurt yourself as you push your body to its limits.  You hurt those that threaten the well-being of others.\n\nIf you want to be the strongest, you have to fight.  How bad do you want it?\n\nI want you to crush those that would offer a challenge to you, then bring me back proof of your triumphs.", objectives = "" }
WordHunterWoW_QuestEN[29434] = { title = "Tonk Commander", description = "Welcome to our humble little steam tank battle simulator!\n\nFor one token, you can demonstrate your tactical mastery by navigating the course and destroying the targets.", objectives = "" }
WordHunterWoW_QuestEN[29436] = { title = "The Humanoid Cannonball", description = "For just one Darkmoon Game Token, you can ride the Blastenheimer 5000 Ultra Cannon.  But the fun doesn't end there!  We've placed a target in the water near the boardwalk.\n\nIf you can score five points from your landing, you can win some prize tickets!\n\nA bullseye gets you five points, a close shot three, and landing at least near it gets you one.\n\nHappy landings!", objectives = "" }
WordHunterWoW_QuestEN[29437] = { title = "The Fallen Guardian", description = "Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon Alysra - one of my very own! - who was in charge of keeping Fandral secure.\n\nWe can only conclude that the Twilight's Hammer has gotten to her. You must confront her, {name}. Destroy her if you must - I cannot bear to see it.\n\nShe was last seen in the Ruins of Lar'donir, west of the World Tree.", objectives = "" }
WordHunterWoW_QuestEN[29438] = { title = "He Shoots, He Scores!", description = "Think you're a good shot?  Quick on the trigger?\n\nIt'll cost you just a single game token to test your skills.\n\nWhat do you say?  How good are you?", objectives = "" }
WordHunterWoW_QuestEN[29439] = { title = "The Call of the World-Shaman", description = "The Earthen Ring calls to you once more, {name}.\n\nAs a member of the Alliance, I know that you may have reservations working with the one you call Thrall, the former Warchief of the Horde. But he has specifically requested an Alliance hero to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.\n\nCast aside your doubts, {class}, and heed the world-shaman's call.\n\nYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree.", objectives = "" }
WordHunterWoW_QuestEN[29440] = { title = "The Call of the World-Shaman", description = "The Earthen Ring calls to you once more, {name}.\n\nThrall has cast aside his mantle as warchief of the Horde, but in his new role he needs the support of his people more than ever. He has requested one of the Horde's finest to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.\n\nYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. Heed the call!", objectives = "" }
WordHunterWoW_QuestEN[29443] = { title = "A Curious Crystal", description = "Power swirls inside this strange crystal. Perhaps it was once a magical focus, an energy source, or simply a good luck charm. There's no way to know for certain.\n\nThe Darkmoon Adventurer's Guide indicates that the crystal would be of interest to Professor Thaddeus Paleo at the Darkmoon Faire.", objectives = "" }
WordHunterWoW_QuestEN[29444] = { title = "An Exotic Egg", description = "You're not certain what kind of creature this egg harbors, but it sure doesn't look like the egg of any ordinary animal.\n\nThe Darkmoon Adventurer's Guide says that an intrepid adventurer might come across any number of strange eggs in his travels. It further notes that the Darkmoon Faire's Zoo Bizarre is always interested in acquiring such specimens.\n\nTake the egg to Yebb Neblegear at the Darkmoon Faire.", objectives = "" }
WordHunterWoW_QuestEN[29445] = { title = "An Intriguing Grimoire", description = "This massive spellbook reveals very little of its origins. Its pages are filled with a variety of spells and enchantments, only a few of which are familiar.\n\nThe Darkmoon Adventurer's Guide says the tome may be of some interest to Sayge, the famous gnoll fortuneteller at the Darkmoon Faire.", objectives = "" }
WordHunterWoW_QuestEN[29446] = { title = "A Wondrous Weapon", description = "An inspection of the weapon reveals expert craftsmanship and intricate inlay work, but this is no ceremonial blade. Faint marks and nicks along the blade attest to its use in combat.\n\nThe Darkmoon Adventurer's Guide lists several types of rare and valuable weapons, leaving no doubt that Professor Thaddeus Paleo at the Darkmoon Faire would be interested in taking a look at this piece.", objectives = "" }
WordHunterWoW_QuestEN[29451] = { title = "The Master Strategist", description = "This tome of strategy is the masterwork of the famous human general, Anduin Lothar. In his own words, the commander describes the proper deployment of forces and strategies needed to win almost any battle.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire would probably love to have a look at such a rare book.", objectives = "" }
WordHunterWoW_QuestEN[29452] = { title = "Your Time Has Come", description = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.>\n\nYoung {class}, be still and hear my words.\n\nI am called to collect you, to deliver you, to one whose eye none can escape.\n\nFind me in Orgrimmar, mortal, for your time has come.", objectives = "" }
WordHunterWoW_QuestEN[29453] = { title = "Your Time Has Come", description = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.>\n\nYoung {class}, be still and hear my words.\n\nI am called to collect you, to deliver you, to one whose eye none can escape.\n\nFind me in Stormwind, mortal, for your time has come.", objectives = "" }
WordHunterWoW_QuestEN[29455] = { title = "Target: Turtle", description = "Hey there! Step right up!\n\nWhy not show everyone how skilled you are?  Just land three rings on the Darkmoon Turtle and you'll get a prize.\n\nFor one game token you can buy a stack of rings and show the world why we call you the \"Eagle Eyed {class}.\"", objectives = "" }
WordHunterWoW_QuestEN[29456] = { title = "A Captured Banner", description = "This tattered banner bears a faded guild crest. This old banner must've seen more than its share of battles.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire collects banners and other relics of combat and he might be interested in acquiring this one. Show the banner to him next time you visit the Darkmoon Faire.", objectives = "" }
WordHunterWoW_QuestEN[29457] = { title = "The Enemy's Insignia", description = "This battered badge carries the insignia of an enemy officer. While worth little more to you than the metal it's made from, this piece would have significant value to a collector of military memorabilia.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire is famous all over Azeroth for his large collection of military artifacts. Show the badge to him the next time you visit the Darkmoon Faire.", objectives = "" }
WordHunterWoW_QuestEN[29458] = { title = "The Captured Journal", description = "This book is covered in battered leather stained with blood and mud. Leafing through the pages, you discover that it is a personal journal of an adventurer with a high opinion of himself and his adventures.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire might want to see something like this.", objectives = "" }
WordHunterWoW_QuestEN[29463] = { title = "It's Hammer Time", description = "So you want to whack some gnolls?  Well you've come to the right place.\n\nYour goal is simple, score 30 points in a minute.\n\nUse the mallet I give you and get ready to whack.  Speak to me when you are ready to start.", objectives = "" }
WordHunterWoW_QuestEN[29464] = { title = "Tools of Divination", description = "This collection of well-worn runestones has seen much use. The pieces seem old; you can't recognize any of the markings on their surfaces.\n\nPerhaps a scholar or a collector would know more about them. Bring them to Professor Thaddeus Paleo next time you're at the Darkmoon Faire.", objectives = "" }
WordHunterWoW_QuestEN[29506] = { title = "A Fizzy Fusion", description = "I'm sure you've made a lot of potions in your time as an alchemist. How would you like to help with something a bit more light-hearted?\n\nI've always wanted to try creating a fruit-flavored version of our popular fizzy drinks. If you're willing to give it a try, you can buy some of the base drink from me and mix it with some moonberry juice.\n\nAny innkeeper in Elwynn Forest or Mulgore should be able to sell you enough juice to make your creation.", objectives = "" }
WordHunterWoW_QuestEN[29507] = { title = "Fun for the Little Ones", description = "Children are always full of questions about what an archaeologist does and how it works, so I prepared a demonstration for them.\n\nI take artifacts and fossils and bury them in the sandbox beside the tent. The children get to dig and make their own discoveries, learn how bones fit together, and see how archaeology can teach them about history.\n\nIf you have any spare fossils, would you consider donating them to my side project?", objectives = "" }
WordHunterWoW_QuestEN[29508] = { title = "Baby Needs Two Pair of Shoes", description = "You may have seen my horse, Baby, over near the wagons. She pulls the cart that hauls some of the animals in our Zoo Bizarre.\n\nShe's a hard worker and she tears through shoes like you wouldn't believe. It's about time for a new set. I've already bought the raw materials.\n\nAll you need to do is shape them over an anvil and apply them to Baby's feet. It's a quick job and worth some tickets, wouldn't you say?", objectives = "" }
WordHunterWoW_QuestEN[29509] = { title = "Putting the Crunch in the Frog", description = "The Darkmoon Faire's crunchy frog is famous all over Azeroth!\n\nWe've just had a fresh batch of frogs delivered. How'd you like to help whip up a few and practice your cooking skills in the process?\n\nYou can get the flour you'll need to bread the frogs from any trade goods vendor in Elwynn Forest or Mulgore.", objectives = "" }
WordHunterWoW_QuestEN[29510] = { title = "Putting Trash to Good Use", description = "People don't just come to the faire for fun and fortunes, {name}. Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets.\n\nFor that, I need a steady supply of soothsayer's dust. Take a look around the grounds and you'll see a lot of discarded weapons. Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?", objectives = "" }
WordHunterWoW_QuestEN[29511] = { title = "Talkin' Tonks", description = "The steam tonks are one of the Darkmoon Faire's most popular amusements. Our visitors love to test their skills for hours and hours, but the tonks take a real beating from all that fun.\n\nYou look like you know your way around a wrench. Mind helping me fix some of the damaged tonks and return them to working order? I'll compensate you for your time.", objectives = "" }
WordHunterWoW_QuestEN[29513] = { title = "Spoilin' for Salty Sea Dogs", description = "We've just introduced another exciting new menu item, the salty sea dog. It's so popular, we can barely keep up with the demand!\n\nYou look like a decent angler and a spry {race}. Would you help me restock my fish supplies?\n\nWe wouldn't want to disappoint all those faire-goers looking to try a new food, would we?", objectives = "" }
WordHunterWoW_QuestEN[29514] = { title = "Herbs for Healing", description = "The little purple flowers that grow wild around the grounds aren't just pretty.\n\nThey play a role in everything from treating wounds to seasoning food.\n\nYou seem to have some talent for harvesting herbs. Would you like to help me rebuild my stocks of darkblossom?", objectives = "" }
WordHunterWoW_QuestEN[29515] = { title = "Writing the Future", description = "As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures.\n\nMost times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice.\n\nMy stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. You can get the parchment you'll need from any trade goods vendor in Elwynn Forest or Mulgore.", objectives = "" }
WordHunterWoW_QuestEN[29516] = { title = "Keeping the Faire Sparkling", description = "The Darkmoon Faire's performers and animals go through more jewelry than I'd ever imagined. Thankfully, the gems are just cut glass, but someone has to craft all of it.\n\nIf you've some skill as a jewelcrafter, perhaps you'd be willing to help craft some of the sparkling glass gems for our performers.\n\nSometimes you can find odd and amazing bits of glass around the grounds. Those make stunning gems when cut by someone with an eye for this craft.", objectives = "" }
WordHunterWoW_QuestEN[29517] = { title = "Eyes on the Prizes", description = "The games are more popular than ever, and that means we're giving out prizes faster than we ever have before!\n\nWe're going to need more prizes, and fast. If you've some skill in leatherworking, I can give you a kit. You'll need to buy some of the pieces from any trade goods merchant in Elwynn Forest or Mulgore, but they're inexpensive.\n\nAre you willing to help?", objectives = "" }
WordHunterWoW_QuestEN[29518] = { title = "Rearm, Reuse, Recycle", description = "Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap.\n\nIt'd be a shame to let all that good metal just sit in the dirt.\n\nIf you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?", objectives = "" }
WordHunterWoW_QuestEN[29519] = { title = "Tan My Hide", description = "The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment.\n\nYou seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.", objectives = "" }
WordHunterWoW_QuestEN[29520] = { title = "Banners, Banners Everywhere!", description = "Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced.\n\nIf you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stones scattered around the grounds of the faire?\n\nIt's missing a few pieces, but you should be able to get what you need from any trade goods vendor in Elwynn Forest or Mulgore.", objectives = "" }
WordHunterWoW_QuestEN[29521] = { title = "The Singing Pools", description = "It is crucial that we bring all of the three remaining spirits back safely. I am too old to do this myself, and for all their strengths, both Aysa and Ji are single-minded in their ideals.\n\nYou possess all the qualities of a hero, and a balance that they do not. It is you that must do this.\n\nShu, the spirit of water is somewhere in the singing pools to the east. Find Aysa there and work with her to locate him. We are all depending on you.", objectives = "" }
WordHunterWoW_QuestEN[29522] = { title = "Ji of the Huojin", description = "Another of my most talented students is awaiting you in Wu-Song Village to the northwest. He is of a different mind than Aysa, but in their differences, they bring balance to each other.\n\nJi Firepaw will instruct you on gathering the offerings for the spirit of fire. Trust in his wisdom.", objectives = "" }
WordHunterWoW_QuestEN[29523] = { title = "Fanning the Flames", description = "Strange thing about wind, it can be hard to wrap your hands around it.\n\nBest practice for me has been finding some sort of living wind. If it can punch you, you can punch it back, and it won't slip through your grasp.\n\nHead over to the Shrine of the Summer Breeze to the south and summon just such a living wind using this wind stone. Best it, gather a Fluttering Breeze from it, and come back over this way so that we can figure out what's next.", objectives = "" }
WordHunterWoW_QuestEN[29524] = { title = "The Lesson of Stifled Pride", description = "Facing a living opponent is a very different thing from the stationary targets in the yard. Living opponents strike back. There is the very real fear of failure, and sometimes, even death.\n\nYou must have the courage to overcome those fears.\n\nChallenge the other trainees within the temple or down the steps below, and defeat them.", objectives = "" }
WordHunterWoW_QuestEN[29527] = { title = "War on the Ramparts", description = "Watchkeeper Gargolmar and Vazruden the Herald are in charge of defending these ramparts.\n\nIf you take them out, their forces will be in complete disarray.\n\nSlay them both and bring me proof so the invasion can begin!", objectives = "" }
WordHunterWoW_QuestEN[29528] = { title = "War on the Ramparts", description = "Hellfire Citadel's entire defensive network relies on the ramparts as a sort of early warning system.\n\nYou need to take out Watchkeeper Gargolmar and Vazruden the Herald. Without them, taking the ramparts will be simple.", objectives = "" }
WordHunterWoW_QuestEN[29529] = { title = "Demons in the Citadel", description = "One of our scouts spotted what he thought was an agent of the Burning Legion somewhere in the ramparts. If that is true, then Honor Hold may be in grave danger of a combined assault!\n\nIf you find this fiend in there, kill it on sight.", objectives = "" }
WordHunterWoW_QuestEN[29530] = { title = "Demons in the Citadel", description = "One of our scouts brought back unpleasant news. We've spotted a powerful agent of the Burning Legion in the ramparts!\n\nI need you to kill this demon before he has a chance to relay news of our efforts to his superiors.", objectives = "" }
WordHunterWoW_QuestEN[29535] = { title = "Make Them Bleed", description = "The Maker serves the purpose of creating more fel orcs by infusing them with demon blood.\n\nMy superiors believe that we may be able to reverse the process, but we need samples of their blood and The Maker's infusion rod before we can know for sure.", objectives = "" }
WordHunterWoW_QuestEN[29536] = { title = "Heart of Rage", description = "We know that the fel orcs are growing their forces by infusing orcs with demon blood.\n\nI need you to venture deep inside these unholy halls and find out how that's happening. We can't risk sending an army into this place until we know exactly what we're dealing with.", objectives = "" }
WordHunterWoW_QuestEN[29537] = { title = "Mind the Gap", description = "In all of the Blood Furnace, there is one area where our scryers cannot reach despite their efforts.\n\nThis 'gap', as they've been calling it, is fairly large, and must be where Magtheridon is being held captive..\n\nYou must find the source of the interference and dispose of it.", objectives = "" }
WordHunterWoW_QuestEN[29538] = { title = "Make Them Bleed", description = "The Maker uses demon blood and a special rod to turn brown and green orcs into red ones. We'd like to see if we can take that blood, mess around with it a bit, and make it turn orcs of all colors into harmless docile lumps. \n\nYou're going to bring me some samples of their blood so we can see. Don't forget to grab that rod!", objectives = "" }
WordHunterWoW_QuestEN[29539] = { title = "Heart of Rage", description = "As it turns out, the eggheads back at Honor Hold can't see much into this place. Bunch of lying lazy mages, is what they are.\n\nEither way, we don't really know exactly what's going on in here. So, you're going in to find out!", objectives = "" }
WordHunterWoW_QuestEN[29540] = { title = "The Breaker", description = "So they've got this big ol' demon stashed away in this place, is what they're telling me. And there's an orc that's in charge of keeping him under wraps.\n\nKilling an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', orcs are always ripe for the slaughter!", objectives = "" }
WordHunterWoW_QuestEN[29542] = { title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Thrallmar is going to be overrun if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Stone Guard Stok'ton. He's in charge of a covert operation to start a Horde invasion on the entire citadel.", objectives = "" }
WordHunterWoW_QuestEN[29543] = { title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Honor Hold is going to be overrun in a matter of time if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Advance Scout Chadwick. He's in charge of a covert operation to start an Alliance invasion on the entire citadel.", objectives = "" }
WordHunterWoW_QuestEN[29544] = { title = "The Blood Furnace", description = "Caza'rez awaits you within the Blood Furnace. He's already cleared out a small area and has our scryers hard at work figuring out what's going on down there.\n\nBut I don't trust that scrying will be enough. I'm sure Caza'rez has plans in mind for a solid blade or two. I want you to go there and lend him your expertise in dealing with the fel orcs. ", objectives = "" }
WordHunterWoW_QuestEN[29545] = { title = "The Blood Furnace", description = "This war is far from over. We need to stop the flow of new recruits to the fel orc front if we are to have any hope of victory.\n\nTravel to the Blood Furnace and speak with Gunny, he's secured a small area within and I'm sure he could use your assistance. Be forewarned, Gunny is...unusual.", objectives = "" }
WordHunterWoW_QuestEN[29547] = { title = "The King's Command", description = "Greetings, {class}.\n\nI have been asked to assemble a team for a high priority mission.\n\nPlease come to Stormwind Keep immediately for a briefing with King Varian Wrynn. I will be waiting in the King's war room.", objectives = "" }
WordHunterWoW_QuestEN[29548] = { title = "The Mission", description = "Well, you heard the King. Admiral Taylor's last transmission came from somewhere in the southern seas.\n\nWe will begin our search from the air! Locating the Prince - the White Pawn - is of critical priority.\n\nThe Skyfire is fueled, supplied, and ready to depart. She and her crew idle in the sky just north of the harbor.\n\nMake your last preparations, then meet Admiral Rogers on the deck. We will depart without delay.", objectives = "" }
WordHunterWoW_QuestEN[29552] = { title = "Critical Condition", description = "We may have won the first battle, but a critical task still remains.\n\nDozens of Skyfire pilots were shot down during the initial aerial battle.\n\nWithout medical aid, their condition will deteriorate over time, until they finally perish. We are their only hope for survival.\n\nGo into the orchard and revive as many pilots as you can find.\n\nWe will leave no one behind.", objectives = "" }
WordHunterWoW_QuestEN[29553] = { title = "The Missing Admiral", description = "Alright. According to the clues you found, that was Anduin's ship, and Admiral Taylor was the captain. \n\nAnd Admiral Taylor's last entry says he was going to fight off the hozen and protect the vessel after the shipwreck.\n\nThe locals say these hozen sometimes take prisoners, and I didn't see Taylor's corpse anywhere among the wreckage. So you'll probably find Taylor at the hozen encampment to the northeast.\n\nGet going, we have no time to lose!", objectives = "" }
WordHunterWoW_QuestEN[29555] = { title = "The White Pawn", description = "Alright, soldier. I've got a critical mission for you.\n\nGet down to the coastline south of here - in the cove there you'll find a wrecked Alliance vessel. I need you to search it and find out if it was the ship that was carrying Anduin. \n\nThen, recover the Captain's Log and see if it has any information on where we can find him.\n\nSince the log is from a military ship, it'll be written using a cipher - take it to Nodd Codejack afterwards. He's keeping watch on the wreck from the other end of the cove.", objectives = "" }
WordHunterWoW_QuestEN[29556] = { title = "Hozen Aren't Your Friends, Hozen Are Your Enemies", description = "We've located an Alliance wreck to the south. Unfortunately, the locals have informed us that it's currently being scavenged by a group of creatures called \"hozen.\"\n\nBy pillaging our wrecked ships, these creatures have already shown that they aren't friendly. We can't have them taking spoils from our ships, stealing our supplies, and worse, potentially capturing or killing any survivors.\n\nGet down there and take them out! When you're done, meet up with Nodd Codejack, our SI:7 agent in the area.", objectives = "" }
WordHunterWoW_QuestEN[29558] = { title = "The Path of War", description = "I see you want to save your friend. I can help you, if you will help me.\n\nFirst of all, it should be obvious that the fewer the Slingtail roaming around, the easier it will be to escape.\n\nKill the hozen guards around us, and we will be one step closer to freedom.", objectives = "" }
WordHunterWoW_QuestEN[29559] = { title = "Freeing Our Brothers", description = "You may be an outsider, but you and I have a common enemy in the hozen.\n\nMany members of my tribe are trapped in cages nearby. I have also seen your... Alliance... soldiers as well.\n\nI cannot leave without freeing my brethren, just as you cannot leave yours.\n\nThe Slingtail hold the keys to those cages. Find the keys and free our friends.", objectives = "" }
WordHunterWoW_QuestEN[29560] = { title = "Ancient Power", description = "Hozen skulls are prized tokens among my village.\n\nWe use them to perform ceremonial rites, and the older the skull, the more potent its magic.\n\nLuckily for us, the hozen are careless, filthy beasts. They leave the skulls of their dead scattered among their huts and campfires.\n\nCollect these skulls for me, and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[29562] = { title = "Jailbreak", description = "Without healing, your friend Taylor will die. My village is just east of here, in the middle of the large lake.\n\nI will take Taylor myself, but the fighting is most dangerous in that direction.\n\nI need you to help clear a path through the hozen, so that I may run safely into my village.\n\nCan you do this?", objectives = "" }
WordHunterWoW_QuestEN[29563] = { title = "Lost in Action", description = "You have to help me! We were sent here to investigate the various parts of the reservoir, but my friends haven't come back yet, and it's been a long time.\n\nThat's why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb went this way.", objectives = "" }
WordHunterWoW_QuestEN[29564] = { title = "A Brother Betrayed", description = "My village was able to escape the naga onslaught at first. We would have all made it to Nagrand had it not been for my brother. He sold our souls for his own freedom.\n\nNow he works here as a slave driver, whipping his own brothers until their backs bleed. Make Mennu pay, {race}.", objectives = "" }
WordHunterWoW_QuestEN[29565] = { title = "The Heart of the Matter", description = "From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and Quagmirran, were among the first enslaved by the naga when they arrived. They helped to subjugate many of the native races of Zangarmarsh.\n\nThough it pains me greatly to ask you to do so, you must put them down.", objectives = "" }
WordHunterWoW_QuestEN[29566] = { title = "Checking Up", description = "These marshes are beautiful, wouldn't you agree? That is, except for the naga forces draining the water away.\n\nI sent a small expedition to the Coilfang Reservoir to investigate the naga, and they haven't returned. I'm concerned that something has happened to them.\n\nWould you travel to the Slave Pens underneath Serpent Lake and find Watcher Jhang?", objectives = "" }
WordHunterWoW_QuestEN[29567] = { title = "Stalk the Stalker", description = "The spore giants may be attacking my people today, but the marsh walkers have taken more innocent lives than any creature I've ever seen. They are our ancient enemies.\n\nTheir brood mother, the Black Stalker, resides deep within this bog. If you were to destroy her and bring me her brain as proof, I would tell tales of your bravery to my grandchildren.", objectives = "" }
WordHunterWoW_QuestEN[29568] = { title = "A Necessary Evil", description = "Hungarfen and Quagmirran used to jointly rule over the spore giants. With Quagmirran gone, the burden rests solely on Hungarfen's tendrils.\n\nWe have no choice but to put the giant down before he can be enslaved and turned into a weapon.", objectives = "" }
WordHunterWoW_QuestEN[29570] = { title = "Rescuing the Expedition", description = "The last members of my expedition are somewhere in here. We're going to need the knowledge they've gathered and their skills if we're to have any chance at defeating the naga.\n\nSee if you can find Earthbinder Rayge and Windcaller Claw, and make sure they're ok.", objectives = "" }
WordHunterWoW_QuestEN[29571] = { title = "Defending the Wilds", description = "The Earthen Ring often finds itself working closely with the druids of the Cenarion Circle. Now is one such time.\n\nTravel north to the Underbog and speak with Watcher Jhang. She is in charge of an expedition in the Coilfang Reservoir to stop the naga there and save Zangarmarsh.", objectives = "" }
WordHunterWoW_QuestEN[29573] = { title = "Safety is Job One", description = "It's nearly safe for our men to come in here and take what's rightfully ours. The real danger now is Shaffar's personal army that he has crawling all over this place.\n\nI need you to take care of his forces for me while I regain my strength.", objectives = "" }
WordHunterWoW_QuestEN[29574] = { title = "Intriguing Specimens", description = "There is a creature not far inside these halls called Pandemonius who is able to twist void energies to sustain and empower itself.\n\nA bit further in lies Tavarok, a being that takes those same void energies and converts them into a crystalline structure stronger than any I've ever seen!\n\nI absolutely must obtain samples for further study.", objectives = "" }
WordHunterWoW_QuestEN[29575] = { title = "Undercutting the Competition", description = "With his ward in place and his forces ready, Nexus-Prince Shaffar has been able to pillage this place for all it's worth without so much as an ounce of trouble.\n\nUnsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a hefty bounty on Shaffar's head.", objectives = "" }
WordHunterWoW_QuestEN[29576] = { title = "An Air of Worry", description = "My sight has long since faded, but when the wind is right I can still smell the blossoms of Nectarbreeze Orchard as if they were in my own palm.\n\nToday, though, their fragrance is muddled with smoke. Please, if you are able, check in on the orchard and see that things are okay. Perhaps my old nose is playing tricks on me.\n\nYou'll find the orchard to the southwest, beyond the statue of the Jade Serpent.", objectives = "" }
WordHunterWoW_QuestEN[29577] = { title = "Ashyo's Vision", description = "Have a look at that!\n\n<Ashyo motions at the massive waterfall to the north.>\n\nThis must be the water supply for the whole valley!\n\nThink about it, {name}: the pandaren use this water to grow vegetables the size of a house. Where could it come from? What is so special about it?\n\nThe elders among my people know a technique for speaking with the water and divining the future. Perhaps this same technique can provide insight into the water's source...\n\nIt's worth a shot at least!", objectives = "" }
WordHunterWoW_QuestEN[29578] = { title = "Defiance", description = "The damn mogu hit us out of nowhere! Anyone they don't kill on sight is being dragged away into the woods.\n\nThis is the only safehouse, and its all I can do to hold the door.\n\nWhat do you say, friend? Are you willing to stand up and fight for the weak?", objectives = "" }
WordHunterWoW_QuestEN[29579] = { title = "Rally the Survivors", description = "The people of this village are simple farmers - not fighters like you and I. Still, they are stubbornly defending their homes as best they can.\n\nSearch the village for anyone still on their feet and tell them to rally here at Hanae's place.", objectives = "" }
WordHunterWoW_QuestEN[29580] = { title = "Orchard-Supplied Hardware", description = "They may not be weaponmasters, but many of these farmers can wield a simple hoe or a rake as an extension of their own will.\n\nThat mastery coupled with the right motivation could muster a force capable of standing against the mogu.\n\nIf you can bring back some tools from the orchard, I'll distribute them to anyone willing to fight.", objectives = "" }
WordHunterWoW_QuestEN[29581] = { title = "The Golden Dream", description = "Ashyo must have experienced what we call the golden dream.\n\nMany of us working here have seen it, too - often after a long day of toiling in the pools. It is said this vision--and the feeling of elation it brings--is a reward to the mind for working the body.\n\nThere IS an easier way, though we rarely resort to it anymore: a tea can be brewed using lotus root and dreamleaf, which grows around the shrine on the upper tier.\n\nBring the dreamleaf to Yan back in town and he can brew the tea for you.", objectives = "" }
WordHunterWoW_QuestEN[29582] = { title = "Grek's Crazy Night", description = "Grek had bad night last night.\n\nShiny mummy man came into Grek's house and told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read wanted poster!\n\n<Grek's face lights up.>\n\nGrek knows! You go find shiny mummy man and tell him Grek sent you. It perfect plan!", objectives = "" }
WordHunterWoW_QuestEN[29583] = { title = "Eckert the Mad", description = "I'm a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen.\n\nDo they call me those things? No.\n\nBut you have one run-in with an ethereal and all of the sudden everyone and their mother calls you \"the mad\".\n\nI saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!", objectives = "" }
WordHunterWoW_QuestEN[29585] = { title = "Spitfire", description = "We've tended these orchards and made cider from their nectar for generations. In that time, we've learned a special trick for putting out fires in a pinch.\n\n<Hanae pushes a jug of cider into your hand.>\n\nThe cider itself - when mixed with crushed gingerleaf and saliva - quickly becomes sticky and viscous. Perfect for smothering flames.\n\nPlease, while you're out there, try to get the flames under control. I've already mixed in the gingerleaf, just swig and spit.", objectives = "" }
WordHunterWoW_QuestEN[29586] = { title = "The Splintered Path", description = "First... before the war-cries... we heard the trees.\n\nGroaning, creaking, and finally crashing down as the mogu cut their way through the woods. They were making the return trip easier...\n\nThey're dragging our friends back down that path, to the ruins west of the village! Those ruins have been empty for years - our children play there.\n\nWhy would the mogu come back to them now?", objectives = "" }
WordHunterWoW_QuestEN[29587] = { title = "Unbound", description = "Can you see them, {name}? Farmers from the orchard, tied up and under inspection. Being hauled off in chains.\n\nThe mogu value strength above all else. Anyone deemed fit for work will be sent to toil under their cruel whips.\n\nAs for the others, well...\n\nLet's not waste any more time.", objectives = "" }
WordHunterWoW_QuestEN[29590] = { title = "The Dead Watcher", description = "A terrifying otherworldly being haunts both the spirit and physical worlds. We call it Shirrak.\n\nIt can only be harmed in your realm. Please help rid us of this nightmare.", objectives = "" }
WordHunterWoW_QuestEN[29591] = { title = "Raging Spirits", description = "The Auchenai have turned their backs on everything we used to stand for. They've taken to raising the dead as unholy minions!\n\nThis cannot stand. Put the spirits back to rest, and massacre those responsible for raising them into undeath. ", objectives = "" }
WordHunterWoW_QuestEN[29593] = { title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", objectives = "" }
WordHunterWoW_QuestEN[29594] = { title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", objectives = "" }
WordHunterWoW_QuestEN[29595] = { title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.", objectives = "" }
WordHunterWoW_QuestEN[29596] = { title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.", objectives = "" }
WordHunterWoW_QuestEN[29598] = { title = "Taretha's Diversion", description = "It was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges.", objectives = "" }
WordHunterWoW_QuestEN[29599] = { title = "Escape from Durnholde", description = "I have plans for my people, stranger.\n\nOne day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nWe will leave when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[29600] = { title = "Snap Judgment", description = "These pools are very special: they nurture life like nothing else in Pandaria.\n\nUnfortunately this means they draw all kinds of attention from local fauna. Recently, dragon turtles have discovered that toadspawn pools are common on the tier just above us. They're running wild up there, trampling the lotuses and snapping at my workers.\n\nThey aren't much of a threat on their own, but in groups they can be pretty nasty. Please, if you can spare your strength, help clear them out.", objectives = "" }
WordHunterWoW_QuestEN[29601] = { title = "The Darkmoon Field Guide", description = "Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you.\n\nIt can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave.", objectives = "" }
WordHunterWoW_QuestEN[29605] = { title = "Brother Against Brother", description = "The Sethekk departed Skettis when Auchindoun exploded.\n\nMy brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god.\n\nIn time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka. Will you help me rescue her?", objectives = "" }
WordHunterWoW_QuestEN[29606] = { title = "Terokk's Legacy", description = "Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind.\n\nDarkweaver Syth still holds his mask and Talon King Ikiss guards his spear.\n\nIt would mean a great deal to my people if these items were returned to us.", objectives = "" }
WordHunterWoW_QuestEN[29607] = { title = "Eyes of Desire", description = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here.\n\nIf you were to bring me some of these rare gems, I would cut you a portion of the profits.\n\nDo we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[29608] = { title = "Allies in Dalaran", description = "Welcome to Northrend, {name}. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there.\n\nRide the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately.\n\nShe can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.", objectives = "" }
WordHunterWoW_QuestEN[29609] = { title = "Friends in Dalaran", description = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city.\n\nSpeak with me and accept a ride to Dalaran. Once you land, make your way to The Filthy Animal.\n\nMake contact with Uda the Beast immediately.\n\nShe can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.", objectives = "" }
WordHunterWoW_QuestEN[29611] = { title = "The Art of War", description = "Lok'tar ogar, {race}. I am Nazgrim.\n\nYou are hereby ordered to present yourself at Grommash Hold immediately.\n\nAll in service to the Horde are to swear an oath of allegiance to their new Warchief.\n\nDo not keep him waiting, {race}.", objectives = "" }
WordHunterWoW_QuestEN[29612] = { title = "The Art of War", description = "Lok'tar Ogar, old friend. It has been too long since last we spoke.\n\nIt is good to see that you emerged safely from the depths of Vashj'ir.\n\nI am stationed here in Grommash Hold.\n\nAll in service to the Horde are to swear allegiance to their new Warchief.\n\nYou would do well not to keep him waiting, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29613] = { title = "A Proper Fate", description = "Warlord Kalithresh is in charge of the entire Steamvault operation.\n\nI need you to kill him, {name}. The naga have left us with no option but violence.\n\nShow him no mercy.", objectives = "" }
WordHunterWoW_QuestEN[29614] = { title = "Containment is Key", description = "The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault.\n\nClear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!", objectives = "" }
WordHunterWoW_QuestEN[29615] = { title = "Windcaller Claw and the Water Thief", description = "The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts.\n\nTaking her out would seriously hinder their operation.", objectives = "" }
WordHunterWoW_QuestEN[29616] = { title = "Storming the Steamvault", description = "We have not as of yet been able to stop the naga in the Steamvault, where most of their pumping infrastructure is located.\n\nThankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?", objectives = "" }
WordHunterWoW_QuestEN[29617] = { title = "Tian Monastery", description = "People come from all over Pandaria to train at the Tian Monastery, just to the north of here. Probably because they never turn anybody down. They'll accept jinyu, hozen... or even a foreign {race} like you!\n\nMy childhood friend, Lin, just joined the monastery's order a few weeks ago. If you're interested in learning how our monks train, maybe you should go talk with her!", objectives = "" }
WordHunterWoW_QuestEN[29618] = { title = "The High Elder", description = "How strange, to have such a foreign-looking {class} visiting our temple. Are you here to study?\n\nYou... you look very strong. You wouldn't have any trouble getting accepted into the monastery. You should talk to the High Elder, up on the balcony above.", objectives = "" }
WordHunterWoW_QuestEN[29619] = { title = "A Courteous Guest", description = "I heard, I heard! The High Elder wants you to train with us!\n\nThere's going to be a banquet for us, the trainees... and you should probably bring a gift, as a sign of courtesy.\n\nThe oranges in the grove south of the temple are extra-sweet right now. Bring some back, for the banquet.", objectives = "" }
WordHunterWoW_QuestEN[29620] = { title = "The Great Banquet", description = "The banquet should be starting any time now. Go find the High Elder and pay your respects. I'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[29622] = { title = "Your Training Starts Now", description = "<Xiao does not look up from his bowl.>\n\nHey, new guy! Glad to see you survived the banquet! Trial One: Complete!\n\n<Xiao eats noisily.>\n\nYou'd better speak up with Instructor Xann. He'll be expecting you for your daily exercises.\n\n<He continues eating. You suspect that he is done talking to you.>", objectives = "" }
WordHunterWoW_QuestEN[29623] = { title = "Perfection", description = "Perfection can be achieved through repetition. Every single student in the training arena below will eventually perfect his or her form... assuming they don't give up first. This is a fact.\n\nI encourage you to join them, {name}. As an honorary guest of the monastery, you are not required to perform the requisite 10,000 daily strikes. Simply follow the leader's example for a few minutes.", objectives = "" }
WordHunterWoW_QuestEN[29624] = { title = "Attention", description = "Your next test also involves concentration and attention. I want you to practice your abilities on the training bags in the pit below.\n\nThe bags are hung in groups of two. When I call out \"Left\", attack the bag on the left. When I call out \"Right\", attack the bag on the right.\n\nIf you fail to follow my simple directions, this task will become much harder.\n\nNow beat on those practice bags until they burst, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29626] = { title = "Groundskeeper Wu", description = "We don't have many rules here, but we do have one particular rule that is worth remembering. If you want to eat...\n\n<Xiao's stomach grumbles audibly.>\n\n...you have to work. Groundskeeper Wu can give you your chores for the day. He's in the market, to the west.", objectives = "" }
WordHunterWoW_QuestEN[29627] = { title = "A Proper Weapon", description = "First things first, though.\n\nA proper trainee needs a proper weapon. And a scrupulous trainee builds his own... or at least gathers the materials.\n\nThe switches which grow nearby should suffice for any respectable weapon. You'll also need to shop for black walnut extract to treat the wood. While you're there, get some ale, for...\n\n<Wu pauses.>\n\n...well, you know what ale is for.", objectives = "" }
WordHunterWoW_QuestEN[29628] = { title = "A Strong Back", description = "Some of our trainees have... larger-than normal appetites. We have occasionally had difficulty supplying enough food for all of them. In times like these, we have to ask for help.\n\nA kindly older woman, who lives in a small house to the northwest, has agreed to make some stew for our trainees. All you need to do is go and get it.", objectives = "" }
WordHunterWoW_QuestEN[29629] = { title = "A Steady Hand", description = "The black walnut extract you purchased from Miss Whiteblossom is but one of many extracts we keep in stock for various applications.\n\nBlushleaf extract can be gathered from the flowers in the Waxwood Forest to the west. Several units can be extracted from one flower, but only those with calm nerves and steady hands can remove all of the extract from one flower.", objectives = "" }
WordHunterWoW_QuestEN[29630] = { title = "And a Heavy Fist", description = "The greenwood sprites in the Waxwood Forest to the west pose no direct threat to us, this is true. However, their numbers have increased as of late, as have their wily antics.\n\nPart of our duty as wardens of this forest is to maintain the balance. Your duty is to do so by returning these sprites to the earth.", objectives = "" }
WordHunterWoW_QuestEN[29631] = { title = "Burning Bright", description = "Might I ask a favor of you, trainee {name}?\n\nBefore I came to the monastery, I was a stranger to battle. During my time as a trainee, I performed adequately, but I was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am expected to protect this perimeter at all costs.\n\nI can handle greenwood sprites, but the tigers in the western Waxwood are something different altogether. Would you mind taking care of them for me?", objectives = "" }
WordHunterWoW_QuestEN[29632] = { title = "Becoming Battle-Ready", description = "Alright, {race}. I'd like to see what you're really made of.\n\nYou'll find my pupils all over the monastery. Challenge them to fights. Push them to their limits. They have been instructed to do the same to you.\n\nWin or lose, you both will come out of the fight stronger.", objectives = "" }
WordHunterWoW_QuestEN[29633] = { title = "Zhi-Zhi, the Dextrous", description = "Upon the hills to my right, you will find a hozen named Zhi-Zhi. He, too, won enough sparring matches to move up the ranks. I think he will provide you with more of a challenge.\n\nChallenge him, and try to defeat him.", objectives = "" }
WordHunterWoW_QuestEN[29634] = { title = "Husshun, the Wizened", description = "The jinyu are long-standing allies of the pandaren, and we welcome any of their kind into our monastery. Husshun, one of their elder shaman, is one of our newest trainees.\n\nHis skills as a monk are mediocre at best, but he is still a fierce combatant. He should provide you with the challenge that you deserve.", objectives = "" }
WordHunterWoW_QuestEN[29635] = { title = "Xiao, the Eater", description = "You may have already met my best student, Xiao, at the banquet tables. I personally would have graduated him several times over, but Instructor Xann insists that he needs more discipline.\n\nIf you ask me, discipline means very little if you win every fight you enter. I'm curious to see if Xiao can keep his streak alive against you.", objectives = "" }
WordHunterWoW_QuestEN[29636] = { title = "A Test of Endurance", description = "I have taught you everything that I can, {name}. It is time you spoke with Instructor Myang.\n\nThe fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait.\n\nFarewell, {name}, and best of luck on the remainder of your training.", objectives = "" }
WordHunterWoW_QuestEN[29637] = { title = "The Rumpus", description = "Master Stone Fist has trained you in the art of one-on-one combat. Now you learn the art of one-on-many.\n\nHow does fifty sound?\n\nLower yourself into the Ring of Inner Focus below, then, when you're ready, set off this firework. My assistants will come at you, several at a time.\n\nAll you need to do is survive.", objectives = "" }
WordHunterWoW_QuestEN[29639] = { title = "Flying Colors", description = "You have passed every test we prepared for you, {name}. It is now time for you to move on to bigger and better things.\n\n...but not before another banquet. The High Elder will be waiting for you at the banquet grounds to celebrate your graduation from our monastery.", objectives = "" }
WordHunterWoW_QuestEN[29640] = { title = "Find Spy To'gun", description = "The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in!\n\nYou must find him. He may be reckless, but we need to find out what he knows.", objectives = "" }
WordHunterWoW_QuestEN[29641] = { title = "The Soul Devices", description = "They've been torturing me, trying to get me to tell them everything that I know.\n\nThey fed the others to Hellmaw, and I was to be next. But I told them nothing!\n\nThey're using special devices to make their summoning more powerful. You must steal these devices!", objectives = "" }
WordHunterWoW_QuestEN[29642] = { title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", objectives = "" }
WordHunterWoW_QuestEN[29643] = { title = "The Codex of Blood", description = "Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake.\n\nRead the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.", objectives = "" }
WordHunterWoW_QuestEN[29644] = { title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!", objectives = "" }
WordHunterWoW_QuestEN[29645] = { title = "Ambassador Hellmaw", description = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one.\n\nOur men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw.\n\nIt is a most deserving fate.", objectives = "" }
WordHunterWoW_QuestEN[29646] = { title = "Flying Colors", description = "Well, I've done all that I can with you. Sounds like the others have, too.\n\nHigh Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate your departure. Not that we're happy you're leaving... he just enjoys celebrations.", objectives = "" }
WordHunterWoW_QuestEN[29647] = { title = "Flying Colors", description = "The Rumpus was your final test. You have mastered the disciplines taught at this monastery.\n\nJust as your training began with a banquet, so shall it end. High Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[29649] = { title = "How to Save a Life", description = "Gunny is dying from a powerful curse, {name}.\n\nGrand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?", objectives = "" }
WordHunterWoW_QuestEN[29650] = { title = "Fel Ember", description = "Caza'rez is dying a coward's death.\n\nGrand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?", objectives = "" }
WordHunterWoW_QuestEN[29651] = { title = "Honor the Dying", description = "Their elite warriors are ruthless... so... powerful.\n\n<Caza'rez spits up blood.>\n\nYou have to kill them... or we will never defeat Kargath...\n", objectives = "" }
WordHunterWoW_QuestEN[29652] = { title = "One Last Favor", description = "Ol' Gunny doesn't have much longer...\n\nDo me one last favor, and kill the biggest, meanest fel orcs ye can find.\n\nFor old times' sake, aye?", objectives = "" }
WordHunterWoW_QuestEN[29653] = { title = "The Will of the Warchief", description = "Kargath was once one of the Horde's greatest heroes.\n\nHe now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.", objectives = "" }
WordHunterWoW_QuestEN[29654] = { title = "Turning the Tide", description = "There is only one true way to end the fel orc threat to Honor Hold and the Alliance.\n\nTheir Warchief must be slain.\n\nBring me his namesake weapon, so that we can always remember his death.", objectives = "" }
WordHunterWoW_QuestEN[29655] = { title = "A Very Special Cloth", description = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful.\n\nTake him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!", objectives = "" }
WordHunterWoW_QuestEN[29656] = { title = "O'mrogg's Warcloth", description = "Stormwind wants to see proof of our successes in the war effort.\n\nRather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?", objectives = "" }
WordHunterWoW_QuestEN[29657] = { title = "With Great Power, Comes Great Responsibility", description = "<A voice like the sound of light bells rings in your head.>\n\nThe Mechanar employs my race's technology to create manacells, objects which provide great amounts of power.\n\nI need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.", objectives = "" }
WordHunterWoW_QuestEN[29658] = { title = "The Calculator", description = "<A gentle wind caresses your face.>\n\nOne more task yet remains.\n\nPathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world.\n\nI ask that you eliminate him.", objectives = "" }
WordHunterWoW_QuestEN[29659] = { title = "Lost Treasure", description = "I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion.\n\nWe cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.", objectives = "" }
WordHunterWoW_QuestEN[29660] = { title = "Saving the Botanica", description = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs.\n\nThe first step is to eliminate their forces so that they cannot cause further problems.", objectives = "" }
WordHunterWoW_QuestEN[29661] = { title = "The Lesson of Dry Fur", description = "Through meditation, I intend to find a route to locating Shu. In the meantime, you would benefit from practice and discipline.\n\nYour first task is the task of all trainees entering the pools: cross the balance poles to the west and ring the bell without falling into the pool.\n\nShould you fall, the pool's curse will make it difficult to get on a pole again, so you will need to return to the edge of the pool to start over.\n\nOh, and beware the cranes.", objectives = "" }
WordHunterWoW_QuestEN[29662] = { title = "Stronger Than Reeds", description = "Gather me reeds from the nearby pools.\n\nDo not question why. Do, and then observe the results.", objectives = "" }
WordHunterWoW_QuestEN[29663] = { title = "The Lesson of the Balanced Rock", description = "I require peace to perform my meditation. Practice your arts while I meditate on Shu's location.\n\nOther monks practice balance and combat upon the balance poles in the surrounding pools. Engage them and defeat them.", objectives = "" }
WordHunterWoW_QuestEN[29664] = { title = "The Challenger's Fires", description = "You're strong of mind and strong of will, but you lack the skills to face me in combat. You must fight with your body, but in truth, it is your character that is being tested.\n\nLet us even the playing field.\n\nTake this torch, light it in the brazier next to me, and then use it to light the three unlit braziers around the pool.", objectives = "" }
WordHunterWoW_QuestEN[29665] = { title = "From Bad to Worse", description = "After their ship crashed, evil creatures swept up from the sea to pick through the wreckage. Our aid may seem but a drop in the pond at the thought of the misfortune they've faced today.\n\nDefeat their tormentors. These people desperately need our help.", objectives = "" }
WordHunterWoW_QuestEN[29666] = { title = "The Sting of Learning", description = "There are dangers in the pools. The latest and most vicious are the water pincers. A time has come for their numbers to be diminished, and I am no longer up to the task.\n\nIf you could clear out some of the water pincers, I would be very appreciative. Beware their numbers... sometimes it's best to lure them from the pool-side rather than wading all the way in.", objectives = "" }
WordHunterWoW_QuestEN[29667] = { title = "Culling the Herd", description = "It seems that Kael'thas' forces have twisted the Botanica's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have.\n\nThere is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.", objectives = "" }
WordHunterWoW_QuestEN[29669] = { title = "A Most Somber Task", description = "I must now ask you to complete a most somber task.\n\nWarp Splinter used to act as guardian to all of the Botanica. He is now impure, and must be taken down.", objectives = "" }
WordHunterWoW_QuestEN[29670] = { title = "Maul Gormal", description = "Thanks to you, there's a small militia of farmers hiding nearby. Hanae said something about giving them \"liquid courage\" which, I'm pretty sure, means they're sauced and ANGRY.\n\nThe mogu think they can walk all over us - we'll give them a fight that will open their eyes.\n\nFollow the trail through the ruins and down to the beach. Find their leader. When you engage him, we'll be there to back you up.", objectives = "" }
WordHunterWoW_QuestEN[29674] = { title = "Unbound Darkness", description = "<The sound of chimes enters your head, but it is distressed.>\n\nWe imprisoned the most dangerous beings we came across in our travels.\n\nZereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.", objectives = "" }
WordHunterWoW_QuestEN[29675] = { title = "Hey There Dalliah", description = "Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer, have begun rallying the demons on board together into a small army.\n\nYou cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.", objectives = "" }
WordHunterWoW_QuestEN[29676] = { title = "Finding an Old Friend", description = "It seems Shu, the spirit of water, had a play companion when he came to the pools throughout the years. An old pandaren we know as Old Man Liang.\n\nLiang moved away from the main town and stopped practicing in the pools some time ago. I am told he lives in a small house northeast of here, up the hill.\n\nLiang may know what has driven Shu away, and where the spirit might be found.\n\nGo to Liang. Ask of Shu.", objectives = "" }
WordHunterWoW_QuestEN[29677] = { title = "The Sun Pearl", description = "Shu, the spirit of water, is eternally young, as are all the spirits of Shen-zin Su. I have been friends with Shu all of my life, but I no longer have it within me to play with him. I am old, and lack the energy.\n\nFor all his complexities, Shu is simple to please: he desires friendship. When I returned to play with Shu each season, I would always bring a Sun Pearl as a gift, and then we would play together. You can find a Sun Pearl in the pools to the southeast. Perhaps you can be his new friend.", objectives = "" }
WordHunterWoW_QuestEN[29678] = { title = "Shu, the Spirit of Water", description = "Shu, the spirit of water, is sulking in the deep pool to the north. Cross the rocks and then drop the sun pearl in the center of the pool. He will know what this means.", objectives = "" }
WordHunterWoW_QuestEN[29679] = { title = "A New Friend", description = "He wants you to play with him. Go for it!", objectives = "" }
WordHunterWoW_QuestEN[29680] = { title = "The Source of Our Livelihood", description = "We have done as Master Shang asked of us. I will return to the temple to inform the master of our progress. You should continue south on the road to the farmlands to seek out Wugou, the spirit of earth.\n\nJi awaits you at the Dai-Lo Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his directness. Remember well the things I have taught you: discipline and patience.", objectives = "" }
WordHunterWoW_QuestEN[29681] = { title = "Maximum Security Breakout", description = "Harbinger Skyriss is the heart of the problem in the Arcatraz.\n\nHe corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose.\n\n{name}, you cannot let a servant of the Old Gods live!", objectives = "" }
WordHunterWoW_QuestEN[29682] = { title = "Magisters' Terrace", description = "We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there.\n\nHowever, we haven't heard from them since, and I fear the worst.\n\nWill you go there and try to find Exarch Larethor? He's in charge of the expedition.", objectives = "" }
WordHunterWoW_QuestEN[29684] = { title = "Severed Communications", description = "We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him.\n\nThe information he was collecting is vital to our mission.", objectives = "" }
WordHunterWoW_QuestEN[29685] = { title = "Hard to Kill", description = "As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[29686] = { title = "A Radical Notion", description = "We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die.\n\nThe Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.", objectives = "" }
WordHunterWoW_QuestEN[29687] = { title = "Twisted Associations", description = "The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply.\n\nFrom what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.", objectives = "" }
WordHunterWoW_QuestEN[29688] = { title = "Advancing the Campaign", description = "I mostly listen, {class}. I listen so that the Warchief doesn't have to.\n\nI've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls, seat of power for the fel orcs.\n\nGo speak with Stone Guard Stok'ton, he's in charge there.", objectives = "" }
WordHunterWoW_QuestEN[29689] = { title = "Advancing the Campaign", description = "The time has come to lay the final blow against the fel orcs.\n\nAdvance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!", objectives = "" }
WordHunterWoW_QuestEN[29690] = { title = "Into the Mists", description = "<Nazgrim fills his lungs with sea air.>\n\nYou smell that, {name}? It's the smell of our home, the lands our kind have bled and died to preserve.\n\nAnd listen... you hear that? It's the sound of peace and safety - a haven we've carved, where our enemies fear to tread.\n\nRemember these things. You won't experience them again anytime soon. We have ourselves a war to win.\n\nNow go get settled, we're shovin' off!", objectives = "" }
WordHunterWoW_QuestEN[29691] = { title = "Bring Me A Shrubbery!", description = "My people use sanguine hibiscus for a number of purposes.\n\nIt grows naturally only in the Underbog, and many of the bog's denizens have taken a liking to it.\n\nIf you could bring me some, I would be very grateful.", objectives = "" }
WordHunterWoW_QuestEN[29693] = { title = "The General's Edge", description = "As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage.\n\nIt occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling...\n\nYou know that dead or alive, the General would want his weapon back in his possession.", objectives = "" }
WordHunterWoW_QuestEN[29694] = { title = "Regroup!", description = "They have an airbase! I have underestimated this Alliance Captain for the last time. So many good warriors lost...\n\nThere must have been a few survivors who were able to bail during the crash. We need every able-bodied fighter we can get.\n\nFind as many survivors as you can in the forest below, and I will investigate the wreckage itself. Rally everyone together at the nearby village for a counter-attack.", objectives = "" }
WordHunterWoW_QuestEN[29696] = { title = "My Stars!", description = "A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you.\n\nThe bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished.\n\nIf you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.", objectives = "" }
WordHunterWoW_QuestEN[29712] = { title = "Horde Justice", description = "Your mind races as you struggle to come to terms with your predicament - shipwrecked on an uncharted land, nearly all of the crew lost....\n\nAs you look at the corpse of this unfortunate creature you realize that the area is crawling with his kind, and that they're pillaging whatever supplies haven't been destroyed.\n\nIt's time to introduce these vermin to some good old-fashioned Horde justice.", objectives = "" }
WordHunterWoW_QuestEN[29713] = { title = "Standard Protocol", description = "The Sky Shark has been totally destroyed.\n\nWith Alliance forces about, standard protocol requires the destruction of any sensitive technologies. These solenoids most certainly fall under that category.\n\nThe Horde's directives are clear, round up the solenoids for destruction.", objectives = "" }
WordHunterWoW_QuestEN[29714] = { title = "Wet Work!", description = "If any Alliance naval forces have come ashore, the smoky fires from your crash will lead them right to you and what remains of your crew.\n\nThere must be a way to extinguish those flames...\n\nThis barrel seems to have survived the catastrophe intact. Perhaps it's still water-tight.\n\nOnly one way to find out!", objectives = "" }
WordHunterWoW_QuestEN[29715] = { title = "The Witch in the Woods", description = "Oh please {race}!  Can you help me?\n\nSome of the village children were playing in the woods and haven't come back. Could you please keep an eye out for them if you are going out there?\n\nI told those village rascals to leave that old widow up in the woods alone. My guess is they are probably harassing her. They think she is a witch.", objectives = "" }
WordHunterWoW_QuestEN[29716] = { title = "The Double Hozen Dare", description = "There is a witch in the woods but no one believes me. She turned my friend Shin into jade!\n\nWe were all so scared we tried to run back but she sicced her big jade monsters on us. A bunch of my friends tried to get away by climbing trees.\n\nCan you help me save my friends?", objectives = "" }
WordHunterWoW_QuestEN[29717] = { title = "Down Kitty!", description = "I tried to fight one of the jade tigers in the woods but they were too scary. They stare at you and you turn to a jade statue!\n\nHonest truth! Chen's sister's friend Ni heard it from Kai's mom.\n\nI want to be brave like you though. Can you show me how to beat up those jade tigers?", objectives = "" }
WordHunterWoW_QuestEN[29718] = { title = "Sixteen Fluid Ounces of Prevention", description = "Better safe than sorry.\n\nThe pillars of smoke surrounding the crash site will be a beacon to any Alliance who might have seen your Zeppelin in distress.\n\nUntil you and your depleted crew get your bearings, you could do without that kind of trouble.\n\nExtinguishing the wreckage fires is just plain common sense.", objectives = "" }
WordHunterWoW_QuestEN[29720] = { title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it!  I don't want to see the witch.  Can you please go talk to her?  You're an adult.  I don't think she would turn you into jade.", objectives = "" }
WordHunterWoW_QuestEN[29722] = { title = "A Lesson in Bravery", description = "Can you help teach me to be brave like you?\n\nWhen we played our prank on the witch we made a bunch of Leafy Tricksters angry.  I think the witch did something to them.\n\nCan you show me how you stand up to them?", objectives = "" }
WordHunterWoW_QuestEN[29723] = { title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it! I don't want to see the witch. Can you please go talk to her and see if she has Shin?\n\nYou're an adult, I don't think she would try to turn you into jade.", objectives = "" }
WordHunterWoW_QuestEN[29724] = { title = "Burial at Sea", description = "These savages are... ruthless.\n\nThey've dragged off our dying soldiers to be tormented in their camps. This is no way for our valiant brothers to die.\n\nI shall join them soon enough, {class}. Please, put my mind at ease and their bodies to rest.\n\nFind their remains at the camps surrounding the wreckage. Put them out of the reach of these creatures.", objectives = "" }
WordHunterWoW_QuestEN[29725] = { title = "SI:7 Report: Fire From the Sky", description = "Yeah, we found Amber, she's alive, and all that. That's about where the good news stops though.\n\nLet's see if I can pick up where ol' Rell left off...", objectives = "" }
WordHunterWoW_QuestEN[29726] = { title = "SI:7 Report: Hostile Natives", description = "I... I can tell you what happened next! We continued north, into the forest...", objectives = "" }
WordHunterWoW_QuestEN[29727] = { title = "SI:7 Report: Take No Prisoners", description = "The final leg of our journey took us west, to a large hozen village. We set up a small camp in the mountains, outside of their line of sight...", objectives = "" }
WordHunterWoW_QuestEN[29728] = { title = "Explosive Evidence", description = "I must ask you to do one more thing for me, {name}.\n\nThe personal effects on this ship cannot be left for others to find. We'll have to destroy it.\n\nI cobbled together some Makeshift Dynamite from the scraps you brought me.\n\nPlace the dynamite anywhere on the ship, but take care not to put them too close together.\n\nThey might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.", objectives = "" }
WordHunterWoW_QuestEN[29729] = { title = "Without a Trace", description = "The explosives are set. All we have to do now is pull the trigger.", objectives = "" }
WordHunterWoW_QuestEN[29730] = { title = "Scouting Report: Hostile Natives", description = "I bet I know your first question: \"What the ook happened to Sergeant Gorrok?\" Don't worry, don't worry. He's totally alive. Not dead or anything.\n\n<Riko shuffles uncomfortably.>\n\nWell, we THINK he's alive, but he ALSO might be very, very dead.\n\n<Riko looks into your eyes for approval.>\n\nFine! Let me tell you exactly what happened.", objectives = "" }
WordHunterWoW_QuestEN[29731] = { title = "Scouting Report: On the Right Track", description = "MOST of what Riko said is true.\n\nWe didn't dare pursue Gorrok - the Horde's numbers here are far too few. Our forces can only sustain so many losses, and frankly, we don't know how powerful that witch really is.\n\nLet me pick up where the hozen left off...", objectives = "" }
WordHunterWoW_QuestEN[29732] = { title = "What Goes Down, Must Come Up!", description = "Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser.\n\nWith a simple calibration, the device is set to deliver drones to Nazgrim's basecamp.\n\nEasy enough....\n\nThere's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact.\n\nAs you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...", objectives = "" }
WordHunterWoW_QuestEN[29733] = { title = "SI:7 Report: Lost in the Woods", description = "<Rell coughs heavily before speaking.>\n\nPlease, {name}. You need to hear what we've been through.\n\nThe whole damned Alliance needs to hear what we've been through. There may not be much time left.", objectives = "" }
WordHunterWoW_QuestEN[29734] = { title = "Deepforge the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29735] = { title = "Stonebrand the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29736] = { title = "Darkfeather the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29737] = { title = "Firebeard the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29738] = { title = "Moonlance the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29739] = { title = "Windsong the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29740] = { title = "Evershade the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29741] = { title = "Sekhemi the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29742] = { title = "Menkhaf the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[29743] = { title = "Monstrosity", description = "It's plain to see that this statue and the surrounding ruins are of ancient origin. Clearly, this land has a deep history, which means it could not have been born of the cataclysm.\n\nAnd yet these waters have been explored for ages now, with no record of anything here but open sea.\n\nPerhaps if you were to sketch the pieces of this broken statue, you might shed light on the continent's origins.", objectives = "" }
WordHunterWoW_QuestEN[29744] = { title = "Some \"Pupil of Nature\"", description = "Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat.\n\nThese particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted.\n\nSo yeah, that's out.\n\nI guess we'll never know.\n\n<Weng coughs.>\n\nOrrrr... A big brave adventurer like YOU could go check it out! What do you say?", objectives = "" }
WordHunterWoW_QuestEN[29745] = { title = "The Sprites' Plight", description = "<Living statues rampage through the woods.\n\nFor now, they seem content in pummeling the forest sprites into splinters, but if they continue any further the pandaren will have more than just missing jade to worry about.>", objectives = "" }
WordHunterWoW_QuestEN[29747] = { title = "Break the Cycle", description = "<Mogu conjurers call forth hapless spirits from beyond, forcing them into statues.\n\nIt seems that destroying the statues alone will not be enough to break the cycle.>", objectives = "" }
WordHunterWoW_QuestEN[29748] = { title = "Simulacrumble", description = "<The shattered remains of an ancient mogu statue. This one looks like it never animated before it was broken.\n\nWhatever dark magic the mogu are employing here, it seems to make the brittle statues significantly tougher. Better to destroy them while they are still vacant.\n\nA good old-fashioned kick should do the job.>", objectives = "" }
WordHunterWoW_QuestEN[29749] = { title = "An Urgent Plea", description = "<Your mind is racked with a howl. Beneath it, a wispy voice is barely audible, as if from far away.>\n\nPlease... help... heart of the ruins... a ritual... conjuring...\n\n...should not be here...\n\nMy staff... on the altar... take it. Please hurry.", objectives = "" }
WordHunterWoW_QuestEN[29750] = { title = "Vessels of the Spirit", description = "The Spiritclaws are a sect of mogu assassin-priests who, at the height of the mogu empire, were the most elite and most feared of the emperor's troops.\n\nAll have mastered a deathblow which ensnares the spirit of the enemy, trapping it in a jade bottle for delivery to a Spiritbinder.\n\nIf you encounter any Spiritclaws further ahead in the ruins, take note: their belts hang with a cursed weight.\n\nRelieve them of their burden and bring the bottles back to me.", objectives = "" }
WordHunterWoW_QuestEN[29751] = { title = "Ritual Artifacts", description = "So many spirits held in captivity here... I can feel them everywhere. Even the walls are a cage for the long-dead.\n\n{name}, we cannot simply break the sorcery over this place - doing so would release countless agonized souls to wander the earth. They will need a beacon, something to guide them.\n\nWith your help, I can create a tan-chao: a bridge from this world to the heavens. For this ritual, I'll need a bowl, a candle, and a jade cong. You should be able to find them all within the ruins.", objectives = "" }
WordHunterWoW_QuestEN[29752] = { title = "The Wayward Dead", description = "The process of mass conjuring, as the mogu are doing here, is not without byproduct. Some spirits arrive too distraught or unruly to be harnessed, so they are confined and left to wander until their desperation leaves them more malleable.\n\nI suspect the mogu have such a holding area somewhere nearby, likely guarded by spiritclaws.\n\nPlease, take my staff again and use it to collect these wayward spirits. You needn't fight them - present the staff and they should be drawn in.", objectives = "" }
WordHunterWoW_QuestEN[29753] = { title = "Back to Nature", description = "I'm afraid I have another favor to ask, {name}.\n\nThe bottles you recovered contain neither the spirits of mogu ancestors nor recently slain foes; they contain spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to fuel their simulacra.\n\nThis complicates our task, for I cannot take the beasts with me through the bridge.\n\nTake the bottles west to Tideview Thicket and smash them to return the spirits to nature. Some may be blind with rage and will need to be subdued.", objectives = "" }
WordHunterWoW_QuestEN[29754] = { title = "To Bridge Earth and Sky", description = "We are ready to open the tan-chao and guide all of these spirits back to peace.\n\nIf I may, I would have your assistance once more. The mogu will surely sense the ritual taking place and will do everything in their power to halt it. I need only a few moments without interference, and once the path is open it will surge too greatly to be closed.\n\nIf you are willing to help one more time, please accompany me to the ritual site.", objectives = "" }
WordHunterWoW_QuestEN[29755] = { title = "Pei-Back", description = "<Ancestral spirits stream into the tan-chao, Pei-Zhi's bridge to freedom.\n\nOne final chamber lingers in the ruins, just north of the tan-chao. The air above crackles with foul energy. Shan Jitong is already at work.>", objectives = "" }
WordHunterWoW_QuestEN[29756] = { title = "A Humble Offering", description = "I'm almost ready for the ritual, there's just one more thing we need: An offering.\n\nRelax, I don't mean a sacrifice. Just a bit of food.\n\nThere are sure to be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. Please bring some.", objectives = "" }
WordHunterWoW_QuestEN[29757] = { title = "Bottletoads", description = "Have you heard about the crisis we're having at the pools?\n\nToads have moved in and are spawning like crazy! It's become a real problem for the lotus farmers.\n\nCoincidentally, I make a jam out of gelatinous toadspawn. I call it \"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in stock.\n\nIf you're heading to the pools, you'd be doing everyone a favor by uh... liberating some of those toad eggs.\n\nInto this bottle. For me.\n\nJust look for bubbles and scoop right in!", objectives = "" }
WordHunterWoW_QuestEN[29758] = { title = "Guess Whose Back", description = "<This dragon turtle's massive shell is rock-hard and covered in sharp ridges. One of the locals could almost certainly make use of it.>", objectives = "" }
WordHunterWoW_QuestEN[29759] = { title = "Kung Din", description = "I hope you are capable of this next task, for our lives depend on it.\n\nThere is only one key that will unlock our chains. Unfortunately, the key hangs around the neck of the hozen's pet tiger, Kung Din.\n\nThey keep the tiger in the great pit to the north. The only way to retrieve the key will be to kill the beast.", objectives = "" }
WordHunterWoW_QuestEN[29760] = { title = "Pit Fighter", description = "There must be more to being a master pit fighter than this...\n\nPerhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.", objectives = "" }
WordHunterWoW_QuestEN[29762] = { title = "Family Heirlooms", description = "We recently lost a fierce battle against the hozen at Moonwater Retreat.\n\nWe evacuated as many of our people as we could, but still, there were many we could not save.\n\nWe have no tokens of our lost over which to send our prayers.\n\nIf someone could go and retrieve heirlooms from the dead bodies, we could properly lay them to rest, and move on.\n\nIt would mean so much to us if you could do this, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29763] = { title = "Stealing Their Thunder", description = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.", objectives = "" }
WordHunterWoW_QuestEN[29764] = { title = "Disarmament", description = "Take it from me, lad, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nI need you to pilfer some o' them weapons before they're used on us!", objectives = "" }
WordHunterWoW_QuestEN[29765] = { title = "Cryin' My Eyes Out", description = "I coulda taken out da whole lot of 'em, mon.\n\nShot 'em one by one, den played dead when dey be gettin' close. Fell for it every time, dey did - well almost every time...\n\nOne of 'em finally got wise. Called my bluff. Before I knew it, dey was usin' my eyes as marbles.\n\nRan off with my goods an' left me here ta die, da savages...\n\nHelp me, mon. Lemme die wit my dignity intact.", objectives = "" }
WordHunterWoW_QuestEN[29766] = { title = "A Good Start", description = "Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet.\n\nBut first, we must deal with these savages!\n\nYou see these corpses I've stacked up around the camp? I want mountains of them!\n\nWe are the Horde!\n\nThese vermin have not learned to fear us yet, but we will fix that soon enough...", objectives = "" }
WordHunterWoW_QuestEN[29768] = { title = "Missing Mallet", description = "{name}, I've got it! It's simple really. Let's make a ruckus so loud that there's no way he can sleep through it.\n\nWhy look at that, a conveniently placed gong! Makes me think this may just be how they've awoken him in the past. We just need the matching mallet to get it ringing as loud as possible.\n\nThe village leader tells me the mallet is over at the Ki-Han Brewery on the river, to the southwest. It's not far. Mind picking it up for me while I give the village some fair warning?", objectives = "" }
WordHunterWoW_QuestEN[29769] = { title = "Rascals", description = "I'll keep trying to find ways to wake this stubborn little guy up, but there is no shortage of trouble on the island it seems. The crops to the south are infested with virmen, rabbit-like thieves and pillagers.\n\nRascals!\n\nThey breed faster than we can kill them! I have the perfect solution for such a situation: kill them faster! With you here, {name}, that shouldn't be a problem.", objectives = "" }
WordHunterWoW_QuestEN[29770] = { title = "Still Good!", description = "The virmen to the south have been running off with all of our crops, but they're taking more than they can eat. They must be stockpiling them somewhere - the ones they like anyway.\n\nWill you go out and recover any of the uprooted crops you can find? I've got an island's worth of people to feed, and every single vegetable makes a difference.", objectives = "" }
WordHunterWoW_QuestEN[29771] = { title = "Stronger Than Wood", description = "Gather me wood planks from construction near the Ki-Han Brewery.\n\nYou do not yet know the extent of my strength, so I shall display it to you.", objectives = "" }
WordHunterWoW_QuestEN[29772] = { title = "Raucous Rousing", description = "You ready for this, {name}? I'm thinking maybe we should have looked for something to cover our ears, but it's a bit late for that now. Just remember that the intense ringing you'll be hearing for the next few hours is the ringing sound of victory!\n\nThe honor's all yours, {name}. Ring the gong whenever you're ready!", objectives = "" }
WordHunterWoW_QuestEN[29773] = { title = "Wugou, the Spirit of Earth", description = "{name}! Well, the plus side is that finding Wugou was easy enough. Waking him... not so much. I think he's going to wake quite sore from all the pushing and hitting I've done trying to rouse him.\n\nAre you a deep sleeper at all, {name}? What wakes you up in the morning?\n\nRolling out of bed always seems to do it for me, so I figure let's just go for that! I tied off some ropes to the ox cart. We send it running and give him a good roll, and we should be good! Care to give the ox a good slap to get it going?", objectives = "" }
WordHunterWoW_QuestEN[29774] = { title = "Not In the Face!", description = "Alright {name}, I was thinking about what we'd try next if the whole gong thing didn't work, and it came to me just like that! Water in the face always worked on me. It's got to be twice as effective for someone so dry and earthy!\n\nMind going over and asking Shu, the spirit of water, if he'll help us out?  He should be playing in the pool next to the waterfall, just on the other side of that tree.", objectives = "" }
WordHunterWoW_QuestEN[29775] = { title = "The Spirit and Body of Shen-zin Su", description = "Well, that wraps it up here, doesn't it {name}?  Now that we've got these two roused and all friendly towards you, we just need to get them back to the Temple of Five Dawns.\n\nYou go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.", objectives = "" }
WordHunterWoW_QuestEN[29776] = { title = "Morning Breeze Village", description = "The fourth and final spirit is Dafeng, the spirit of air. When he is not in the skies, he can be found on the Ridge of Laughing Winds to the west. I've sent both Aysa and Ji to help you find him.\n\nWhen you are ready, I will summon winds to carry you to the top of the temple. From there, cross the bridges to the west and find Ji in Morning Breeze Village.", objectives = "" }
WordHunterWoW_QuestEN[29777] = { title = "Tools of the Enemy", description = "The hozen have stolen our brushes and are painting over our scrolls of wisdom with their own wisdoms, if you can call them that. If you're here to help, stop them and bring our brushes back before they can do more harm.", objectives = "" }
WordHunterWoW_QuestEN[29778] = { title = "Rewritten Wisdoms", description = "{name}, we must help Elder Shaopai. There are few more deserving of our kindness.\n\nOn the way here, you surely noticed the scrolls of wisdom hanging in the grotto to the south. The hozen have defiled many of them, and sadly, they are not recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the hozen writings away entirely.\n\nDo not worry for Elder Shaopai. The people shall come together and help him rewrite the wisdoms in time. I shall see to that.", objectives = "" }
WordHunterWoW_QuestEN[29779] = { title = "The Direct Solution", description = "Alright {name}, this is the second time we've had to deal with ravaging hozen. I think it's time we take care of this problem the Huojin way. No more patience. No more mediation. We go to the source.\n\nWe're going into the hozen village to the north and we're punishing those smelly troublemakers. I've been looking forward to a chance to fight by your side again, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29780] = { title = "Do No Evil", description = "{name}, I need you to understand that the way of the Huojin is not the way of violence. When fighting is needed, we will not hesitate, but when fighting is not needed, neither do we instigate. However, the direct solution is often cutting the head off the snake, as they say.\n\nThe hozen have a leader instigating these attacks. If we remove Ruk-Ruk, we won't have to wipe the hozen out entirely.\n\nI know you are not of the Huojin, but are you with me in what must be done, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29781] = { title = "Monkey Advisory Warning", description = "The monkeys have been stealing from the village during their attacks. We should be fine without some of the extra food stores, but the idea of monkeys with fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks will come in handy?\n\nHelp me recover the stolen fireworks from their village, {name}?", objectives = "" }
WordHunterWoW_QuestEN[29782] = { title = "Stronger Than Bone", description = "This giant jade tiger pillar doesn't seem to fit in amidst the hozen buildings.\n\nWhat it does seem is very hard. Very solid.\n\nYou know just the person to bring this to.", objectives = "" }
WordHunterWoW_QuestEN[29783] = { title = "Stronger Than Stone", description = "Gather me stone blocks from the Ridge of Laughing Winds to the south.\n\nYou have seen my strength twice, yet I still spy doubt within your eyes. It will not last.", objectives = "" }
WordHunterWoW_QuestEN[29784] = { title = "Balanced Perspective", description = "Aysa has been meditating on the lake since we've arrived, all her thoughts focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, and Master Shang Xi has entrusted this task with her.\n\nYou will need to cross the ropes leading from the end of the dock to reach her. It shall test your balance, but I think you're up to the task, {name}.", objectives = "" }
WordHunterWoW_QuestEN[29785] = { title = "Dafeng, the Spirit of Air", description = "If you listen long enough, the wind will carry the answer to you.\n\nDafeng, the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He hides within the Chamber of Whispers, at the south side of the plateau.\n\nGo to him. Ji and I will join you there.", objectives = "" }
WordHunterWoW_QuestEN[29786] = { title = "Battle for the Skies", description = "Dafeng, the spirit of air, is terrified by Zhao-Ren, the Onyx Serpent. We must help him face that fear, or face it for him ourselves.\n\nWhen I told Ji of the serpent, he said he had an idea and would begin preparations outside of the chamber. Despite his rash nature, I must admit, I envy his passion and conviction.\n\nLet us go outside and confront the Onyx Serpent.", objectives = "" }
WordHunterWoW_QuestEN[29787] = { title = "Worthy of Passing", description = "The four elemental spirits will help you speak with the land and uncover its plight, but first, I have one small task to ask of you.\n\nJoin me, my pupil. Accompany this old pandaren to the western grove.", objectives = "" }
WordHunterWoW_QuestEN[29788] = { title = "Unwelcome Nature", description = "You faced forest sprites in the Dawning Valley, but the forest sprites in this grove are a different breed. Crueler and more dangerous.\n\nIf you would clear some of these sprites out, the spirits would thank you.", objectives = "" }
WordHunterWoW_QuestEN[29789] = { title = "Small, But Significant", description = "I am tired, {name}. I must rest.\n\nWe have a ritual to perform, but we require some of the charms from this grove. If you wander the grove, you should see them all over hanging from the trees. \n\nIf it does not offend one as young as you, will you permit me to sit and recover my strength while you gather these charms?", objectives = "" }
WordHunterWoW_QuestEN[29790] = { title = "Passing Wisdom", description = "This journey shall soon be yours to undertake without me. Stay for a few moments and listen to an old man's words. Let my knowledge serve as a foundation for yours, that you might be greater than I ever was.", objectives = "" }
WordHunterWoW_QuestEN[29791] = { title = "The Suffering of Shen-zin Su", description = "Now is not the time to grieve. The balloon is ready, and Shen-zin Su awaits.\n\nWe shall be the first pandaren to speak to Shen-zin Su in hundreds of years. It is a great honor.", objectives = "" }
WordHunterWoW_QuestEN[29792] = { title = "Bidden to Greatness", description = "It is up to all of you to remove the thorn from the side of Shen-zin Su. Do not let your differences come between you. Trust in each other.\n\nWithin the Pei-Wu Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark things that now lurk in the trees.", objectives = "" }
WordHunterWoW_QuestEN[29793] = { title = "Evil from the Seas", description = "I do not know what this evil is that is infesting the forest, {name}, but I know exactly how to deal with it. So do you, I think.", objectives = "" }
WordHunterWoW_QuestEN[29794] = { title = "None Left Behind", description = "Your friend has been doing everything she can to save my crew. I'm deeply appreciative.\n\nWe're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads.\n\nI still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?", objectives = "" }
WordHunterWoW_QuestEN[29795] = { title = "Stocking Stalks", description = "My men are malnourished, injured, and exhausted, but they are Horde. Every one will fight to their dying breath. As our new ally, we will stand by you when the time comes, but we would stand stronger with weapons.\n\nI have my men out gathering bamboo stalks to fashion into spears. If you can spare the effort, we could use the extra pair of capable hands.", objectives = "" }
WordHunterWoW_QuestEN[29796] = { title = "Urgent News", description = "I'm sure Aysa won't love this plan, but it's the only plan we've got. Would you mind being the bearer of bad news for me, {name}? She needs to know what we're doing so she can get everyone to safety.", objectives = "" }
WordHunterWoW_QuestEN[29797] = { title = "Medical Supplies", description = "We need supplies to tend to our wounded, but the supply crates containing them were scattered in the crash. If you can bring back any crates you find, I would be very grateful.", objectives = "" }
WordHunterWoW_QuestEN[29798] = { title = "An Ancient Evil", description = "{name}, I was looking for you!\n\nOne of the escaping sailors just spotted Aysa in the wreckage of the ship, facing some enormous beast. She might need your help - you should go to her, quickly!", objectives = "" }
WordHunterWoW_QuestEN[29799] = { title = "The Healing of Shen-zin Su", description = "This is more horrific than I imagined, but we can handle this. We need to gather the healers and close the wound. We need to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", objectives = "" }
WordHunterWoW_QuestEN[29800] = { title = "New Allies", description = "{name}, I did what had to be done. And the plan worked. Things could have been much worse had we not acted. I only wish Aysa could understand that.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", objectives = "" }
WordHunterWoW_QuestEN[29801] = { title = "Proving Your Worth", description = "Hello, {name}! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.'\n\nWe need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right man for the job.\n\nWhen the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring. Are you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[29802] = { title = "A Hidden Message", description = "Corastrasza, currently stationed at the Vermillion Redoubt in the Twilight Highlands, has intercepted a coded message of grave importance. I'll let her explain the full situation, but we need your expertise to unravel the cipher!\n\nTake your decoder ring to an ethereal thaumaturge in your capital city - he should know how to charge it. Acquire the encoded cipher from Corastrasza and use the ring to decode it for her. Hurry! Time is ticking... ", objectives = "" }
WordHunterWoW_QuestEN[29803] = { title = "Ears of the Lich King", description = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord.\n\nI don't like that one bit!\n\nGo and give him a round o' pain. You'll be doing the world a favor by doing so.", objectives = "" }
WordHunterWoW_QuestEN[29804] = { title = "Seein' Red", description = "I was just about ta curl up an' die, mon.\n\nNow, dis!\n\nSnuff an' me go way back. Oh, da memories...\n\nNo way I can face Snuff in da afterlife without avengin' his death first, mon!\n\nDese hooligans be led by one named Konk. We gotta sniff him out an' den snuff him out - for Snuff!", objectives = "" }
WordHunterWoW_QuestEN[29807] = { title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub.\n\nHe has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King.\n\nBring an end to his reign.", objectives = "" }
WordHunterWoW_QuestEN[29808] = { title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise.\n\nThe eggs have been tainted with foul magics. Our only recourse is to dispose of them.", objectives = "" }
WordHunterWoW_QuestEN[29809] = { title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", objectives = "" }
WordHunterWoW_QuestEN[29811] = { title = "The Gatewatcher's Talisman", description = "Krik'thir, guardian of the gates to Azjol-Nerub, was not a traitor.\n\nHe fell in the War of the Spider defending our home from the Scourge.\n\nAs per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.", objectives = "" }
WordHunterWoW_QuestEN[29815] = { title = "Forensic Science", description = "These creatures are everywhere - and very hostile! We'll need to deal with them before any more Alliance show up.\n\nThis one's taken quite a beating, but I've still made some determinations about its anatomy.\n\nWith the proper reagents, I'll be able to fashion a poison that should be quite effective against this species. In fact, I'll just need to modify a bit of the poison I have with me.\n\nGo and find me some viscous chlorophyll down by the water. Any semi-sentient flora should do.", objectives = "" }
WordHunterWoW_QuestEN[29820] = { title = "Into the Nexus", description = "I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days.\n\nWould you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.", objectives = "" }
WordHunterWoW_QuestEN[29821] = { title = "Missed Me By... That Much!", description = "Listen, pal.\n\nI sent out a coupla supply drones from the gunship, and they've all been lost or crashed. Almost all, that is.\n\nOne of 'em buzzed right through the camp here and crashed out by them waterfalls.\n\nHow 'bout you see what you can do about bringin' the contents of that crate back here, hmm?\n\nWe're all outta drones, but my rocket boots might yet come in handy... or footy, as the case may be.\n\nHah! I just kill me...", objectives = "" }
WordHunterWoW_QuestEN[29822] = { title = "Lay of the Land", description = "Curse these furry pests! Kill one, and two more rise in its place...\n\nNothing has changed, {name}. Orders are orders, no matter how few of us stand and regardless of the odds.\n\nI have plans to make and problems to solve.\n\nI want you to get out there and learn the lay of the land. Don't return until you have something useful to report.\n\nAnd silence that yammering fool while you're out there!\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[29823] = { title = "Scouting Report: The Friend of My Enemy", description = "We weren't only looking for Alliance, you know. We were also looking for those snooked-up, tik-flikklin' jinyu!\n\nWell, we found 'em all right...", objectives = "" }
WordHunterWoW_QuestEN[29824] = { title = "Scouting Report: Like Jinyu in a Barrel", description = "With our leader turned to jade, our hozen guide disappeared, and a prisoner of war in tow, there was only one thing that Kiryn and I could do:\n\nMarch into our enemy's territory and deliver some vengeance.\n\nWant to know how it went?", objectives = "" }
WordHunterWoW_QuestEN[29825] = { title = "Pupil No More", description = "I once called Elder Nadox my teacher.\n\nThat changed forever when I was forced to watch him mercilessly slaughter my friends and family as a servant of the damned.\n\nFind him within the depths and make him pay for his crimes, {race}.", objectives = "" }
WordHunterWoW_QuestEN[29826] = { title = "Reclaiming Ahn'Kahet", description = "Prince Taldaram and his army of Scourge use the same wards we once used to hide our empire to keep themselves safe from the native denizens of the icy depths.\n\nDeactivate the wards and slaughter the Scourge guarding them. My forces will help the natives slaughter the rest.", objectives = "" }
WordHunterWoW_QuestEN[29827] = { title = "Acid Rain", description = "Since you've been gone, more and more of these creatures are approaching our camp. They appear to be amassing for a major assault!\n\nWe're going to have to take some drastic measures if we hope to see tomorrow.\n\nHere, take my poisoned throwing stars and figure out a way to thin out their numbers.", objectives = "" }
WordHunterWoW_QuestEN[29828] = { title = "What the Scourge Dred", description = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that was immune to the plague.\n\nIf you could find King Dred and bring me one of his teeth, perhaps I could fashion it into a weapon.", objectives = "" }
WordHunterWoW_QuestEN[29829] = { title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", objectives = "" }
WordHunterWoW_QuestEN[29830] = { title = "Containment", description = "My forces are in absolute shambles, and Malygos' assailants just keep coming.\n\nI fear that the worst has yet to come.\n\nYou must engage them until their leader, Cyanigosa, comes. Only her death will stop the invasion and save Dalaran.\n\nSpeak to me again when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[29833] = { title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way to Gundrak and speak with Tol'mar. He will be able to direct you further in this cause.", objectives = "" }
WordHunterWoW_QuestEN[29834] = { title = "Gal'darah Must Pay", description = "It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nMy job be to observe only. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", objectives = "" }
WordHunterWoW_QuestEN[29835] = { title = "Gal'darah Must Pay", description = "Da mighty Akali has been slain, {race}.\n\nMy role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", objectives = "" }
WordHunterWoW_QuestEN[29836] = { title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from inside Gundrak. Perhaps you could find the time to check in on her for me?", objectives = "" }
WordHunterWoW_QuestEN[29837] = { title = "Sacred Scroll", description = "The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of.\n\nYou suspect that, like everything else these Hozu possess, this is stolen merchandise.\n\nPerhaps the original owner of the scroll is still nearby...", objectives = "" }
WordHunterWoW_QuestEN[29838] = { title = "One of a Kind", description = "At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nIf what I learned be true, den dey have a special golem - one like nuthin' created before!\n\nBring me back a piece from dat golem ta study.", objectives = "" }
WordHunterWoW_QuestEN[29839] = { title = "One of a Kind", description = "Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem.\n\nI heard dat dey have a special golem - one imbued with forbidden powah.\n\nBring me back a piece from dat golem so we can learn from our bruddas and sistahs.", objectives = "" }
WordHunterWoW_QuestEN[29840] = { title = "For Posterity", description = "Gundrak looks doomed. You know dis to be true.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be bringin' dem back to der former glory.", objectives = "" }
WordHunterWoW_QuestEN[29841] = { title = "Lay of the Land[TEMP]", description = "Grah!!\n\nFor every one of these muck-flingers we kill, another two spring from the woods to take its place. I wouldn't share this with the others, but it's clear that we won't last long here, {name}.\n\nI must stay and defend what remains of our belongings. You scout out the region and seek a solution to our primate problem.\n\nGo now. Our hope goes with you...", objectives = "" }
WordHunterWoW_QuestEN[29842] = { title = "Seeking Answers", description = "<Cho endures your stream of questions before speaking.>\n\nSo much to ponder, traveler...\n\nYou first must learn how to ask before your mind can discern the truth.\n\nI have completed my meditations for today, but my candles remain at the Cairn of Blood.\n\nGo there. Clear your mind. We will speak again when you are prepared to hear my words.", objectives = "" }
WordHunterWoW_QuestEN[29844] = { title = "For Posterity", description = "Da land of da ice trolls is a shadow of its former glory.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be givin' dis land back to a new line of frost trolls.", objectives = "" }
WordHunterWoW_QuestEN[29847] = { title = "To Catch a Thief", description = "Just beyond this cave lies Ravenholdt Manor. You need to get inside without being seen!\n\n<Mostrasz places an enchantment on you.>\n\nThere - now I'll be able to keep an eye on you and communicate as you venture into the compound. Now sneak into that manor, locate the egg, and don't get caught...", objectives = "" }
WordHunterWoW_QuestEN[29848] = { title = "The Forlorn Watcher", description = "I would gladly give my life for the Makers or their creations.\n\nHowever, since Loken's betrayal it seems all of Ulduar has turned on the world. One in particular, the Maiden of Grief, seems to reel in agony at her new orders.\n\nPlease lay her to rest and bring me one of her tears.", objectives = "" }
WordHunterWoW_QuestEN[29850] = { title = "Corrupt Constructs", description = "The iron dwarves are busy at work carving out massive stone constructs that I fear will soon be used as powerful weapons.\n\nYou must defeat their overseer, Krystallus, and the dark rune giants already walking the halls before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[29851] = { title = "Champion of the Tournament", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n{name}, fight with valor and honor. Every fighter here has gathered for the common good.\n\nTogether, we will stop Arthas!", objectives = "" }
WordHunterWoW_QuestEN[29856] = { title = "Cairn of Bone", description = "Your mind felt clear.\n\nYou thought you were focused.\n\nMaybe it was the droning of the nearby insects that put you to sleep. That must've been it!\n\nOut of the corner of your eye, you see another of the stone formations just north of here.\n\nPerhaps it's quieter at that one...", objectives = "" }
WordHunterWoW_QuestEN[29858] = { title = "Wisdom of the Ages", description = "You must learn to approach your life's trials with humility and an open mind, stranger.\n\nWisdom cannot fit through the narrow slits of the skeptic's eye.\n\nMeet me at the Cairn of Stone and I shall teach you the ancient art of meditation.\n\nOnce you are at peace, you may find that the answers you seek are not as distant as you might think them to be.", objectives = "" }
WordHunterWoW_QuestEN[29860] = { title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nVolkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.", objectives = "" }
WordHunterWoW_QuestEN[29861] = { title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nThe honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my unending gratitude.", objectives = "" }
WordHunterWoW_QuestEN[29862] = { title = "Clearing the Way", description = "Loken's forces prepare for war. What they are not ready for is to be attacked themselves.\n\nNow is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[29863] = { title = "Stormherald Eljrrin", description = "I have sent an emissary to the Halls of Lightning to take the battle to Loken.\n\nHe undoubtedly needs assistance, given the strength of Loken's armies. Lend him any aid you can so that we may finally stop the traitor.", objectives = "" }
WordHunterWoW_QuestEN[29864] = { title = "Working at the Source", description = "We are hard at work ensuring that we minimize our losses to the Scourge war machine.\n\nThe vrykul here are undermining that mission by willingly joining the Lich King's ranks.\n\nPlease, brave champion, you must defeat their spiritual leader, Svala, before she leads her people into the eternal shadow!", objectives = "" }
WordHunterWoW_QuestEN[29865] = { title = "The Silkwood Road", description = "West of here is the Silkwood Road. It has fallen into shadow as the spiders there have turned to a more evil and gluttonous path.\n\nI would face these villains myself but someone has to defend the noodle shop from... um... dangers and such.\n\nGo, hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some of my epic tales of heroism.\n\nI'll also pay you.", objectives = "" }
WordHunterWoW_QuestEN[29866] = { title = "The Threads that Stick", description = "Ah, welcome traveler. I have need of your services!\n\nSyra Goldendraft was looking for some silk. Personally I hate silk as it always gets stuck in my fur.\n\nI really want to impress her though.\n\nIf you bring me some silk from the Silkwood to the west of here I will gladly pay you for your help.", objectives = "" }
WordHunterWoW_QuestEN[29869] = { title = "One Hand Clapping", description = "You have much yet to learn, but your feet are now on the path to enlightenment.\n\nTake what I have taught you here and apply it at the lake to the west.\n\nWith patience and practice, harmony and enlightenment can be attained. Then, wisdom will flow freely into your mind.\n\nAlso, you will be far enough away that your snoring will not interfere with my own studies.\n\nFarewell, stranger.", objectives = "" }
WordHunterWoW_QuestEN[29871] = { title = "Clever Ashyo", description = "I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are clever, and I wouldn't say that he's any more clever than most of them.\n\nQuite the opposite, actually.\n\nAt least he's a capable fighter. He did well enough at Tian Monastery to be selected for our training mission.\n\nIf you want to help him look for the Hidden Master, you can find him along the Valley's northern border.", objectives = "" }
WordHunterWoW_QuestEN[29872] = { title = "Lin Tenderpaw", description = "Lin is more talented than she thinks she is. Strong of fist but weak of spirit. With more confidence, she could be better than all of us.\n\nPerhaps she will find the surety she needs on her trip into the west. She's probably on her way to Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the Valley.", objectives = "" }
WordHunterWoW_QuestEN[29873] = { title = "Ken-Ken", description = "So... Ken-Ken. The hozen.\n\nPersonally, I'm impressed he's progressed so far in his training. He's got a brain between his ears, which is more than can be said for most of his kind.\n\nHe said he was headed east, but, seeing as we're already on the far east side of the valley, I can't imagine he went too far from here. Look for him at Zhu's Watch, in Krasarang Wilds, down the path to the south. See what he's found.", objectives = "" }
WordHunterWoW_QuestEN[29874] = { title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", objectives = "" }
WordHunterWoW_QuestEN[29875] = { title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", objectives = "" }
WordHunterWoW_QuestEN[29877] = { title = "A Poor Grasp of the Basics", description = "Virmen - they no just eat our food. They trying to start farms of their own. The problem is... well, they ookin' dumb.\n\nYou no believe Muno? Last night, they break into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows planted in ground.\n\nThey was WATERING them. They was trying to GROW WHEELBARROWS.\n\nPlease, while you out there, unbury our stuff.", objectives = "" }
WordHunterWoW_QuestEN[29878] = { title = "Building a Better Hozen Trap", description = "One thing is now painfully clear. The Hozen love their 'slickies'.\n\nWhile deep in your meditative trance, scattered images and impressions came to your mind. Now fully awake, you struggle to make sense of the experience.\n\nThe beginnings of an absurd plan begin to take shape in your head. It might just be crazy enough to work...", objectives = "" }
WordHunterWoW_QuestEN[29879] = { title = "Swallowed Whole", description = "Now, back to your dilemma.\n\nI believe you can help your people build relations with our hozen, as my people have.\n\nThe trail behind me will lead you to a body of water the hozen use to gather the fish that feeds them.\n\nAround this time every year, fearsome beasts call those waters home and many hungry hozen are lost to them.\n\nIf you were to rescue some of the victims and gather some fish, perhaps you will be regarded more favorably.", objectives = "" }
WordHunterWoW_QuestEN[29880] = { title = "Catch and Release!", description = "As you place one fish in each jar, your optimism grows.\n\nThis just might work! Ideally, rescuing the Hozen from your makeshift trap will soften their stance towards you.\n\nTime to set some bait.", objectives = "" }
WordHunterWoW_QuestEN[29881] = { title = "The Perfect Color", description = "As you have seen, this grove is abundant with beautiful pink petals.  As each petal ages, the tone deepens and fades.\n\nIf you would be so kind, I am in need of a few petals that have freshly fallen.  Only the ones that have just fallen will have precisely the right color I am after.\n\nFrom it I can forge an ink that will be breathtaking.  Can you help me?", objectives = "" }
WordHunterWoW_QuestEN[29882] = { title = "Quill of Stingers", description = "To achieve perfect paint strokes, one must have the right tools. My own have fallen into disrepair, their bristles becoming as unmanageable as hozu hair.\n\nHave you seen the wasps throughout the Arboretum? Their stingers can be fashioned into quills that provide just the right level of sharpness in each line.\n\nCould you gather some for me please? ", objectives = "" }
WordHunterWoW_QuestEN[29883] = { title = "The Pearlfin Situation", description = "I've been thinking.\n\nWe are cut off from support and a long way from home.\n\nAlthough these Pearlfin jinyu mistrust our presence, they do not appear to be hostile.\n\nIf we could convince them that we are their friends, an alliance between our races could prove extremely valuable.\n\n{name}, you must go speak to the jinyu around the village.\n\nConvince their leaders that we are not to be feared, and that we only wish for peace.", objectives = "" }
WordHunterWoW_QuestEN[29885] = { title = "Road Rations", description = "We do not have time to wait around for the Admiral to recover.\n\nSully and I are planning to search for Anduin to the north, but we'll need supplies for our journey.\n\nThe lake here is teeming with wildlife, which we have received permission to hunt.\n\nGo and gather some supplies while Sully and I finalize our preparations.", objectives = "" }
WordHunterWoW_QuestEN[29886] = { title = "Zen Healing", description = "Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure.\n\nLuckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries.\n\nThe flowers growing on the surface of Glass Lake are needed to make the antidote.\n\n{name}, go quickly and bring back some blooms. Your Admiral's life depends on it.", objectives = "" }
WordHunterWoW_QuestEN[29887] = { title = "The Elder's Instruments", description = "Oh dear, oh dear... The Elder mustn't find out!\n\nI must have left the Elder's ceremonial instruments behind during the escape.\n\nBut... Moonwater Retreat is crawling with hozen by now!\n\nWhat sort of Pearlkeeper am I, to have lost them so carelessly?\n\n<The old jinyu buries his face into his hands.>\n\nStranger, could you find it in your heart to help me?", objectives = "" }
WordHunterWoW_QuestEN[29888] = { title = "Seek Out the Lorewalker", description = "I see that you and your people are desperate to find your Prince Anduin.\n\nI know someone who may be able to help you, a pandaren Lorewalker who knows this land better than anyone. I cannot guarantee what kind of reception you will receive, but he will almost certainly be as curious about you as you are of him!\n\nThe Lorewalker lives in the forest to the southwest. Tell him that the Pearlfin have sent you.", objectives = "" }
WordHunterWoW_QuestEN[29889] = { title = "Borrowed Brew", description = "A delicious smell wafts out from the bottle on the table.\n\nA little taste couldn't hurt, right?", objectives = "" }
WordHunterWoW_QuestEN[29890] = { title = "Finding Your Center", description = "The dream brew is complete! This time, when you drink it, you must embrace the visions you see from a state of inner focus.\n\nFollow me to my pagoda, and I will teach you how to achieve the inner calm that we pandaren value so much.\n\nYour troubled mind will present you with many distractions, but just remember to stay centered!   ", objectives = "" }
WordHunterWoW_QuestEN[29891] = { title = "Potency", description = "To make the Dream Brew, we will need several ingredients.\n\nFirst, to improve its strength, I will need an ingredient from a fearsome creature, the legendary Mist Horror.\n\nIt is said that this creature only appears where the fog is deepest.\n\nNorth and east of here, you will find smaller Mist Creepers roaming the swamps. Kill these creatures until the Mist Horror appears, and then bring me its heart.", objectives = "" }
WordHunterWoW_QuestEN[29892] = { title = "Body", description = "A brew's body is an important and often overlooked factor.\n\nTo create the perfect consistency, I will need pristine eyes from the Bog Crocolisks to the east.\n\nTake care. The creatures are quite vicious.", objectives = "" }
WordHunterWoW_QuestEN[29893] = { title = "Hue", description = "The most distinguishing feature of the Dream Brew is its iridescent, dream-like color.\n\nTo the east, you will find Glittering Amberflies. I will need their wings to create the final luminescent color of the brew.\n\nTake this knife and use it to collect 8 wings.", objectives = "" }
WordHunterWoW_QuestEN[29894] = { title = "Spirits of the Water", description = "Our war against the hozen rages without end, and the future of our tribe is uncertain.\n\nThis is why our waterspeaker has decided to seek wisdom from the waters.\n\nElder Lusshan is waiting. Please deliver the instruments so that they may begin.", objectives = "" }
WordHunterWoW_QuestEN[29895] = { title = "Trail of the White Pawn", description = "Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest.\n\nYou should show it to your Alliance commander.", objectives = "" }
WordHunterWoW_QuestEN[29898] = { title = "Sacred Waters", description = "I appreciate you coming all this way to save me, but Ren is gravely injured.\n\nThe old pandaren had no reason to help me, yet still he risked his life to save my own.\n\nBefore the fever set in, he mentioned that there are healing waters in the cave just down the hill.\n\nIt is dangerous, but I will do anything to help my friend. Will you help me retrieve the waters?", objectives = "" }
WordHunterWoW_QuestEN[29899] = { title = "Rest in Peace", description = "The spirits... the cavedwellers... they howl in agony... \n\nTrapped... in this world... cannot move... to the next.\n\nI... will go mad... listening... to their cries... \n\nPlease...go...put them to rest.", objectives = "" }
WordHunterWoW_QuestEN[29900] = { title = "An Ancient Legend", description = "My father has dedicated his life to studying the Vale of Eternal Blossoms.\n\nThe Vale is a mythical place, sealed after the Pandaren revolution twelve thousand years ago. We know so little about it!\n\nMy father followed a trail of clues to the cave down the hill, seeking a very old poem known as the Song of the Vale, but he is in no condition to retrieve it. It is guarded by some sort of ancestor spirit.\n\nIf you are heading that way anyway, would you mind bringing it back to him?", objectives = "" }
WordHunterWoW_QuestEN[29901] = { title = "Anduin's Decision", description = "You have done all you can for the Prince's friends.\n\nYou completed your mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 agents will be eager to have the boy safe in their custody.\n\nIt is time to return home.", objectives = "" }
WordHunterWoW_QuestEN[29903] = { title = "A Perfect Match", description = "Elder Lusshan and I agree that the best path forward will be to work together.\n\nWe will share with the Pearlfin our superior military knowledge and weaponry.\n\nIn return, they will be a powerful ally should we again encounter the Horde.\n\nTake this crate of equipment and weapons. I need you to go around the village and equip the jinyu with weapons befitting their skills.", objectives = "" }
WordHunterWoW_QuestEN[29904] = { title = "Bigger Fish to Fry", description = "I've prepared a team of bright young Pearlfin trainees who need field experience.\n\nTake them northeast, into the Bamboo Wilds, and kill any wildlife that you find.\n\nDon't bring them back until they're fit for battle.", objectives = "" }
WordHunterWoW_QuestEN[29905] = { title = "Let Them Burn", description = "Advance scouts report that the hozen at the Slingtail Pits are amassing with reinforcements from their tribes to the north.\n\nOur forces are gathered for battle on the ridge to the northwest. They are just waiting for you.\n\nNow is the time to show them what we are made of. Now is the time to destroy them indefinitely.", objectives = "" }
WordHunterWoW_QuestEN[29906] = { title = "Carp Diem", description = "Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut, is the shrewd mastermind behind their attacks.\n\nHe is organizing their movements at the great pit at the hozen camp to the northwest.\n\nStrike now and show him no mercy, {name}, for he will do the same.", objectives = "" }
WordHunterWoW_QuestEN[29907] = { title = "Chen and Li Li", description = "My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going.\n\nThat farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li?\n\n{race}? Would you like to share the road with us?", objectives = "" }
WordHunterWoW_QuestEN[29908] = { title = "A Seemingly Endless Nuisance", description = "I apologize for the state of things around here. The virmen - those rabbity creatures, down the hill - have been pushing further and further into my family's farm, and our crops - which are normally bigger, and more delicious, by the way - have been suffering because of it.\n\nI'm no soldier... but you might be! Would you mind pushing some of these virmen off of our land?", objectives = "" }
WordHunterWoW_QuestEN[29909] = { title = "Low Turnip Turnout", description = "Your help here is appreciated, {name}. I'd like to give you another job, if you're interested.\n\nMy son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day.\n\nWould you go down there and see what's going on?", objectives = "" }
WordHunterWoW_QuestEN[29910] = { title = "Rampaging Rodents", description = "I went off this morning to watch my papa fight the virmen. When I came back, the farm was full of marmots!\n\nI don't want to kill them, but we need to get rid of them. Hey, I know! We can close the holes!\n\nFill in their holes with dirt, so they can't come out in our farm anymore.", objectives = "" }
WordHunterWoW_QuestEN[29911] = { title = "Practically Perfect Produce", description = "Here, {name}. My father will be wanting this.\n\nThank you, again, for helping with the virmen.", objectives = "" }
WordHunterWoW_QuestEN[29912] = { title = "The Fabulous Miss Fanny", description = "Most of these vegetables will be sold, but I'd like to keep some for my family. Specifically, my nephew Liang needs some to feed to his pigs.\n\nUnfortunately, the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to have to ask Miss Fanny to help us out.\n\nBring some of the food we've gathered to Miss Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to Liang's ranch.", objectives = "" }
WordHunterWoW_QuestEN[29913] = { title = "The Meat They'll Eat", description = "I told you earlier, my pigs are picky eaters. They need to eat meat to grow strong, but they don't like mutton, they don't like yak, and I'm not about to feed them any pig meat.\n\nThey do, however, eat meat off of the mushan beasts, and they're also quite partial to turtle. Both creatures can be found in abundance to the west.\n\nMy skills as a hunter are admittedly quite weak. Can you help out a young rancher and his pigs?", objectives = "" }
WordHunterWoW_QuestEN[29914] = { title = "Back to the Sty", description = "I try to keep an eye on my stock, but every once in a while some of them sneak away. With all the confusion these virmen are causing, I may have let my guard down for a few moments, and some of my pigs escaped.\n\nCare to look for them? I'd start by looking down the hill, to the west.", objectives = "" }
WordHunterWoW_QuestEN[29915] = { title = "A Neighbor's Duty", description = "I'm not the only one having trouble with his stock, it seems. One of Francis' sheep has wandered over to my ranch, for the third time this week. I'm beginning to think he needs help tending to his flock.\n\nYou should check up on him, neighbor. And bring this poor little thing with you.", objectives = "" }
WordHunterWoW_QuestEN[29916] = { title = "Piercing Talons and Slavering Jaws", description = "First the hawks came. You've probably seen some of them circling up above.\n\nThe wolves came shortly after. I think they smelled my weakness.\n\nI'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts.\n\nCan... can you help, sir?", objectives = "" }
WordHunterWoW_QuestEN[29917] = { title = "Lupello", description = "I've been thinking... the wolves might stop attacking if we kill their pack leader.\n\nWe call him Lupello, and he patrols the opposite riverbank.\n\n<Francis' concentration is broken by another attack. Perhaps you should go deal with Lupello yourself.>", objectives = "" }
WordHunterWoW_QuestEN[29918] = { title = "A Lesson in Bravery", description = "<Master Shang speaks to his shepherd boy.>\n\nFrancis, you need to show bravery! You have everything it takes to make a great shepherd, except the courage to face your fears!\n\n<He looks over to you.>\n\nYou, stranger. You helped the rest of my family. Francis is like a second son to me.\n\nShow my apprentice what it means to lack fear. Use this rope to lasso and defeat one of the great white hawks above us.\n\n<Shang points to the sky, looks at Francis, and leaves.>", objectives = "" }
WordHunterWoW_QuestEN[29919] = { title = "Great Minds Drink Alike", description = "Hello again, {name}. What is this, the fourth time we've run into one another already?\n\nSay... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?", objectives = "" }
WordHunterWoW_QuestEN[29920] = { title = "Getting Permission", description = "My love, Lo, tried to get permission to marry me from the pandriarchs. Though they have passed beyond, their favor would carry a lot of weight.\n\nThing is, they are spirits, and none of the gifts or tributes we brought impress them. To win their favor they claimed that either Lo or a champion must defeat them in single combat.\n\nLo is a good man, but not a fighter.\n\nWould you be our champion?", objectives = "" }
WordHunterWoW_QuestEN[29922] = { title = "In Search of Wisdom", description = "Lorewalker Cho came by and asked for you while you were gone.\n\nHe needs your assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did not say.\n\nSpeak to Kitemaster Ut-Nam. He would be happy to send you there.", objectives = "" }
WordHunterWoW_QuestEN[29924] = { title = "Kill Kher Shan", description = "Kher Shan is one big dooker.\n\nGrooked all my sons! Ick Ick, Nab Nab, Eet Eet, Bitty Bitty, and the others I can't remember.\n\nWikket wanna help hozen? Go grook Kher Shan!\n\nThe dooker's over there.\n\n<Nibi Nibi points to the east.>", objectives = "" }
WordHunterWoW_QuestEN[29925] = { title = "All We Can Spare", description = "Alright, I called in every favor I could. Here's what we got.\n\nCho must be on to something big!\n\nLemme know when you're ready to go see him - I got a ride all prepared for ya.", objectives = "" }
WordHunterWoW_QuestEN[29926] = { title = "Calamity Jade", description = "You ever seen a shale spider, {class}? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\"\n\nA few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys.\n\nYou get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.", objectives = "" }
WordHunterWoW_QuestEN[29927] = { title = "Mann's Man", description = "<For once, the foreman lowers her voice.>\n\nLook, this ain't easy... I got another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice as stupid. Says the boys need him around for \"moral support.\"\n\n<Mann sneers.>\n\nWhat about my moral support?! What am I gonna do if that idiot dies?!\n\nPlease... keep an eye out for him. Tell him to come home.\n\n<Her eyes soften before she turns away.>", objectives = "" }
WordHunterWoW_QuestEN[29928] = { title = "I Have No Jade And I Must Scream", description = "Our whole jade supply line has fallen apart. The mines are a death trap, morale is historically low, and - as if that weren't bad enough - the mason's quarter has been overrun by wood sprites!\n\nNow even the plants are out to ruin me!\n\nYou need jade so badly, you can follow the road southwest to the mason's quarter and get it from those glorified chopsticks yourself.", objectives = "" }
WordHunterWoW_QuestEN[29929] = { title = "Trapped!", description = "<Hao struggles against the rubble with all his might.>\n\nHNNNGHHH!!\n\nLet me guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a little--HNNGGHHH!!--cave-in to keep ol' Hao down.\n\nSome o' the boys, on the other hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine.\n\nReally.", objectives = "" }
WordHunterWoW_QuestEN[29930] = { title = "What's Mined Is Yours", description = "Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time.\n\nI should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her.\n\nNow, I ain't never met no {race} t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.", objectives = "" }
WordHunterWoW_QuestEN[29931] = { title = "The Serpent's Heart", description = "You've done great here, kid. Thanks to you, we have quite a bit of extra jade, and I know just the someone who could use it.\n\nMy friend Foreman Raike is running the great statue project at the Serpent's Heart.\n\nBring a shipment of extra jade to him, and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.", objectives = "" }
WordHunterWoW_QuestEN[29932] = { title = "The Temple of the Jade Serpent", description = "You've done us a huge favor here, traveler.\n\nNow that we have enough jade to complete the statue, we should send word of our progress to Yu'Lon, the Jade Serpent.\n\nWhen you arrive, speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent.\n\nIf you wish to speed your journey, speak to Kitemaster Shoku. I'm sure he can spare an extra kite for you.", objectives = "" }
WordHunterWoW_QuestEN[29933] = { title = "The Bees' Knees", description = "You really hozen friend, wikket? Let's see, hmm?\n\nHozen at Grookin' Hill all outta slicky bait. Tigerflies' legs stay twitchy in water - make best bait!\n\nBo Bo sick from stings. Wikket get bait and take to Grookin.", objectives = "" }
WordHunterWoW_QuestEN[29934] = { title = "To Ravenholdt", description = "If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure.\n\nThat's you, {name}.\n\nMostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[29935] = { title = "Orders are Orders", description = "Hmm, maybe wikket not so bad after all!\n\nOther baldskins not nice to hozen.\n\nHozen take this from bad wikkets!\n\nAll wikket loot goes to Kah Kah - Chief's orders!\n\nHere, wikket. You take it. Kah Kah will want to meet new hozen friend.\n\nHis camp south at Grookin Hill.", objectives = "" }
WordHunterWoW_QuestEN[29936] = { title = "Instant Messaging", description = "Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen.\n\nDook Ookem wanted to be chief, but good wikket grook him good - big gift to Kah Kah.\n\nHozen has gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.", objectives = "" }
WordHunterWoW_QuestEN[29937] = { title = "Furious Fowl", description = "So these guys like fish, huh? Well how about we finish what you started and make them LOVE us?\n\nI've still got some explosive powder from the wreck, just need something to attract the fish.\n\nGuts is sure to do the trick - never fails. I saw some birds flyin' around south of town.\n\nWell? Whatcha waitin' for?", objectives = "" }
WordHunterWoW_QuestEN[29938] = { title = "Friends and Foes", description = "These ookin' Jinyu grookin Kah Kah's nephews!\n\nWikket once kill many hozen. Now wikket kill many jinyu.", objectives = "" }
WordHunterWoW_QuestEN[29939] = { title = "Boom Bait", description = "There. I've plastered your bird guts over my explosives.\n\nI call 'em Gut Bombs, patent pending.\n\nSince you made friends with these fellas, how about you do the honors?\n\nJust light the fuse and throw 'em down by the shoreline!", objectives = "" }
WordHunterWoW_QuestEN[29940] = { title = "Taking a Crop", description = "Alright, fine. I DON'T have everything under control here. I spent all morning fighting off virmen. I managed to clear them off of my property, but they got away with some of my crops.\n\nThey took them down to the river, to the south. I have no idea what they're doing with them, but it's probably not eating them.\n\nIf my father wants his delivery now, I'm going to need some help getting those crops back. Could you help me out?", objectives = "" }
WordHunterWoW_QuestEN[29941] = { title = "Beyond the Horizon", description = "I recognize all you've managed to do here, {class}. My report to the Warchief will include an account of your deeds.\n\nBut there's no time to rest!\n\nThis land must be charted and prepared for Horde settlement. I've already selected an away team to do just that.\n\nFind them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide.\n\nYou'll be staying here with me. We have preparations to make.", objectives = "" }
WordHunterWoW_QuestEN[29942] = { title = "Silly Wikket, Slickies are for Hozen", description = "You think hozen crazy, wikket? Wait til you see hozen with no slickies!\n\nNot enough slickies for hozen and wikkets.\n\nSnappers! Hozen hate them ookin' snappers. Wikkets can eat all the snappers!\n\n<Eekle Eekle points to the south.>", objectives = "" }
WordHunterWoW_QuestEN[29943] = { title = "Guerrillas in our Midst", description = "Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, {name}.\n\nBut there's another side of this coin. We'd be naive to think the child was left alone.\n\nAny Alliance scum within sight of this land must be searching desperately for their precious princeling.\n\nYou and I are going to scour the area and root out his would-be rescuers.", objectives = "" }
WordHunterWoW_QuestEN[29944] = { title = "Leaders Among Breeders", description = "Before any kegs are tapped, we have work to do. These virmen are no different than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits they resemble.\n\nSure, we could kill every last virmen we find, but what's the point in needless bloodshed? Let's just take out their alphas, and they'll slow down with their... reproduction.", objectives = "" }
WordHunterWoW_QuestEN[29945] = { title = "Yellow and Red Make Orange", description = "Uncle Chen says we're going to help this guy out with his virmen problem. Fine by me! I LOVE messing with virmen.\n\nHere's the plan: we're going to paint some turnips orange, and then we'll try to convince the virmen that they're carrots.\n\nThis can only end in comedy.\n\nI'll gather turnips. You find something that we can use to make edible orange paint.", objectives = "" }
WordHunterWoW_QuestEN[29946] = { title = "The Warren-Mother", description = "We've dealt with the alpha males. Now, the alpha female.\n\nVirmen aren't terribly selective when it comes to breeding, but most broods will still have a dominant mother figure. She's usually bigger, meaner, and tougher than anyone else in the brood.\n\nYou know, I wouldn't mind testing my skills against a warren-mother. Mind if I fight alongside you?", objectives = "" }
WordHunterWoW_QuestEN[29947] = { title = "Crouching Carrot, Hidden Turnip", description = "Uncle Chen's still got his eye on me, which means I won't be wandering off any time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into the Twisted Warren and deliver them for me.\n\nIt should be pretty simple. Just toss the vegetables in front of virmen, then watch their reaction when they find out it's really a turnip!", objectives = "" }
WordHunterWoW_QuestEN[29948] = { title = "Thieves to the Core", description = "You and that Chen fellow are good people, helpin' out with the virmen like you are. I don't like to ask for favors, but I ain't gonna turn 'em away, either.\n\nWhile you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last night.\n\nProbably usin' em for pillows, knowin' how they are.", objectives = "" }
WordHunterWoW_QuestEN[29949] = { title = "Legacy", description = "I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.", objectives = "" }
WordHunterWoW_QuestEN[29950] = { title = "Li Li's Day Off", description = "Uncle Chen asked me not to get into any fights while he was away... but that doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without stopping every forty-seven steps for another rest!\n\nYou want to come with me? I'll bet there's all kinds of cool places we can visit, not too far away from here.", objectives = "" }
WordHunterWoW_QuestEN[29951] = { title = "Muddy Water", description = "While you're just hangin' around, I might as well get you involved in my whole beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff together and wait.\n\nYou probably heard - I like to use the muddy water from the riverbanks, to the south. Would you mind fillin' up this flask with that water and bringin' it back? I'll start gettin' the hops and barley all ready.", objectives = "" }
WordHunterWoW_QuestEN[29952] = { title = "Broken Dreams", description = "Yes, I found the Stormstout Brewery... although I didn't exactly get the warm reception I expected.\n\n<Chen pours himself a mug of ale.>\n\nDo you want to hear the story?", objectives = "" }
WordHunterWoW_QuestEN[29966] = { title = "Burning Down the House", description = "Look, {name}!\n\nThese Alliance dogs built a camp up on the ridge.\n\nHere, take my grog. Let's make a fire they can see from Stormwind!\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[29967] = { title = "Boom Goes the Doonamite!", description = "It's an emergency!\n\nLooks like you stirred up a hornet's nest killin' all them fish-folk.\n\nThey're conductin' a full-on counterattack on Grookin Hill!\n\nI was hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work right away!\n\nMeet me on the east side of the fort, and bring yer throwin' arm!", objectives = "" }
WordHunterWoW_QuestEN[29968] = { title = "Green-ish Energy", description = "One word: Methane!\n\nWe're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world.\n\nThat, and I ran out of blasting powder...\n\nSo, I need your help, {name}.\n\nNo, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself.\n\nYou gather up some wood for an outhouse - I'm thinking long-term here!", objectives = "" }
WordHunterWoW_QuestEN[29971] = { title = "The Scouts Return", description = "Hey, while you were out our scouts came back. And get this, they found some Alliance kid.\n\nYou should probably go debrief them.", objectives = "" }
WordHunterWoW_QuestEN[29981] = { title = "Stemming the Swarm", description = "I'm not from here. I've never even BEEN here before today. But even I can tell you that something's wrong.\n\nThat wall over there was built to keep mantid off of pandaren lands.  Now, the mantid are sending their winged scouts over the top, as if the wall wasn't even there!\n\nThe only reason those spindly scouts aren't dying is because they're attacking farmers, not soldiers. They wouldn't stand a chance against someone like you.", objectives = "" }
WordHunterWoW_QuestEN[29982] = { title = "Evacuation Orders", description = "A few farmers remain in the fields... some perilously close to the crumbling wall. I don't want any farmers pretending to be heroes. We will take care of this mantid swarm, and then they can return to their homes.\n\nMy Shado-Pan are too busy defending this town to organize evacuations. You want to prove yourself useful? Get those farmers out of harm's way.", objectives = "" }
WordHunterWoW_QuestEN[29983] = { title = "The Hidden Master", description = "We should be able to handle the defense of Stoneplow from here on out.\n\n<The Watch Commander motions towards Lin Tenderpaw.>\n\nLin here is searching for someone she calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue for you.\n\nGo north.", objectives = "" }
WordHunterWoW_QuestEN[29984] = { title = "Unyielding Fists: Trial of Bamboo", description = "We will start with a test: The Trial of Bamboo.\n\nYour friend Lin failed this test.\n\nFollow me, and listen carefully to my instructions.", objectives = "" }
WordHunterWoW_QuestEN[29985] = { title = "They Will Be Mist", description = "The mist in this forest is a constant nuisance - one which I'm glad to hand off to trainees like you. Strange creatures lurk in the mist between these trees, and they must constantly be pushed back.\n\nConsider this part of your training.", objectives = "" }
WordHunterWoW_QuestEN[29986] = { title = "Fog Wards", description = "Trainee.\n\nSeveral wards surround us, hidden in the woods near my home. They are quite effective at dispersing the mist, but they require constant upkeep.\n\nYou will find one to the north, one to the west, and one to the south. Find these wards and light them.", objectives = "" }
WordHunterWoW_QuestEN[29987] = { title = "Unyielding Fists: Trial of Wood", description = "You have progressed in your training, I think. Come with me, and we will attempt the Trial of Wood.", objectives = "" }
WordHunterWoW_QuestEN[29988] = { title = "A Taste For Eggs", description = "I can sense your anxiety, but you are not ready yet. Your training must continue before you perform the final test. As for your task... I need you to fetch me some eggs.\n\nYes, eggs. The marshland atop the hills to the east is home to a number of birds, all of which are generally peaceful in nature. You should have no trouble gathering enough eggs to last me several weeks.", objectives = "" }
WordHunterWoW_QuestEN[29989] = { title = "Unyielding Fists: Trial of Stone", description = "You have accomplished much in the short time you have been here, {name}. I would not normally offer this test so soon... but I feel that you're ready.\n\nIt is time you attempted the Trial of Stone.", objectives = "" }
WordHunterWoW_QuestEN[29990] = { title = "Training and Discipline", description = "I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, {name}. I'm not going to let it slip away.\n\nStill, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me.\n\nOh, and if you run into the others, maybe you should tell them where the Hidden Master is...", objectives = "" }
WordHunterWoW_QuestEN[29992] = { title = "Tenderpaw By Name, Tender Paw By Reputation", description = "I'd like to go tell Xiao, Kang, and the others that I've found the hidden master, but now he won't let me leave! He says I have to pass that test of bamboo first.\n\n<Lin whispers:> How'd you do that, by the way?\n\nIt looks like, for the time being, I'm stuck here practicing my punches against this rock. And my knuckles are about to cave in.\n\nIf you could gather some jademoon leaves, I could prepare an ointment and at least numb some of this pain.", objectives = "" }
WordHunterWoW_QuestEN[29993] = { title = "Find the Boy", description = "Have you seen my son, Lo? He was here a moment ago and I told him we were leaving today.\n\nI'm sure he's off trying to woo that young Syra Goldendraft. That is the very reason we need to leave!\n\nNo son of mine is going to run off with a Goldendraft!\n\nI'm going to search around here for them.\n\nI do keep catching those two sneaking off to the Arboretum. Any chance you could head out there and look for them?", objectives = "" }
WordHunterWoW_QuestEN[29995] = { title = "Shrine of the Dawn", description = "The \"children\" you seek are not actually children but grown pandaren, despite what their elders might claim. Their love will not be held in check by the feuds of their families.\n\nYou will find both Syra and Lo at the Shrine of the Dawn, ever seeking an answer to their dilemma amongst the pandriarchs of old.", objectives = "" }
WordHunterWoW_QuestEN[29997] = { title = "The Scryer's Dilemma", description = "Since you were so helpful at the mines, would you be willing to help us with a small problem here at the temple?\n\nWise Mari has been complaining recently of a disturbance in his temple.\n\nThe water elementals have gotten quite playful recently, and made off with his ceremonial staff.\n\nIf you could help him, I would be most grateful. I may even put in a word with the Jade Serpent for you.\n\nJust follow the path to the north.", objectives = "" }
WordHunterWoW_QuestEN[29998] = { title = "The Librarian's Quandary", description = "Lorewalker Stonestep is in charge of the entire temple library. Lately, something has been troubling him and his work.\n\nWith thousands of ancient tomes to be transcribed, I can't afford to have him distracted.\n\nWould you follow the path south to the library and see what ails him?", objectives = "" }
WordHunterWoW_QuestEN[29999] = { title = "The Rider's Bind", description = "Have you seen the young serpents in the training yard?\n\nThe littles ones tend to be mischievous, and some of them ran off to play before the training session.\n\nThe Mistress will get angry if she discovers they're missing.\n\nWould you go find them and bring them back to me? I don't want them to get into trouble.\n\nThey like to play out in the open, so look for them in courtyards and around the spires.", objectives = "" }
WordHunterWoW_QuestEN[30000] = { title = "The Jade Serpent", description = "You came to deliver a message to the Jade Serpent, right?\n\n<The little girl tilts her head up at you inquisitively.>\n\nI guess it's time you met her.", objectives = "" }
WordHunterWoW_QuestEN[30001] = { title = "Moth-Ridden", description = "Moths have infested the library. Moths!\n\nAny librarian worth his letters knows that moths are the most dangerous threat to paper, second only to bookworms.\n\nAs it turns out, my assistants are a useless bunch of insect-fearing cowards.\n\nPlease, you MUST help me get rid of the moths immediately! The works of a thousand pandaren storytellers depend on you!", objectives = "" }
WordHunterWoW_QuestEN[30002] = { title = "Pages of History", description = "The worst possible thing has happened, {race}.\n\nWe. Have. Bookworms.\n\nThis is a critical situation. All bookworms in the library must be eradicated at once to prevent their spread.\n\nWe must squash this problem, literally! Please examine the infested books in the library and squash any bookworms that you find.", objectives = "" }
WordHunterWoW_QuestEN[30003] = { title = "A Book By Its Cover", description = "", objectives = "" }
WordHunterWoW_QuestEN[30004] = { title = "Everything In Its Place", description = "You have helped us more than you can ever imagine, {name}.\n\nI do not know what I would do if our precious scrolls were ever to be lost.\n\nPlease return to the Elder Sage Rain-Zhu and tell him that the library is in order.", objectives = "" }
WordHunterWoW_QuestEN[30005] = { title = "Lighting Up the Sky", description = "Do you like fireworks, sir?\n\nI love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty!\n\nI think there are still some old launchers lying around the temple.\n\nWould you go set off some big fireworks for me? It would make me so happy!", objectives = "" }
WordHunterWoW_QuestEN[30006] = { title = "The Darkness Around Us", description = "Despite our best efforts, the sha broke the seals around the main temple.\n\nIf we cannot hold them back here, their darkness will spread to the rest of the Jade Forest.\n\nWe need your help immediately. Kill any sha creatures that you see. They should not be difficult to find.", objectives = "" }
WordHunterWoW_QuestEN[30011] = { title = "A New Vision", description = "Please tell the Elder Sage Rain-Zhu that I will begin my work at once.", objectives = "" }
WordHunterWoW_QuestEN[30015] = { title = "Dawn's Blossom", description = "Blood and Thunder! My axe hungers!\n\nWe won't return to Orgrimmar until every last Alliance is purged from this land.\n\nI will train these natives myself, if I have to. One way or another, this land will be made ready for Horde settlement.\n\nIn the meantime, their chief gave me this to pass on to you - a map and a message in some fancy script.\n\nDo what you must, but be quick about it.\n\nWar is brewing...", objectives = "" }
WordHunterWoW_QuestEN[30027] = { title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a staff from one of the weapon racks below, bring it to me, and show me that you know how to equip it properly.", objectives = "" }
WordHunterWoW_QuestEN[30028] = { title = "Grain Recovery", description = "Since you are heading south, can you try to recover some of the grain that these thieves made off with?\n\nWe saw birds and sprites running off with entire bags of our best bulk stock into the fields east and south of here.", objectives = "" }
WordHunterWoW_QuestEN[30029] = { title = "Wee Little Shenanigans", description = "So... we bought some cheap grains in bulk. It turned out the grain was infested with sprites.\n\nI HATE sprites. With their wee beady eyes and constant smiling.\n\nI would like to resolve this quietly. Can I buy your services to discreetly eliminate some of these grain thieves?", objectives = "" }
WordHunterWoW_QuestEN[30030] = { title = "Out of Sprite", description = "Just to be clear, what happened was an accident. What I did, I did for INDUSTRY!\n\nThere was no way I could have known that a sprite invasion would happen at any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" formula.\n\nNow not only do they have a big sprite leading them, but he's one angry beast.\n\nIf I pay you, will you take him out?", objectives = "" }
WordHunterWoW_QuestEN[30031] = { title = "Taste Test", description = "As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life.\n\nYou should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.", objectives = "" }
WordHunterWoW_QuestEN[30032] = { title = "The Quest for Better Barley", description = "Looking for sweet grain? My father once mentioned a malted cave barley that sounds about right.\n\nIf you are willing to brave the peril, there is an ancient cave at the base of the Winds' Edge south of here.\n\nThere is even an old lift my father made when he would travel into the jungle.\n\nIn the cave is a bush as old as my family. From that bush you can pluck a grain so sweet it will humble your senses.\n\nJust watch out for its guardians.", objectives = "" }
WordHunterWoW_QuestEN[30033] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a spellblade and a hand fan from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", objectives = "" }
WordHunterWoW_QuestEN[30034] = { title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a crossbow from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", objectives = "" }
WordHunterWoW_QuestEN[30035] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a mace and a book of prayers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "" }
WordHunterWoW_QuestEN[30036] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a pair of daggers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "" }
WordHunterWoW_QuestEN[30037] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "" }
WordHunterWoW_QuestEN[30038] = { title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", objectives = "" }
WordHunterWoW_QuestEN[30039] = { title = "Much to Learn", description = "Freshly arrived for your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30040] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30041] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30042] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30043] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30044] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30045] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "" }
WordHunterWoW_QuestEN[30046] = { title = "Chen's Resolution", description = "You know what? I don't have to take this.\n\nI'll show that Uncle Gao what it means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients I've never even used before.\n\nI'm Chen Stormstout, and I'm the best brewer alive.", objectives = "" }
WordHunterWoW_QuestEN[30047] = { title = "The Chen Taste Test", description = "Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that.\n\nLet's get this grain back to him at Halfhill.", objectives = "" }
WordHunterWoW_QuestEN[30048] = { title = "Li Li and the Grain", description = "I'll let you in on my brewing plan, {name}: I'm planning on making an Emperor Stout. Done right, it should be dark, roasty, and high in alcohol.\n\n<A frown appears on Chen's face.>\n\nI just realized... I never told my plans to Li Li. She'll have no idea what type of grain to bring back!\n\nCould you speak with her? I need her to bring back the sweetest malted grains she can find.", objectives = "" }
WordHunterWoW_QuestEN[30049] = { title = "Doesn't Hold Water", description = "Would you mind checking in on Mudmug? He may need some assistance bringing that water back.\n\nI'm sure he'll appreciate the help of a big, strong {class} like yourself to help him shoulder the load.", objectives = "" }
WordHunterWoW_QuestEN[30050] = { title = "Gardener Fran and the Watering Can", description = "You want me to just GIVE you some hops? Pfshh! This is the third time today some little {race} like you has come up to me asking for food!\n\nYou want food? Then you'd better work!\n\n<She shoves a watering can into your hand.>\n\nNow go water my plants!", objectives = "" }
WordHunterWoW_QuestEN[30051] = { title = "The Great Water Hunt", description = "Look at it, {name}: the Gilded Fan. I heared lots of good things about the water they got here. Lots of bad things, too.\n\nNo sayin' what kind of water Chen's gonna be needin', so what say we make him a little sampler platter?\n\nCome on, let's get movin'. We'll go scoop up some water together.", objectives = "" }
WordHunterWoW_QuestEN[30052] = { title = "Weed War", description = "You want some hops? I've got plenty in the shed out back. I'll gladly share some with you... if you'll help me weed my field.\n\nNow \"hop\" to it! Get it?", objectives = "" }
WordHunterWoW_QuestEN[30053] = { title = "Hop Hunting", description = "With Li Li fetching grain, and Mudmug handling our water, all we need is hops, and some good wood barrels. I'll handle the barrels... but I need you to gather the hops.\n\nI don't know much about the hops from this land, but I'm sure the nearby farmers have something worth brewing with. Go see what you can rustle up.", objectives = "" }
WordHunterWoW_QuestEN[30054] = { title = "Enough is Ookin' Enough", description = "Virmen, they bite too much.\n\nThey bite Mung-Mung's carrot. They bite Mung-Mung's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung's tail and foot.\n\nEnough is ookin' enough.\n\nYou fight way better than Mung-Mung does. Bring back their bitey teeth. Then we see who does the biting.", objectives = "" }
WordHunterWoW_QuestEN[30055] = { title = "Stormstout's Hops", description = "All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.", objectives = "" }
WordHunterWoW_QuestEN[30056] = { title = "The Farmer's Daughter", description = "Brave {class}, you could not have arrived at a better time. My daughter is missing!\n\nI've got a suspicion that the virmen took her down into that stinking little warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from fighting them off all morning.\n\nCould you look for her?", objectives = "" }
WordHunterWoW_QuestEN[30057] = { title = "Seeing Orange", description = "Those virmen... they make me do horrible, horrible, silly things. All involving carrots. I couldn't tell you how many carrots they threw at me.\n\nLet's not waste any more time. Get me out of here!", objectives = "" }
WordHunterWoW_QuestEN[30058] = { title = "Mothallus!", description = "The esteemed Journeyman Chu would appear to have created a monster. It is silken death with wings.\n\nMothallus.\n\nYou have already faced its brood. Now we ask that you help us face the creature itself.\n\nPlease, {class}, venture into the pit and rifle the bait. This will bring the beast to you.\n\nOur mothfighters will assist you as you need, though silk tends to stick to them more than most so you may need to help them, should they become overwhelmed.", objectives = "" }
WordHunterWoW_QuestEN[30059] = { title = "The Moth Rebellion", description = "Oh... oh good! A {class}! Could you help me?\n\nI created a strain of vile monsters during my experiments to improve silk output.\n\nThe result was a full-scale moth rebellion. Can you use your {class}iness and destroy some of these mutants?", objectives = "" }
WordHunterWoW_QuestEN[30063] = { title = "Behind the Masks", description = "The sha may seem unstoppable, but this is not true.\n\nTheir masks seem to be the source of their power. When a sha and its mask are separated, the creature's essence is banished back to its own realm.\n\nBring me intact masks, for I wish to study them further. Do be careful. I'm sure the sha will not part with them easily.", objectives = "" }
WordHunterWoW_QuestEN[30064] = { title = "Saving the Sutras", description = "My adepts had to abandon their studies when the sha invasion began.\n\nUnfortunately, they left their books scattered around the temple grounds. These priceless works of knowledge must be saved!\n\nThe sutras can be found near the Training Pit and the Adept's Ring to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[30065] = { title = "Arrows of Fortune", description = "Our war supplies grow low, but especially needed are additional arrows.\n\nOur serpent riders are skilled marksmen, but they can do little without ammunition.\n\nWe need someone to brave the battlefields and retrieve any undamaged arrows to refill our stores.\n\nEvery arrow you retrieve will be used wisely.", objectives = "" }
WordHunterWoW_QuestEN[30066] = { title = "Hidden Power", description = "Our temple defenders have battled relentlessly for hours. No doubt they grow tired.\n\nI will give you mantras to deliver to our fighters.\n\nDo not be fooled by these pieces of paper. These ancient scriptures hold words of untold power.", objectives = "" }
WordHunterWoW_QuestEN[30067] = { title = "The Shadow of Doubt", description = "A terrible manifestation of the sha has appeared to the south.\n\nIt is trying to destroy an ancient relic, the Bell of a Thousand Whispers.\n\nThis bell has never been rung in the temple's history, for it is rumored to be an ancient instrument of power.\n\nPlease go and defeat this demon where it stands! We must save this relic!", objectives = "" }
WordHunterWoW_QuestEN[30068] = { title = "Flames of the Void", description = "Do you see the violent black and white flames erupting all around the temple?\n\nThe greater our doubt, the stronger they rage. Unchecked, they will devour the entire temple.\n\nWe have but one hope.\n\nTake flight on one of our war serpents. Fly it near the pure springs of water, and then douse the fires with water from the pools.", objectives = "" }
WordHunterWoW_QuestEN[30069] = { title = "No Plan Survives Contact with the Enemy", description = "Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at least.\n\nRell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin and Taylor, but it's getting hot in there and he needs support.\n\nFight yer way through these dogs and find Rell!", objectives = "" }
WordHunterWoW_QuestEN[30070] = { title = "The Fall of Ga'trul", description = "Alright lad. We've taken enough jabs at this warlock army... now it's time to cut off the head.\n\nGa'trul's back there, in that big ol' temple ruin. Give him a good what-for, and the Horde will have lost its last stake here in Pandaria.", objectives = "" }
WordHunterWoW_QuestEN[30072] = { title = "Where Silk Comes From", description = "Would you like to be a Silkmaster for a day?\n\nThe first thing you'll need are fresh mulberry leaves. You can find them in our grove of mulberry bushes to the northwest.\n\nNext you will need to feed them to a hungry silkworm in our feeding pit to the west.\n\nAnd finally you should get some raw silk from our processing hut on the south side of our farm.\n\nHave fun!", objectives = "" }
WordHunterWoW_QuestEN[30073] = { title = "The Emperor", description = "We have everything we need. It's time to start brewing.\n\nPay attention, {name}... you might learn a thing or two.", objectives = "" }
WordHunterWoW_QuestEN[30074] = { title = "Knocking on the Door", description = "Now, onward to the Stormstout Brewery! It's high time that I was reunited with the rest of the Stormstouts... and what better way to reunite than over a few mugs of ale?\n\nYou know where the brewery is, right? Just follow this road to the west. You can't miss it. Of course, you're free to share the road with us - we'll be leaving any moment now.", objectives = "" }
WordHunterWoW_QuestEN[30075] = { title = "Clear the Way", description = "Are you seeing this? Virmen, hozen, and water sprites... all pouring out of the brewery doors and windows! What the heck is going on in there!?\n\nThere is another entrance, on the eastern side of the brewery. I'm going to run over there and try to figure out what's going on. In the meantime, see if you can't get rid of these creatures. There's nothing worse than a drunken hozen.", objectives = "" }
WordHunterWoW_QuestEN[30076] = { title = "The Fanciest Water", description = "I've heard lots of cockamamie rumors about this here brewery. I thought they were all false... until I saw that giant hozen.\n\nSo, it got me thinkin', what if the other rumors are true? I heard this one rumor just the other day about some water sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies are actually MADE OF WATER.\n\nI reckon a man could make some mighty fine beer with some fancy water like that. If you find any, could you bring me some?", objectives = "" }
WordHunterWoW_QuestEN[30077] = { title = "Barrels, Man", description = "I can't believe that giant hozen! He's just throwing barrels everywhere!\n\nBarrels, man!\n\nIt looks like he managed to get pretty much all the pandaren that were working out in front of the brewery. If I were you, I'd help some of them break out. Put some of those ridiculous muscles to use.\n\nWe're headed over to the brewery's rear entrance, to the east. Meet you there!", objectives = "" }
WordHunterWoW_QuestEN[30078] = { title = "Cleaning House", description = "That's it, {name}. I've had enough of this.\n\nIf somebody doesn't do SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much family history - and beer - in there to risk wasting.\n\nSo... we're going to break in through the back door. You, Li Li, Mudmug, and me.\n\nIt's gonna be a brawl in there.\n\nLet me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[30079] = { title = "What's Eating Zhu's Watch?", description = "Pandaren always welcome travelers with open arms - and open kegs! But this town full of jerks!\n\nEveryone so busy sulking, they won't talk to Ken-Ken at all!\n\nCan you find someone in town who will talk to us? Maybe normal pandaren just hiding in the houses?", objectives = "" }
WordHunterWoW_QuestEN[30080] = { title = "Finding Yi-Mo", description = "My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair hit the town, he took it harder than most. He sat around for days refusing to eat, just staring off into the horizon.\n\nNow he's wandered off toward the cliffs northeast of here, where the thunderbirds nest and hunt.\n\nPlease, {class}, will you look for him?", objectives = "" }
WordHunterWoW_QuestEN[30081] = { title = "Materia Medica", description = "Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old hozen remedy that do the trick.\n\nNeed to mix honey, fish oil, and salt. Ken-Ken saw lots of beehives in the trees around town, and there must be fish left in the dry ponds.\n\nThat just leave salt... Mei might know where we can find some.", objectives = "" }
WordHunterWoW_QuestEN[30082] = { title = "Cheer Up, Yi-Mo", description = "Ever since this storm began, I've just been... tired.\n\nNot physically... no. It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels when a mate leaves them for someone with a rounder belly, but I've never had a mate so how would I know?\n\nHow can I claim to know anything? I'm worthless to everyone but these thunderbirds. At least they'll have a good meal out of me.\n\n<Yi-Mo sighs deeply and continues staring off into the sky. It doesn't look like he's going anywhere.>", objectives = "" }
WordHunterWoW_QuestEN[30083] = { title = "Securing the Province", description = "With our grip on the province loosening, saurok from the wilds have already moved in to the cave just north of town.\n\nMost of our hunters are face-down in their own tears, so the saurok just walk in here like they own the place and grab whatever they want!\n\nI want to send a message that Zhu's Watch is not to be crossed.\n\nWill you be my messenger?", objectives = "" }
WordHunterWoW_QuestEN[30084] = { title = "Borderlands", description = "Bonfires are surprisingly effective at discouraging beasts from wandering out of the wilds. We have three along the border to the southwest which we normally keep lit at all times.\n\nNobody's been there for days, though, and the fires must be out by now. It's only a matter of time before the wilds creep back in and overtake the land we have kept safe for centuries.\n\nPlease, re-ignite the bonfires. They are critical in keeping the province safe, and they are memorials to the founders of our way of life.", objectives = "" }
WordHunterWoW_QuestEN[30085] = { title = "Into the Brewery", description = "We need to find out what's going on inside that brewery, {name}!\n\nWe may have cleared out some of the bigger pests, but I'm certain there's plenty more where they came from. Gather up a few of your friends, and meet me inside!", objectives = "" }
WordHunterWoW_QuestEN[30086] = { title = "The Search for the Hidden Master", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs.\n\nI'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I are trying to decide something. We can talk again afterwards.", objectives = "" }
WordHunterWoW_QuestEN[30088] = { title = "Why So Serious?", description = "Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still sad...\n\nWe try another old hozen remedy - this time, we go back even further than gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at parties.\n\nKen-Ken got woodworking to do - you bring him teeth! Not yours; big ones, like a panther would have!\n\nOh, and some paint! Mei might know where to find.", objectives = "" }
WordHunterWoW_QuestEN[30089] = { title = "Apply Directly to the Forehead", description = "Well... THAT was unexpected!\n\nCome to think of it, now Ken-Ken remember why hozen use mask in the first place...\n\nA legend about the Monkey King says he used a mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then they buried mask--with all his sadness--in the ground.\n\nWe should use the mask on more pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT.\n\nLet's do this, {name}!", objectives = "" }
WordHunterWoW_QuestEN[30090] = { title = "Zhu's Despair", description = "Hmm... Is that Yi-Mo kid over there?\n\n<Ken-Ken squints against the increasing torrents of rain.>\n\nIt is! He's at the well, and he's not lookin' so good.\n\nKen-Ken got a bad feeling about this...", objectives = "" }
WordHunterWoW_QuestEN[30091] = { title = "Tears of Pandaria", description = "All of this started with our ponds. In a single day, all of the water retreated down into the earth. When there was no more water in the ponds, it began to fall from the sky.\n\nDespite endless torrents of rain, the ponds do not fill. It's as if the land itself thirsts and cannot be quenched.\n\nNow the ponds birth horrific manifestations of despair. Elementals made of water from the sky and salt from the earth; the tears of Pandaria.", objectives = "" }
WordHunterWoW_QuestEN[30092] = { title = "Our Man in Gilneas", description = "If you wish to join my cause and slaughter the black dragons in hiding, prove yourself by taking down Hiram Creed. He's amassing an army in Gilneas.\n\nWe haven't been able to slip past his defenders, but we've got a man on the scene keeping an eye on him. Zazzo Twinklefingers, a very crafty arcane mage, is waiting for us to contact him just outside of the ruins of the Gilnean capital.\n\nFind him and he'll direct you to the target.", objectives = "" }
WordHunterWoW_QuestEN[30093] = { title = "Assassinate Creed", description = "The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out.\n\nOnly a surgical assassination can end this!\n\nThe bridge behind me is relatively unguarded. Slip in through merchant's square and head south - you'll find Creed in the middle of the military district.\n\nI'll keep an eye on you and pull you out if there's any trouble.\n\n...There WILL be trouble!", objectives = "" }
WordHunterWoW_QuestEN[30094] = { title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", objectives = "" }
WordHunterWoW_QuestEN[30095] = { title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", objectives = "" }
WordHunterWoW_QuestEN[30096] = { title = "Murozond", description = "If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me.\n\nThe creature that blocks us from accessing this time passage is named Murozond. He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing.\n\nThis is why you were brought here, {name}.", objectives = "" }
WordHunterWoW_QuestEN[30097] = { title = "Archival Purposes", description = "From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us.\n\nWe believe that the most interesting and valuable elements of this future are the powerful \"echoes\" that roam the dragonshrines.\n\nTake this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight's depository.", objectives = "" }
WordHunterWoW_QuestEN[30098] = { title = "The Well of Eternity", description = "We must move quickly, before any remaining Infinite agents intervene. Time is precious.\n\nI will now take you from your distant future into your distant past... the War of the Ancients. Our goal is the Dragon Soul, an artifact of immense power... enough power to break Deathwing, and end his reign over your present.", objectives = "" }
WordHunterWoW_QuestEN[30099] = { title = "In Unending Numbers", description = "Between us and the Dragon Soul lies a legion of demons. They will have to be dispatched before we proceed.\n\nIf my timing is correct - and it usually is - a young night elf named Illidan Stormrage should be crossing our path shortly. He will undoubtedly be of some use when it comes to demon hunting.\n\nHelp Illidan disable the demons' portals, then slay their leader, Peroth'arn.", objectives = "" }
WordHunterWoW_QuestEN[30100] = { title = "The Vainglorious", description = "Queen Azshara and her royal guard lie ahead of us. We cannot afford the possibility of any interference with our plan. So we will take the fight to her, before she has a chance to meddle.\n\nIt is quite unlikely that you will kill Queen Azshara today; very few coherent timelines exist along that branch. Consider it a victory if you are simply able to occupy her attention, however temporarily.", objectives = "" }
WordHunterWoW_QuestEN[30101] = { title = "The Path to the Dragon Soul", description = "I cannot simply fly up and grab the Dragon Soul. The old gods protect it.\n\nTo make matters worse, their shield is strengthened by the swirling, arcane energies that emanate from the Well of Eternity, and those energies are being focused by the great demon Mannoroth.\n\nDistract Mannoroth, and the link between the Dragon Soul and the Well will be broken. Without the Well's power, the old gods' ward will be weakened, and the Dragon Soul will be vulnerable.\n\nAnd then I will take it.", objectives = "" }
WordHunterWoW_QuestEN[30102] = { title = "The Hour of Twilight", description = "There's no need to stand around here forever. Have you forgotten? We can CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the future.\n\nThat Dragon Soul that you just liberated? Thrall already has it, back in your present day. And he's going to need your help.\n\nYou ready to go?", objectives = "" }
WordHunterWoW_QuestEN[30103] = { title = "To Wyrmrest!", description = "The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to you, it is now safely in our hands.\n\nCome! The aspects await us. We must bring the Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.", objectives = "" }
WordHunterWoW_QuestEN[30104] = { title = "Documenting the Timeways", description = "You... {name}, was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative.\n\nI require more information for our archive. While you and Nozdormu don't intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data.\n\nI require information on Captain Varo'then, one of Azshara's pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?", objectives = "" }
WordHunterWoW_QuestEN[30105] = { title = "The Twilight Prophet", description = "The missive reads as follows:\n\n\"The Hour of Twilight is upon us. The world-shaman Thrall approaches Wyrmrest with the Dragon Soul in hand, feebly whimpering one final threat to destroy our glorious master.\"\n\n\"Stop Thrall, and we win our war. I will be watching you from nearby.\"\n\n   ~ The Twilight Prophet", objectives = "" }
WordHunterWoW_QuestEN[30106] = { title = "The Deed is Done", description = "Prince Wrathion will be pleased to hear that you've succeeded. You should report back to him at Ravenholdt Manor.\n\nThe Prince has been known to be extremely generous to those who help him. ", objectives = "" }
WordHunterWoW_QuestEN[30107] = { title = "Cluster Clutch", description = "The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind.\n\nI need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight's Hammer to control the most powerful of elementals.\n\nA great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing's minions and bring the gems to me.", objectives = "" }
WordHunterWoW_QuestEN[30108] = { title = "Our Man in Karazhan", description = "Your next target is the Black Dragon Nalice, who is engaged in some sort of arcane debauchery beneath the ruined tower of Karazhan.\n\nYour primary mission is to destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to augment the power of the daggers I've given you.\n\nYour accomplice Zazzo has already been dispatched to the scene and awaits you there. He'll have more details.", objectives = "" }
WordHunterWoW_QuestEN[30109] = { title = "Blood of the Betrayer", description = "I've pinpointed Nalice to the Master's Cellar, an extended basement you'll find in the ruins up ahead.\n\nDragon cultists are everywhere, and Nalice has set up some strange arcane storage devices throughout the area. Perhaps you can use those to your advantage?\n\nSneak past the cultists, obliterate Nalice, and grab a vial of her blood for Wrathion.\n\nI'll keep my eyes on you and pull you out if you get into any trouble. But I'm NOT coming in there with you!", objectives = "" }
WordHunterWoW_QuestEN[30112] = { title = "A Score to Settle", description = "Utgarde's forces are organizing under the advisory of Prince Keleseth, a san'layn ambassador of the Scourge.\n\nWe cannot allow the vrykul to benefit from his counsel any further. Silence him.", objectives = "" }
WordHunterWoW_QuestEN[30113] = { title = "Victory in the Depths", description = "<Zazzo performs an enchantment on the vial of blood, then quickly hands it back to you, as though it's toxic.>\n\nDone! You'll want to get this back to Wrathion as soon as possible, along with those two daggers of yours.\n\nI don't know what he plans to do with this stuff. Between you and me, sometimes that little dragon kid creeps me out. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[30116] = { title = "Sharpening Your Fangs", description = "Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn't their fault. They must seek out their own destiny, free from the meddling of my kind.\n\nWe are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won't be enough. My work will require entire clusters. Gather them from my father's minions...", objectives = "" }
WordHunterWoW_QuestEN[30117] = { title = "Stoneplow Thirsts", description = "Excuse me... {name}? Did I hear your name correctly?\n\nI've come from Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the Stormstout Brewery is all boarded up!\n\nIt looks like your handsome friend there - no, not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town in need?", objectives = "" }
WordHunterWoW_QuestEN[30118] = { title = "Patricide", description = "Your next target has claimed the lives of all of my other assassins. I need you to kill my father himself.\n\nYou must destroy Deathwing.\n\nWe are out of time. His madness has already corrupted all the others of my kind, and his darkness will consume the world if he is not stopped.\n\nIf you by some miracle succeed, and can retrieve for me a piece of him - perhaps a fragment of the armor he uses to disguise his true chaotic nature - the reward I give you will be without equal. ", objectives = "" }
WordHunterWoW_QuestEN[30120] = { title = "Cleansing Drak'Tharon", description = "'Ey, mon, you be here! Dis is good, mon!\n\nDrak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", objectives = "" }
WordHunterWoW_QuestEN[30121] = { title = "Search Party", description = "I sent a diplomat to look for allies in the ruins east of here.\n\nMy diplomat has not returned and now Kang tells me this jungle is filled with a sinister people known as the mogu.\n\nChezin is my friend and Leza's brother. To lose a brother would cause her to give in to despair. She already has enough to worry about with her fever.\n\nCould you investigate the ruins east of here and find out what happened?", objectives = "" }
WordHunterWoW_QuestEN[30123] = { title = "Skitterer Stew", description = "Leza has a fever. No mother in labor should have a fever.\n\nMama Bramblestaff once told me that Skitterer Stew could heal almost any illness. Let us put this knowledge to the test.\n\nGather some intact skitterer glands for me while I get the herbs we'll need and I'll whip up a batch.", objectives = "" }
WordHunterWoW_QuestEN[30124] = { title = "Blind Them!", description = "These sunwalkers are a tiresome lot. I need soldiers with horde blood in their veins and honor in their hearts. Not some pacifist sun spirit filth.\n\nThe Alliance are here, {name}. Followed us no doubt, or somehow tracked the same visions Leza had that led us here. It doesn't matter. I don't want them to know how divided we are at the moment. Go kill their scout south of here before it can report back.\n\nHellscream's eyes upon you.", objectives = "" }
WordHunterWoW_QuestEN[30127] = { title = "Threat from Dojan", description = "Mogu? They seem like the elves, ancient and an over developed sense of entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not \"visiting\" this world. We are here. We are staying.\n\nTeach them this lesson. Quell their numbers in the ruins south and west of here. Break their amassing forces before they decide to attack.\n\nLearn what you can of how these creatures fight, and how they die.", objectives = "" }
WordHunterWoW_QuestEN[30128] = { title = "The Pools of Youth", description = "The mogu found the Pools of Youth!\n\nMama Bramblestaff used to tell me old stories about those. During the mogu empire they would use the waters to extend life.\n\nThing is those stories never ended well for some reason. As if the waters were cursed.\n\nEither way, we should investigate. There is a good chance those waters might help Leza.\n\nIt looks like the Pools of Youth are on the northwestern side of the ruins.", objectives = "" }
WordHunterWoW_QuestEN[30129] = { title = "The Mogu Agenda", description = "Mogu don't often gather in numbers like this. We should find out what they are up to.\n\nI thought I heard someone shouting orders near the center of the ruins.\n\nWe should probably see if he has information.", objectives = "" }
WordHunterWoW_QuestEN[30130] = { title = "Herbal Remedies", description = "Kang's remedy isn't working.\n\nThere is something else at work here. A power deep beneath the soil. It is sapping us of hope, hitting us with depression and despair.\n\nKang tells me this land has lotus plants. I might be able to make a tea that would hopefully lend Leza some strength.\n\nPlease, {name}, search the ruins south and west of here for lotus leaves. I will pay you for your efforts.", objectives = "" }
WordHunterWoW_QuestEN[30131] = { title = "Life", description = "My child is coming. I must help as I may.\n\nStay nearby, hero. If my wife and child survive, I would have them look on the face of the one who saved them.", objectives = "" }
WordHunterWoW_QuestEN[30132] = { title = "Going West", description = "Leza now walks with the ancestors of this strange land. I must look now to the living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nI sent a scout of my own to investigate the crane temple. Please, {name}, seek out my scout, get their report, then meet up with Kor and lend what aid you can to him.\n\nWe will join you as quickly as we are able.", objectives = "" }
WordHunterWoW_QuestEN[30133] = { title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker.", objectives = "" }
WordHunterWoW_QuestEN[30134] = { title = "Wild Things", description = "Welcome to the Order of the Cloud Serpent, {race}. I can see from the spark in your eye that you wish to join the Order.\n\nLet me get a good look at you.\n\n<Elder Anli gently holds your head and gazes at your face.>\n\nHmm. I see honesty and earnestness in your heart. You have journeyed far to come here, but I am afraid you must go yet further.\n\nYour path into the Order begins now.\n\nSpeak to Instructor Tong at Windward Isle to the northeast to take the first step.", objectives = "" }
WordHunterWoW_QuestEN[30135] = { title = "Beating the Odds", description = "At first, the Slitherscale were too frightened to approach the wild serpents.\n\nThen, I caught them snatching the eggs under the cover of night.\n\nNow, they are slaughtering adults and hatchlings alike!\n\nIf we do not do something, these gentle creatures will be completely wiped out. Then there won't even be an Order of the Cloud Serpent to join!\n\nGo and slay these vile Slitherscales, and then we will talk.", objectives = "" }
WordHunterWoW_QuestEN[30136] = { title = "Empty Nests", description = "When the attacks began, the young hatchlings scattered in terror.\n\nThey are roaming around the island, lost and scared.\n\nIf you want to help, take this rope and leash the lost little ones. Take them back to their nests. Return them home.", objectives = "" }
WordHunterWoW_QuestEN[30137] = { title = "Egg Collection", description = "Ahhh, I should have known! You have the look of a hungry initiate.\n\nI would gladly help you choose a serpent egg, but the Slitherscale have thoroughly raided the cloud serpent nests.\n\nI'm terribly sorry. I don't know what to tell you.\n\nUnless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs, I'm afraid I can't help you.", objectives = "" }
WordHunterWoW_QuestEN[30138] = { title = "Choosing the One", description = "I have examined each egg, {name}. Out of the lot that you brought me, I have chosen the three eggs with the most promise.\n\nYou may choose only one egg to take with you. Are you ready to make your final selection?", objectives = "" }
WordHunterWoW_QuestEN[30139] = { title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", objectives = "" }
WordHunterWoW_QuestEN[30140] = { title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", objectives = "" }
WordHunterWoW_QuestEN[30141] = { title = "The Rider's Journey", description = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed.\n\nIn the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", objectives = "" }
WordHunterWoW_QuestEN[30142] = { title = "It's A...", description = "Oh my! This egg is going to hatch at any second!\n\nWell, looks like this little guy is eager to meet you.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[30143] = { title = "They Grow Like Weeds", description = "Ahh, it is you again, {name}.\n\nInstructor Windblade is looking for you. You can find her on the ridge to the east.\n\nShe has some news about your cloud serpent.", objectives = "" }
WordHunterWoW_QuestEN[30144] = { title = "Flight Training: Ring Round-Up", description = "Now that your serpent is fully grown, you are ready to begin flight training.\n\nAs with all novices, you must start at the beginning.\n\nYour first task is simple. Fly through 6 of the cloud rings between the spires to the east.", objectives = "" }
WordHunterWoW_QuestEN[30145] = { title = "Flight Training: Full Speed Ahead", description = "The next task will be a little harder.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[30146] = { title = "Snack Time", description = "Cloud serpents love to eat, and one of their favorite treats is the sugar minnow.\n\nThese fish can be found in salt or fresh water anywhere in Pandaria. I trust you have some skill in fishing, and your own fishing pole to catch them?\n\nBring me a fresh catch and I'm sure the hungry beasts around here will be very grateful.", objectives = "" }
WordHunterWoW_QuestEN[30147] = { title = "Fragments of the Past", description = "The Order of the Cloud Serpent's history stretches back thousands of years, and although we have tried to preserve the old ways, there are ancient techniques that have been lost over time.\n\nYou can help us recover some of this knowledge by searching Pandaria's dig sites for clues to our past.\n\nUse your archaeology skill to survey around Pandaria and bring me whatever you find.", objectives = "" }
WordHunterWoW_QuestEN[30148] = { title = "Just a Flesh Wound", description = "Many of the baby hatchlings at Windward Isle have been injured as a result of all the fighting.\n\nI have been told that you may be able to help them, with your access to powerful bandages.\n\nPlease go northeast and use some of the best bandages you can acquire to save the injured hatchlings.", objectives = "" }
WordHunterWoW_QuestEN[30149] = { title = "A Feast for the Senses", description = "I have heard that you know a thing or two about cooking.\n\nAs it so happens, serpents love to eat Fish Cakes.\n\nIf you use your culinary skills and bring me 5 of these dishes, the cloud serpents around here will be very happy.", objectives = "" }
WordHunterWoW_QuestEN[30150] = { title = "Sweet as Honey", description = "<The hatchling scampers about, then whines and whimpers.>\n\nFrom the cloud serpent's behavior, you have a hunch that it wants a sweet treat.\n\nThe fragrant trees in The Arboretum are home to many honey hives.\n\nIt will be a simple matter to collect combs from the nearby honeykeepers.", objectives = "" }
WordHunterWoW_QuestEN[30151] = { title = "Catch!", description = "<The hatchling looks up at you with a bored, listless expression.>\n\nYou have a feeling the serpent is tired of being cooped up all day.\n\n How about playing a little game of catch?", objectives = "" }
WordHunterWoW_QuestEN[30152] = { title = "The Sky Race", description = "The time for the great race is upon us!\n\nTraverse the course among the spires and pass through the checkered flags on each of the 10 balloon checkpoints.\n\nMake sure to pass underneath the finish line when you are done.\n\nThe competition will be fierce, but I wish you luck. Speak to me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[30154] = { title = "The Easiest Way To A Serpent's Heart", description = "<The hatchling scowls at you.>\n\nUh-oh, looks like someone is in a bad mood today!\n\nLuckily, you know just the thing that will cheer up the little beast.\n\nCloud serpents love the taste of tiger meat, but the tender flanks can be... challenging... to acquire.\n\nLuckily, you recall there are some fat, juicy tigers to the northeast, on Windward Isle.\n\nSure, you might suffer some scratches and a little mauling, but it's all worth it for your serpent, right?", objectives = "" }
WordHunterWoW_QuestEN[30155] = { title = "Restoring the Balance", description = "The situation at the islands remains dire, {name}.\n\nThe Slitherscale saurok have not responded to our attempts at peace, so only one option remains.\n\nIn order to protect the wild cloud serpents, we must rid the island of their presence. Only then can the cloud serpents be left to live in peace.", objectives = "" }
WordHunterWoW_QuestEN[30156] = { title = "Feeding Time", description = "<The serpent darts forward and bites your fingers.>\n\nOuch! It seems, without a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can be found on the wild cloud serpent island to the northeast.\n\nPerhaps some turtle meat will fill the hatchling's voracious appetite.", objectives = "" }
WordHunterWoW_QuestEN[30157] = { title = "Emptier Nests", description = "Oh, thank goodness, another cloud serpent trainer!\n\nI just received word that the wild hatchlings at Windward Isle to the northeast are in serious trouble!\n\nWhile the adults fight those terrible saurok, who is watching the cute little babies? No one, that's who!\n\nWE HAVE TO SAVE THEM!\n\nI'm sending every trainer I can find to go and help. If you aren't too busy, can you make sure the hatchlings are safely delivered back to their mothers' nests?", objectives = "" }
WordHunterWoW_QuestEN[30158] = { title = "Disarming the Enemy", description = "If we are to stop the poachers, we need to take more aggressive action.\n\nIf we can remove the enemies' primary tools for killing and capturing serpents, we may be able to stop their operation altogether.\n\nI need you to go into their territory on the eastern end of Windward Isle and steal their weapons.\n\nA cat without claws cannot strike.", objectives = "" }
WordHunterWoW_QuestEN[30159] = { title = "Preservation", description = "Oh no! We must stop them! {name}, is it? The Order needs your help!\n\nDo you know what those horrible Slitherscale saurok are doing?\n\nThey have the audacity to steal cloud serpent eggs straight from the matriarch's nests!\n\nWhile the cloud serpents become ever rarer, those brutes are... are...\n\n<Suchi takes a deep breath.>\n\n...they're eat their eggs for dinner! It's horrible!\n\nGo to Windward Isle to the northeast and recover any unbroken eggs that you can. As students of the Order, it's our duty!", objectives = "" }
WordHunterWoW_QuestEN[30163] = { title = "For the Tribe", description = "We fell back to the refuge when the mogu attacked but lost a number of our people along the way.\n\nTravel west and north of here and look for any captives you can rescue that could help us in our fight.\n\nLeave any Alliance you find to their fate.", objectives = "" }
WordHunterWoW_QuestEN[30164] = { title = "The Stoneplow Convoy", description = "I tried to save as many of the Stoneplow envoys as I could but these \"mantid\" dragged many of them off into the jungle.\n\nThese are civilians in need of our help.\n\nPlease take the herbs you gathered earlier. I've infused them with what gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as you can.", objectives = "" }
WordHunterWoW_QuestEN[30168] = { title = "Thieving Raiders", description = "Saurok!\n\nThese vile creatures are obsessed with killing and stealing. They attacked our settlement without provocation or warning.\n\nPlease, {class}, can you aid us?\n\nHelp us recover our lost possessions from these Riverblade raiders that march along the river and we will gladly reward you.", objectives = "" }
WordHunterWoW_QuestEN[30169] = { title = "Raid Leader Slovan", description = "The raiders are led by a particularly violent saurok known as Slovan. The Crane Temple usually comes to our aid when he attacks but now we find ourselves outmatched and outmaneuvered.\n\nPlease, {class}, aid us by destroying this raid leader.\n\nYou can find him in his den behind the Krasari Falls.", objectives = "" }
WordHunterWoW_QuestEN[30172] = { title = "Barreling Along", description = "No, no, no, don't you worry about pickin' 'em up. I can hold these here barrels.\n\nI may not be the handsomest pandaren, or the smartest, or any fun to be around in the slightest, but I'm stronger than a mushan beast.\n\nI'mma just need you to lead the way.", objectives = "" }
WordHunterWoW_QuestEN[30174] = { title = "For Family", description = "Kor should have caught up by now. He said he was going to secure the Ruins of Korja east of here and meet us to help with the mantid threat.\n\nHe may need help against Groundbreaker Brojai. Could you assist him? Kang and I will follow shortly.", objectives = "" }
WordHunterWoW_QuestEN[30175] = { title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", objectives = "" }
WordHunterWoW_QuestEN[30178] = { title = "Into the Wilds", description = "Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker.", objectives = "" }
WordHunterWoW_QuestEN[30179] = { title = "Poisoned!", description = "The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to Dezco... in Thunder Cleft, west of here.", objectives = "" }
WordHunterWoW_QuestEN[30181] = { title = "Mushan Mastery", description = "Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on probably. A fine trophy.\n\nIf you are lookin' to test your mettle as a big game hunter, start with them.", objectives = "" }
WordHunterWoW_QuestEN[30182] = { title = "Fox Mastery", description = "So, when I was scouting east of here I saw a collection of foxes. That's what I first learned to hunt when back on the Wandering Isle.\n\nIf you want to see the challenge a young pandaren hunter faced when growing up, head east and face off against a bunch of foxes. They tend to be clever and cunning so be on your guard. ", objectives = "" }
WordHunterWoW_QuestEN[30183] = { title = "Stalker Mastery", description = "Tigers! No matter what land I go to I hear about these big fanged beasts. And yet I haven't had a chance to hunt any of them.\n\nLet's go hunt some tigers. I'll go east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near those mushan.", objectives = "" }
WordHunterWoW_QuestEN[30184] = { title = "Mushan Mastery: Darkhide", description = "My boy here is a talented hunter... in training. Let's show him an old 'Nessy style hunt shall we?\n\nI saw a mighty big mushan east of here with a hide dark as night. It looked like it had taken down a number of hunters in its day.\n\nIf you want a big game hunt, go try an' take it on.", objectives = "" }
WordHunterWoW_QuestEN[30185] = { title = "Tortoise Mastery", description = "Granted, tortoises are not big game but they can be mean game. They also work as the perfect bait for bigger game!\n\nGotcher found some ol' tablets sayin' that the Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the waters as it were.\n\nWell ah mean to see me what's down in that water. Gather up some fresh tortoise shells and meet me at the pit.\n\nLet's see if ol' legends be true.", objectives = "" }
WordHunterWoW_QuestEN[30186] = { title = "Parental Mastery", description = "If them tablets were correct, all ay got ta do is a small dance ritual and the big thing o' the deep will be summoned.\n\nWhen it comes out, we'll get 'em and show me pop we are both true big game hunters like him.", objectives = "" }
WordHunterWoW_QuestEN[30187] = { title = "Flight Training: In Due Course", description = "Now that you have learned the basics of the race, you should go learn the course.\n\nExplore the spires and collect a race flag from each of the checkpoints.\n\nFly through each checkered flag to collect it.", objectives = "" }
WordHunterWoW_QuestEN[30188] = { title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", objectives = "" }
WordHunterWoW_QuestEN[30190] = { title = "Sprite Plight", description = "Sprites again! I hate these things. We need to stop them before they hurt someone or burn down half of the village!\n\nIf you see any of the pests, please deal with them! ", objectives = "" }
WordHunterWoW_QuestEN[30191] = { title = "Steer Clear of the Beer Here", description = "Someone left some beer out up on the southern rise and now the sprites have developed a taste for our brew. They've been sneaking into town all morning, stealing whatever kegs they find.\n\nBring back what you can. A pandaren worker without brew is just... it won't be very productive. We need the men in good spirits.", objectives = "" }
WordHunterWoW_QuestEN[30192] = { title = "My Town, It's on Fire", description = "I don't know if you noticed, but my town is burning...\n\nThe sprites have started kicking the braziers! They're going to set fire to the whole town!\n\nPlease help us! Stamp out any fires you see!", objectives = "" }
WordHunterWoW_QuestEN[30193] = { title = "Meating Expectations", description = "Hard workers deserve hearty meals, but I'm all out of good meat!\n\nCan you head out into the forest and get me some fresh gazelle meat?", objectives = "" }
WordHunterWoW_QuestEN[30194] = { title = "Encroaching Storm", description = "The villagers have lost another yak this morning to one of the thundermaw wolves from across the river. The wolves grow bold.\n\nThis is a sign that they are breeding beyond the vale's ability to sustain them. It's time to thin their numbers again.\n\nIf you are willing to aid me in this, you would have my sincere appreciation.", objectives = "" }
WordHunterWoW_QuestEN[30195] = { title = "Blooming Blossoms", description = "Would you do a humble merchant a favor? I've been needin' to refresh my stock of eternal blossoms. They grow in the woods nearby.\n\nCould you help me out, perhaps?", objectives = "" }
WordHunterWoW_QuestEN[30196] = { title = "Lushroom Rush", description = "Building a new village makes for hungry workers it seems!\n\nI have a hearty stew recipe prepared, but I need some lushrooms from the Tu Shen Burial Ground to the east. Apparently there are roused spirits causing trouble up there though, and I'm not very well suited for the violent life.\n\nIf you're heading up the burial grounds today, could you collect some lushrooms for me?", objectives = "" }
WordHunterWoW_QuestEN[30200] = { title = "In Ashen Webs", description = "We used to have the trainees clear out the ruins of spiders as part of their training, but now we send them straight to the mogu front. The spiders have gotten out of control.\n\nCare to put things back in control?", objectives = "" }
WordHunterWoW_QuestEN[30204] = { title = "That's Not a Rock!", description = "Okay, these spiders are seriously creeping me out. Especially those egg sacs they leave lying around that I keep accidentally stepping on only to be covered in very little but very creepy spiderlings. Ug, makes me shudder just thinking about it.\n\nI say you burn them. Burn them all.", objectives = "" }
WordHunterWoW_QuestEN[30205] = { title = "Runelocked", description = "Hello, friend.\n\nOne of Leven's men brought word to me of a mogu artifact in the eastern ruins, but said he couldn't figure out how to retrieve it. I suspect it's guarded by one of their rune locks.\n\nIf you go to the artifact, you should find four runes somewhere nearby that when activated will release the lock. If you could bring the artifact back to me, I would be very grateful.", objectives = "" }
WordHunterWoW_QuestEN[30206] = { title = "Runes in the Ruins", description = "In the walls of the ruins themselves, there are precious runestones that we can make use of back in the eastern vale.\n\nIf you see any while you are within the ruins, would you be so kind as to bring them back to me?", objectives = "" }
WordHunterWoW_QuestEN[30225] = { title = "The Ashweb Matriarch", description = "My dear Kun spotted more spiders pouring out of the Guo-Lai Halls this morning, and when he went to investigate, he uncovered another spider matriarch inside.\n\nI need you to kill it.", objectives = "" }
WordHunterWoW_QuestEN[30226] = { title = "Blood on the Rise", description = "A small group of mogu have been sighted on Ruin's Rise, to the north.\n\nExtinguish them.", objectives = "" }
WordHunterWoW_QuestEN[30227] = { title = "Wulon, the Granite Sentinel", description = "One of the quilen statues in Guo-Lai Halls came to life and nearly killed my precious Kun. I won't have it! No one threatens my Kun.\n\nI want you to go in there and smash the thing to pieces. I'd do it myself, but I need to attend to my lover's wounds first.", objectives = "" }
WordHunterWoW_QuestEN[30228] = { title = "Troubling the Troublemakers", description = "The wood sprites are back. I need you to kill them before they cause anymore trouble.", objectives = "" }
WordHunterWoW_QuestEN[30229] = { title = "The Greater Danger", description = "I apologize for my harsh words earlier. Dezco might have been right to wait and move west with a unified strength.\n\nThe mogu hit us hard when we were searching the ruins west of here. They ambushed us using summoning portals and some dark magics. I haven't seen such evil sorcery used since Outland. \n\nWe need a respite. Head west, kill their summoners, cut their supply line.", objectives = "" }
WordHunterWoW_QuestEN[30230] = { title = "Re-Reclaim", description = "Mogu are thugs. They have always been thugs.\n\nOnly when they ruled their empires in the old stories did they ever know any kind of magic.\n\nBut these mogu are using arcane portals and spells. We need to stop them!\n\n{name}, look for any artifacts the mogu are using to cast their magics with. I saw a number of their collectors and reclaimers to the west and north that were gathering these items.", objectives = "" }
WordHunterWoW_QuestEN[30231] = { title = "Pomfruit Pickup", description = "I need more pomfruit! Go knock some loose from the trees for me, would you?\n\nTake this, I use it when I go harvesting. Things go quicker when the fruit comes to you!", objectives = "" }
WordHunterWoW_QuestEN[30232] = { title = "Ruffling Some Feathers", description = "The hawk numbers in the vale are thriving. This is opportune for our fletchers, for we will need a great number of feathers if we are to keep the archers upon the wall stocked with arrows.\n\nIf you would not mind, could you aid us in gathering these feathers?", objectives = "" }
WordHunterWoW_QuestEN[30233] = { title = "Cracklefang", description = "Hi! So, I have a dilemma. I've only got one good wolf name.... wait for it... Cracklefang! I know, amazing right?! But now there are TWO big nasty wolves in the forest, which is all kinds of confusing.\n\nI need you to kill one of them so I can free up the name. Should be simple enough, yeah? Especially for someone of your incredibleness.\n\nSo, are you on board? I'm hoping for yes!", objectives = "" }
WordHunterWoW_QuestEN[30234] = { title = "Vicejaw", description = "Vicejaw! Sounds absolutely violent, does it not? I came up with it myself, and I think it's very suiting. I tried to wrestle my staff away from him for hours, but he simply would not let go!\n\nOkay, it was really more like a few seconds. I like to be truthful to my friends, even if it makes my stories significantly more boring.\n\nAnyway, would you be so kind as to release your oh-so-potent wrath upon this crocolisk with a vice-like jaw, and then kindly bring my staff back? Preferably in-tact!", objectives = "" }
WordHunterWoW_QuestEN[30235] = { title = "Quid Pro Quo", description = "Quid is a very powerful and very ancient water spirit, though you might not know it with his child-like ways.\n\nThis morning, Quid nearly killed several villagers in the bar when he jokingly caused several of the water kegs to explode.\n\nAs long as the water flows, Quid will remain. He cannot be slain. But he can be reminded that we do not take his dangerous antics in jest.\n\nWould you be willing to carry this message to him on behalf of the village?", objectives = "" }
WordHunterWoW_QuestEN[30236] = { title = "Aetha", description = "It seems Aetha has been levitating the livestock and dropping them into the river again. The mayor has requested that we remind her that these kinds of jokes are not welcomed.\n\nWould you be so generous as to travel to the ridge above the village and teach her this lesson? You cannot kill her, you can only send her away for a time, but this should prove a potent reminder.", objectives = "" }
WordHunterWoW_QuestEN[30237] = { title = "The Pandaren Uprising Relived", description = "In the Tu Shen Burial Ground to the east, the spirits of ancient mogu are locked in battle with the spirits of our pandaren ancestors that rose up against them. The spirits have seen no rest since the return of the mogu to the valley.\n\nIf you would be willing to go to the graveyard and force the mogu to relive their defeat again, we might offer some lasting peace to the spirits of our ancestors.", objectives = "" }
WordHunterWoW_QuestEN[30238] = { title = "Return to Rest", description = "The spirits of our ancestors are reliving one of the most revered battles in our history at the Tu Shen Burial Grounds to the east.\n\nDo as I ask, {race}, and honor their gravestones. Remind them that they are respected even these many years later, and that they are deserving of peaceful rest.", objectives = "" }
WordHunterWoW_QuestEN[30239] = { title = "Lao-Fe the Slavebinder", description = "You can hear the spirit of Lao-Fe, the Slavebinder shouting taunts from the cave at the top of Tu Shen Burial Mound.\n\nDefeating him will surely serve to ensure victory for the spirits of the pandaren monks.", objectives = "" }
WordHunterWoW_QuestEN[30240] = { title = "Survival Ring: Flame", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", objectives = "" }
WordHunterWoW_QuestEN[30241] = { title = "Warn Stoneplow", description = "So much death. And more to come, if Ambassador Han's stories of the mantid are to be believed.\n\nWe must help. We must do our part to save lives.\n\nTravel to Stoneplow. Warn them of the coming mantid attack.\n\nI will join you with what forces I can muster once I have laid Kor's body to rest.", objectives = "" }
WordHunterWoW_QuestEN[30242] = { title = "Survival Ring: Blades", description = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", objectives = "" }
WordHunterWoW_QuestEN[30243] = { title = "Mantid Under Fire", description = "The mantid are attacking again, and we're a bit short-handed up on the wall. In hopes that you'd help, I saved one of the more fun posts for you: the hot oil!\n\nIt's a bit more violent and a bit less scandalous than it sounds.\n\nIt's simple really. Get up on the wall, find one of the oil stations, and dump it on any of the mantid pouring up against the wall. It's very effective.", objectives = "" }
WordHunterWoW_QuestEN[30244] = { title = "Along the Serpent's Spine", description = "There are mantid on top of the wall. The defenders on the ramparts are calling for help!", objectives = "" }
WordHunterWoW_QuestEN[30245] = { title = "Lost Scouts", description = "We sent some scouts towards the Five Sisters to the north to try and find whatever mogu leader has risen up to direct their movements in the valley. Few have returned.\n\nI'd like to think they're just off downing too much ale or being irresponsible with some young pandaren, but they may actually be in some trouble.\n\nCan you scout for the scouts? And see if they've turned up any information on that leader while you're at it?", objectives = "" }
WordHunterWoW_QuestEN[30246] = { title = "Upon the Ramparts", description = "Some of the mantid have made it on top of the wall. There's some risk they'll route the soldiers we have posted there if their numbers are large enough.\n\nI need you to get on top of the wall and help clear out any that have broken through.", objectives = "" }
WordHunterWoW_QuestEN[30248] = { title = "The Butcher", description = "Scouts reports place the displaced Shao-Tien Imperion at the north end of the wall.\n\nAngi Autumnlight spelled out your goal in no uncertain terms: find this leader and kill him.", objectives = "" }
WordHunterWoW_QuestEN[30249] = { title = "Under the Setting Sun", description = "A giant beast has burrowed under the gate into the courtyard. The defenders need your help!", objectives = "" }
WordHunterWoW_QuestEN[30251] = { title = "Vyraxxis, the Krik'thik Swarm-Lord", description = "A giant mantid is terrorizing the inside of the wall. It seems doubtful that the defenders will be able deal with it without you.", objectives = "" }
WordHunterWoW_QuestEN[30252] = { title = "A Helping Hand", description = "I've been pushing and shoving and hammering all morning, but it's hopeless.\n\nThese rocks won't budge!\n\n\"It will be a breeze,\" Grandpa said. \"Farming's like breathing!\" he said. Maybe for him, but not for me!\n\nHow am I supposed to succeed at this whole FARMING thing if I can't even clear my farm for planting?\n\nHey, wait a minute. You look like you've got some muscle on you.\n\nWould you be willing to help me out? Just until I can catch my breath.", objectives = "" }
WordHunterWoW_QuestEN[30254] = { title = "Learn and Grow II: Tilling and Planting", description = "Okay, now we've got our seeds, it's time to plant them.\n\nFirst, we have to prepare the soil! You gotta till the soil and break it up to make a nice bed for our little sprouts.\n\nTill those two plots of soil over there, then plant the seeds in them.", objectives = "" }
WordHunterWoW_QuestEN[30255] = { title = "Learn and Grow III: Tending Crops", description = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay?\n\nThe point is, now that our cabbages have sprouted, they need attention! Today they look a little dry, so you should water them.\n\nHere's the old watering can grandpa left. It will always be near the field if you need it.", objectives = "" }
WordHunterWoW_QuestEN[30256] = { title = "Learn and Grow IV: Harvesting", description = "It's time for our hard work to pay off! Normally we'd have to wait a day before the crops are ready to harvest.\n\nFortunately, those seeds Greenfield gave us were specially designed to grow FAST. The yield won't be worth much, but they're good for stepping new farmers through the process.\n\nOur cabbages should be ready to harvest. I'll let you do the honors, of course!", objectives = "" }
WordHunterWoW_QuestEN[30257] = { title = "Learn and Grow V: Halfhill Market", description = "All right friend, all of that farming was just for practice!\n\nAre you ready to try the real thing?\n\nThere's a lady by the name of Gina Mudclaw who runs the Halfhill Market, which is across the street to the south.\n\nI heard she's looking to buy some vegetables. Since it's your first time meeting her, you shouldn't go empty-handed.\n\nWhy don't you look around the ranch and see if there are any items hiding around?\n\nMight be that we'll find a good gift to take to our new neighbor!", objectives = "" }
WordHunterWoW_QuestEN[30258] = { title = "Mung-Mung's Vote I: A Hozen's Problem", description = "I've been thinkin' about how to get into the Tiller's good graces, {name}.\n\nNow, the Tiller's Union accepts new farmers each year, and there are five members on the voting council.\n\nWe already got Gina's vote, but we'll have to prove ourselves to the other four members of their board.\n\nWhy don't you go over and say hello to Mung-Mung? He works with Mr. Mudclaw out on the Mudclaw's farm to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[30259] = { title = "Mung-Mung's Vote II: Rotten to the Core", description = "Dem virmen's back!\n\nThey been biting Mr. Mudclaw's carrots. Ruining his crop. And who is gonna pay? Mung-Mung, that's who!\n\nYou go get the chewed up carrots before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the ground in the virmen's tunnels, too.\n\nOtherwise, Mung-Mung in big trouble.\n\nYou do this for me?", objectives = "" }
WordHunterWoW_QuestEN[30260] = { title = "Growing the Farm I: The Weeds", description = "Hey {name}, I've been thinkin' recently about expanding my farm.\n\nSee that plot there that's just covered in weeds? If we can get rid of those weeds, we could use that land for planting.\n\nI heard there's a farmer by the name of Gai Lan who knows a thing or two about weed whackin'.\n\nHis farm is just out west. Go talk to him and see if he'd be willing to help us.", objectives = "" }
WordHunterWoW_QuestEN[30261] = { title = "Roll Club: Serpent's Spine", description = "Get to the bottom of the wall in the fastest time possible.\n\nSpeak to me when you're ready to roll.", objectives = "" }
WordHunterWoW_QuestEN[30263] = { title = "Clearing in the Forest", description = "The Shao-Tien are on their heels. Most of them retreated to Winterbough Glade after their last defeat. We should press the advantage.\n\nTake the fight to these mogu in the clearing to the northwest. Let us leave them no minute of rest as long as they remain in the Vale.", objectives = "" }
WordHunterWoW_QuestEN[30264] = { title = "Enemy at the Gates", description = "The mantid forces are pouring against the wall. I've arranged for some flying serpents to cut away at their forces from the air.\n\nWould you be willing to take the reigns on one of them?", objectives = "" }
WordHunterWoW_QuestEN[30265] = { title = "Sparkle in the Eye", description = "I've been staring down into the waters of the lake, pondering life, love, and everything beautiful, and suddenly I realized that the sparkles in the water aren't just a reflection of my radiant personality, there are actually some sort of shining objects down there! Surely valuable.\n\nWould you mind taking a drip and relieving the lake's depths of its mysterious sparkles? Pretty please?", objectives = "" }
WordHunterWoW_QuestEN[30266] = { title = "Bloodied Skies", description = "We have cannons set up on the top of the towers flanking the main gate. They are our best method to clear the skies when the flying mantid try to pass over the wall, like they are now.\n\nLooks like you're on, {name}.", objectives = "" }
WordHunterWoW_QuestEN[30267] = { title = "Watery Woes", description = "I love fishing. I'd be enjoying myself much more, however, if I had my bait and my lures. They were thrown away in a... a misunderstanding with my wife, Rin.\n\n<Gladecaster Lang sighs.>\n\nShould I let a whole day of fishing be ruined, just because of a little domestic squabble? No! All I need is bugs and feathers, after all, and this glade is filled with those two things.\n\nCare to help a fisherman out?", objectives = "" }
WordHunterWoW_QuestEN[30268] = { title = "The Murksweats", description = "Take a good look. The river nearby is swarming with these snakes. Their venom causes a condition the locals call \"the murksweats.\"\n\nSeveral refugees were bitten as they fled the temple and have already begun to show symptoms: nausea, vomiting, and intense sweating as the body rejects all fluids, causing dehydration and potentially death.\n\nWe are administering anti-venom as quickly as possible, but we'll need more venom glands. Don't bother removing the glands yourself - just bring back the whole head.", objectives = "" }
WordHunterWoW_QuestEN[30269] = { title = "Unsafe Passage", description = "As we say at the temple: \"Never fight a tiger with a hozen on your back.\"\n\nWe will deal with the sha, but first we must see to the more immediate... nuisance.\n\n<Koro slams the writhing saurok HARD against the stone.>\n\nGroups of refugees from the temple are heading for a camp to the north, but they're being ambushed by saurok. Help me see the next group to the camp and we'll figure out our next move from there.", objectives = "" }
WordHunterWoW_QuestEN[30270] = { title = "Blinding the Riverblades", description = "\"A hooded falcon catches no quarry.\"\n\nThis is one of the first mantras we teach young monks at the temple. It means that even a foe as swift and lethal as a falcon can be neutralized by depriving its senses.\n\nThe saurok have scouts all over the region acting as eyes for their raiding parties.\n\nIt's time we put their eyes out, don't you think?", objectives = "" }
WordHunterWoW_QuestEN[30271] = { title = "Sha Can Awe", description = "The sha have the mysterious ability to evoke powerful, often overwhelming, emotional responses in their victims.\n\nAs we fled the temple, senior members of the Crane Wing order stayed behind to cover our escape. They are no doubt being subjected to intense emotional trauma, and I fear they are not all strong enough to resist falling into despair.\n\n{name}, we have to show them there is still hope! Show them that despair CAN be defeated!", objectives = "" }
WordHunterWoW_QuestEN[30272] = { title = "Striking the Rain", description = "Now as for that \"striking the rain\" part... well, sometimes you have to.\n\n\"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the eye.\"\n\nThere seems to be no end to the sha pouring out of the temple. But in order to see beyond the veil of despair, you must carve through it.\n\nWith any luck, you'll find a sun behind the clouds...", objectives = "" }
WordHunterWoW_QuestEN[30273] = { title = "In the House of the Red Crane", description = "\"Broken are the bodies wherein hopeless hearts reside - the blight of despair strikes forth from inside.\"\n\nThis was the last piece of wisdom the Red Crane imparted to me, just hours before the Sha outbreak.  It makes sense now...\n\n{name}, when the Sha attacked, they broke forth from the temple's basement...\n\nAll of his teachings - the very Way of the Crane itself... it's all been preparation for facing the Sha of Despair.\n\nThe Red Crane has been expecting this conflict for centuries!", objectives = "" }
WordHunterWoW_QuestEN[30274] = { title = "The Arcanic Oubliette", description = "An Alliance member? Here? Elune be praised.\n\nMy team has encountered a snag. We opened a portal to this land using some ancient scrolls we had found that predated Azshara's rule.\n\nUnfortunately, the coordinates provided on the tablets were warded and the portal that meant to take us to our destination landed us in this oubliette.\n\nWe have been trapped here for days, and it is slowly leaching our energies to power itself.\n\nCan you find the nearby shackles that bind the oubliette and disable them?", objectives = "" }
WordHunterWoW_QuestEN[30275] = { title = "A Crocolisk Tale", description = "How could this crocolisk have grown so large?\n\nCertainly, rumors exist of very old crocolisks that have grown to enormous sizes... but this female can't be more than a dozen years old.\n\nPerhaps someone in New Cifera can shed some light on the subject.", objectives = "" }
WordHunterWoW_QuestEN[30277] = { title = "The Crumbling Hall", description = "An ancient mogu artifact has been uncovered in the Guo-Lai Vault, beyond the Hall of Statues. We've made repeated attempts to retrieve it, but none have been successful.\n\nWe cannot let this artifact fall into the hands of the Shao-Tien. I need someone capable to retrieve it, and quickly.\n\nAre you in?", objectives = "" }
WordHunterWoW_QuestEN[30280] = { title = "The Thunder Below", description = "Roars have been echoing out from inside the Guo-Lai Halls. The mogu have awakened some ancient beast, and it will not be long before they attempt to release it upon my men.\n\nFind your way to the Hall of the Serpent and slay the beast before it can be unleashed upon us. I would trust no other with such a dangerous and important task.", objectives = "" }
WordHunterWoW_QuestEN[30281] = { title = "The Silent Approach", description = "<He leans over and draws a picture of what can only be a mogu, points towards the lake to the west, drags the blunt side of his dagger across his throat, and looks at you expectantly. It seems he wants you to kill mogu at Whitepetal Lake.>", objectives = "" }
WordHunterWoW_QuestEN[30282] = { title = "Burning Away the Filth", description = "The mogu have erected their filthy banners around the lake to the west, claiming it as their own. Take this torch and show them what we think of their banners.", objectives = "" }
WordHunterWoW_QuestEN[30283] = { title = "A Smashing Impression", description = "Sometimes I feel sorry for these mogu... maybe ripping out the spirits of other races is just their way of coping with family issues at home? Maybe we should be more sympathetic to where all this aggression stems from?\n\nOr we could just smash all their soul-stealing ritual objects down at the lake. That sounds more fun to me personally.", objectives = "" }
WordHunterWoW_QuestEN[30284] = { title = "A Thousand Pointy Teeth", description = "The water has been frothing with danger this day! Some sort of swarming, meat-eating fishy nastiness has taken up residence in our lake! Deplorable. And just when I was considering stripping down to my nothings to take a mid-day dip!\n\nYou are adept in the ways of slaughtering any manner of nasty, are you not? Would you put your skills to use this day, in the name of pandaren everywhere desiring a swim?\n\nIt's a truly noble cause, especially with me among their ranks!", objectives = "" }
WordHunterWoW_QuestEN[30285] = { title = "Wu Kao Scouting Reports", description = "There were some scouting reports unaccounted for after the attack. If we're lucky, they're still out in the village, but the mogu may have gotten their hands on some of them as well.\n\nIf you could bring back any scouting reports you find, it would definitely put my mind at ease. We can't afford to let the mogu in on our positions or any of the artifacts we've found, lest the men be in even more danger than they already are.", objectives = "" }
WordHunterWoW_QuestEN[30286] = { title = "Backed Into a Corner", description = "Many villagers are cornered and scared, unable to defend themselves. You will need to defend them. Rescue them.\n\nGo quickly friend, save as many as you can!", objectives = "" }
WordHunterWoW_QuestEN[30287] = { title = "Mogu Make Poor House Guests", description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone.\n\nYou help?  Rook will tell Leven you helped.  Promise.", objectives = "" }
WordHunterWoW_QuestEN[30288] = { title = "My Town, It's On Fire Again", description = "I don't know if you noticed, but my town is on fire... again.\n\nWe have water buckets all over town, but no one can get out to put out the fires. Please, please, help us!", objectives = "" }
WordHunterWoW_QuestEN[30289] = { title = "Freeing Mind and Body", description = "Mogu stealing peoples minds! Making them do evil things.\n\nDon't kill them, just kill the mogu, then they forget about all the mogu mind stealing and stop being evil. You should fix people like Rook is.", objectives = "" }
WordHunterWoW_QuestEN[30290] = { title = "Stonebound Killers", description = "Mogu stone dog creatures chasing villagers and hurting them. Rook try to smash some, but they too fast.\n\nYou help smash some too?", objectives = "" }
WordHunterWoW_QuestEN[30291] = { title = "Stunning Display", description = "I've been talking to Tantan here... again... and he insists that fishing is some kind of fabulous. I was skeptical, but I gave it another go. I'm not a big fan of that whole holding a stick and waiting method though, so I tried something a bit more direct.\n\nWould you be a doll and go collect any of the still intact fish floating belly up in the lake for me?", objectives = "" }
WordHunterWoW_QuestEN[30292] = { title = "Rude Awakenings", description = "The mogu are taking over the minds of the saurok at the lake to our west and turning them against us! The thing is, they were already against us, so I'm not sure they really thought this thing through fully.\n\nAnyway, Anji's the fighter in this pair, I'm more the lover, so I'm looking for someone to do all the weapon swinging and spell flinging and war crying and such.\n\nCan you go kill some saurok for me?", objectives = "" }
WordHunterWoW_QuestEN[30293] = { title = "In Enemy Hands", description = "The Shao-Tien Mindbenders have taken over the minds of our defenders down at Whitepetal Lake to the west. Get down there and kill the mogu that are controlling them, but don't kill the defenders! Killing their captors should free them from their mind control.\n\nSooner would be better. Anji might try to go down there to help soon, and her ability to restrain herself when in the heat of things is not one of the qualities I married her for.", objectives = "" }
WordHunterWoW_QuestEN[30296] = { title = "Gaohun the Soul-Severer", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", objectives = "" }
WordHunterWoW_QuestEN[30297] = { title = "Baolai the Immolator", description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? Please?", objectives = "" }
WordHunterWoW_QuestEN[30298] = { title = "Painting the Ruins Red", description = "The mogu think they can inhabit these ruins uncontested. Let's show them the error in their ways.", objectives = "" }
WordHunterWoW_QuestEN[30299] = { title = "No Stone Unturned", description = "The mogu have forced spirits into their old statues to bring them to life, control them, and turn them against us.\n\nThe only way to free the bound spirits is to destroy their vessels.", objectives = "" }
WordHunterWoW_QuestEN[30300] = { title = "The Key to Success", description = "The mogu have taken prisoners. They'll be tortured or worse.\n\nFind any way you can to free them from their cages.", objectives = "" }
WordHunterWoW_QuestEN[30301] = { title = "Offering a Warm Welcome", description = "There is no more sure message we can send them then to burn the tents the sleep in.\n\nScour the ruins. Destroy every tent you find.", objectives = "" }
WordHunterWoW_QuestEN[30302] = { title = "The Imperion Threat", description = "Scouts spotted a Shao-Tien Imperion entering the Guo-Lai Halls. I need someone I can trust to make sure he doesn't come out of there alive.\n\nI think you're the {class} for the job.", objectives = "" }
WordHunterWoW_QuestEN[30304] = { title = "Hard as a Rock", description = "Hey! You know what awesome thing happened to me this morning?\n\nI was strolling through the ruins with Anji, eyes on the ground so I wouldn't step on anymore of those creepy spider pods, when one of the statues came to life and tried to smash me!\n\nAnji ended up doing the smashing. But I'm not satisfied. I think that you should go out there and smash all the statues, whether they're moving or not. It's the only way to be sure.", objectives = "" }
WordHunterWoW_QuestEN[30305] = { title = "He Knows What He's Doing", description = "You know He Softfoot? Sneaky guy, don't talk much. He put traps all over ruins for mogu. He said Rook just need to trick mogu into traps. Rook don't really know how.\n\nMaybe you do it? You find traps, you get bad guys into traps? Can you not tell He though, please?", objectives = "" }
WordHunterWoW_QuestEN[30306] = { title = "The Battle Ring", description = "We have some fresh trainees that are far from being a danger to you, but in numbers, they may prove enough of a challenge. And if not, they could use the lesson in humility.\n\nStep into the battle ring when you're ready. Don't go easy on them.", objectives = "" }
WordHunterWoW_QuestEN[30307] = { title = "The Eternal Vigil", description = "Good to have you with us, {class}. If you're joining the fight, I need more men out up at the Golden Stair to clear out the mogu setting up base there.\n\nCan I count on you?", objectives = "" }
WordHunterWoW_QuestEN[30308] = { title = "Stone Hard Quilen", description = "Leven always says the only good quilen is a dead quilen, and I'm inclined to agree. You here to aid the cause?", objectives = "" }
WordHunterWoW_QuestEN[30309] = { title = "Set in Stone", description = "The mogu have been sending their narcissistic stone effigies onto our battlefield today. They're brining them to life up on the Golden Stair.\n\nThe bigger they are, the harder we hit'm. You in?", objectives = "" }
WordHunterWoW_QuestEN[30310] = { title = "Thundering Skies", description = "The mogu have bent the will of sky serpents and turned them against us.\n\nThe defenders won't fare well against them, but you would. Head northwest towards the Golden Stair and remove them from the sky.", objectives = "" }
WordHunterWoW_QuestEN[30312] = { title = "Given a Second Chance", description = "A foolish contingent attempted to mount an offensive on the Golden Stair through the eastern pass, and were bombarded by cannons. Those that made it back are in bad shape, and there are still wounded out in the field.\n\nHere are some bandages. Use these, or any other healing skills you possess, and help get our wounded defenders back to safety.\n\nPlease hurry, there is little time.", objectives = "" }
WordHunterWoW_QuestEN[30313] = { title = "The Moving Mists", description = "<He looks down at the dead fog creature at his feet, looks up at you, then points out into the mists surrounding the lake. It seems he wants you to find and kill more of these fog creatures.>", objectives = "" }
WordHunterWoW_QuestEN[30314] = { title = "The Displaced Paleblade", description = "<He looks down at the dead saurok at his feet, looks up at you, then points out down the lake shore. It seems he wants you to find and kill more of these saurok.>", objectives = "" }
WordHunterWoW_QuestEN[30317] = { title = "Water, Water Everywhere", description = "How'd you like to make yourself useful?\n\nThe season's been awful dry lately. I need someone to water the crops out in the Heartland. Here's the thing: I need you to water ALL of the crops.\n\nI keep a few kites with Wing Nga, the flightmaster across the way. Grab one of those kites, then throw water on any areas that look dry and dusty.", objectives = "" }
WordHunterWoW_QuestEN[30318] = { title = "Chasing the Chicken", description = "Say, you there! {name}, was it? I've got a problem, and I need someone with better legs than mine to help me solve it.\n\nMy prize-winning chicken has flown the coop! Now she's out in the open, mingling with the other hens, wild birds, and... <gulp> ill-intentioned roosters.\n\nMy farm is west of here, south of the Skyrange. Could you find her, and bring her back to me?", objectives = "" }
WordHunterWoW_QuestEN[30319] = { title = "Pest Problems", description = "One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost field. I understand he's had some problems with pests.\n\nHe's got plenty of pesticide to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the marmots.\n\nWould you lend him a hand? With rampant hozen and virmen attacks, I can't afford to lose crops to simple pests.", objectives = "" }
WordHunterWoW_QuestEN[30320] = { title = "Free Spirits", description = "I came upon one of the Shao-Tien Soul-Render's daggers. It radiates a strong magic. I've been told it should allow you to enter their spirit vortexes.\n\nThe mogu use these to harvest spirits and bind them to their will, but I'm hoping you can use it to free the spirits.\n\nEnter any of the spirit vortexes you can find up on the Golden Stair, and free all the captive spirits you find.", objectives = "" }
WordHunterWoW_QuestEN[30321] = { title = "Weed War II", description = "Ssshhay... d'you know that guy over on the farm, with the... the *hic*... the weed problem? Gai Lan, I think his name was. I love that guy, man.\n\nAnywayshh, he said that if I *hic* sent an adventurer over to go pick his weeds, he'd get me some ale.\n\nIt's jusht a few weeds, not too many, probably.\n\n*hic*", objectives = "" }
WordHunterWoW_QuestEN[30322] = { title = "Money Matters", description = "I love working in the market, although there's one aspect of this job I really dislike: collecting debts.\n\nWhile most pandaren debts are simply due to laziness, there are a few unsavory characters around town who simply don't want to pay, and there's some who are just too poor.\n\nA few people here in town owe me money. Could you go talk to them, and remind them about what they owe?", objectives = "" }
WordHunterWoW_QuestEN[30323] = { title = "They Don't Even Wear Them", description = "A few weeks ago, a group of those jumpy little Springtail virmen broke into my lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but they still have most of my collection.\n\nIf you're headed up to the Springtail Crag, in the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry back.", objectives = "" }
WordHunterWoW_QuestEN[30324] = { title = "Not in Chee-Chee's Backyard", description = "Not all hozen are the same. Chee-Chee's tribe was forest hozen... came from Jade Forest. Pretty easy to get along with.\n\nThe Kunzen invaders... they come from mountains, far to the north. Not nearly as nice as Chee-Chee.\n\nThey come into our green land, take our things, leave big mess behind.\n\nChee-Chee wants to kill them. You like to help?", objectives = "" }
WordHunterWoW_QuestEN[30325] = { title = "Where It Counts", description = "I've been watching those Kunzen hozen, and I've noticed a consistent pattern. Whenever they're getting ready to attack, they participate in strange, barbaric rituals around their totem.\n\nIf we can disrupt this ritual, not only will we put off any impending attacks, we can deal a huge blow to their morale! So get in there, rough them up, and make as much of a mess as possible!", objectives = "" }
WordHunterWoW_QuestEN[30326] = { title = "The Kunzen Legend-Chief", description = "I've heard people talk about the hozen like they're just some tribe of barely-functional idiots... but that's not true! They have brains, too - they just don't all like to use them that much.\n\nI've heard that the Kunzen tribe has two chiefs - one in charge of fighting, and one in charge of stories, lore, and history.\n\nWhat I wouldn't give to see what kind of stories they tell...", objectives = "" }
WordHunterWoW_QuestEN[30327] = { title = "You Have to Burn the Ropes", description = "I, umm... well...\n\nOh, never mind. It was a stupid idea.\n\nIt's just that, I was thinking that maybe we can stop the Kunzen hozen from attacking us without having to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I think they're using them to climb down to our farms and...\n\nNo, forget it. It was a silly idea anyways.", objectives = "" }
WordHunterWoW_QuestEN[30328] = { title = "The Thousand-Year Dumpling", description = "One of my most popular recipes is the Thousand-Year Dumpling, which is filled with preserved vegetables.\n\nI normally let the vegetables ferment in a hole underneath my house, but when I looked for them this morning, they were gone!\n\nI blame those thieving virmen.\n\nBring them back, and I'll let you help me cook!", objectives = "" }
WordHunterWoW_QuestEN[30329] = { title = "Cindergut Peppers", description = "A certain few pandaren around here prefer their dishes unbearably spicy. Unfortunately, my access to such peppers is limited.\n\nThe Kunzen hozen, in the mountains to the west, often carry cindergut peppers. A few of those and I'll be set for a few days.\n\nSay, could you collect some for me? You might want to wear gloves if you'll be handling them directly.", objectives = "" }
WordHunterWoW_QuestEN[30330] = { title = "The Truffle Shuffle", description = "I like to bake with truffles... when I can find them. They only grow up on the Skyrange, and in very, very scarce amounts.\n\nThey're a fantastic ingredient, but we can't risk over-farming them. That's why we need to replace what we've taken. Bring me a handful of adult truffles, and plant some of these spores in their place.", objectives = "" }
WordHunterWoW_QuestEN[30331] = { title = "The Mile-High Grub", description = "Have you ever tried Mushan Tail Stew? Chances are, if you have, that it was stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew: you need to cook it at high elevation.\n\nI've already gathered the ingredients. Take this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew over their bonfire.", objectives = "" }
WordHunterWoW_QuestEN[30332] = { title = "Fatty Goatsteak", description = "You know what? I think I want to grill up some goatsteak today.\n\nNo, not from the puny little shaghorns they keep around here. They don't have nearly enough fat on them.\n\n<The chef pats his voluminous belly.>\n\nYou think I got to this size eating no-fat-havin' goats?\n\nNow, the shaghorns up on the Skyrange, to the west... those'll do just fine.", objectives = "" }
WordHunterWoW_QuestEN[30333] = { title = "The Lesser of Two Evils", description = "Like any farming community, we have the occasional virmen troubles.\n\nThe most powerful Springtail virmen live high up in the cliffs to the north, and only come down when they run out of veggies to nibble on.\n\nFrankly, I've dealt with virmen before. They're nothing but a pest that must be kept in check, and there's no better way to do that than by killing their warren-mother. Easy as that.", objectives = "" }
WordHunterWoW_QuestEN[30334] = { title = "Stealing is Bad... Re-Stealing is OK", description = "The hozen, up in the mountains to the west, continue to steal vegetables from my fellow farmers. Being so close to Halfhill, I very rarely suffer hozen attacks, but my friends have not been so lucky.\n\nSeems to me like they steal way more than they can eat. If you can find any intact vegetables up there in those mountains... steal them back!", objectives = "" }
WordHunterWoW_QuestEN[30335] = { title = "Stalling the Ravage", description = "The Kunzen hozen, up in the mountains to the west, have been acting up, lighting their fires and shouting their chants. Based on what I've heard and seen around here, that means that a ravage is coming.\n\nThere's not much we can do to stop the ravage, but we can at least thin their numbers before they attack.", objectives = "" }
WordHunterWoW_QuestEN[30336] = { title = "The Kunzen Hunter-Chief", description = "From what I've gathered, the Kunzen hozen have two chiefs. One is harmless - he deals with potions, medicines, and ancient fables. The other one is in charge of the Kunzen's hunters - and the only thing they've been hunting lately is our crops.\n\nThe Hunter-Chief is a problem waiting to be solved. I'm sure the local farmers would be grateful if you went up there and, you know, \"took care\" of him.", objectives = "" }
WordHunterWoW_QuestEN[30337] = { title = "Simian Sabotage", description = "The hozen steal from us, and we keep stealing our stuff back. It has to stop sometime.\n\n<Farmer Yoon hands you a barrel of fireworks.>\n\nFind some of our stolen supplies in their mountain camp to the west, and place these fireworks beside them. Hopefully, if they see the explosions, they'll think our supplies are defective and stop stealing altogether.\n\nIt's worth a shot, right?", objectives = "" }
WordHunterWoW_QuestEN[30338] = { title = "A Weighty Task", description = "For the life of me, I can't figure out why the mogu would have built all their statues and such down in that lake. I'm sure there wasn't always water down there, but it still seems wickedly inconvenient should it ever have rained.\n\nAh well, who's to fathom the strange intentions of the mogu...\n\nWould you be so kind as to swim down there and bring back any artifacts that seem even vaguely carry-able? I'd certainly appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[30339] = { title = "Getting your Hands Dirty", description = "Some of the best fishin' in all of pandaria in this lake right here. I brought enough brew to last me all day, but I didn't think to bring any bait.\n\nWho can really remember such things?\n\nIf you'd be willing to gather me some bait along the shore, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", objectives = "" }
WordHunterWoW_QuestEN[30340] = { title = "Stick in the Mud", description = "I came out for a beautiful day of fishin', but I didn't think to bring a pole. There are so many things to remember for fishin', I just can't keep it all in my head.\n\nThose reeds along the river look alright for makin' a pole out of. If you'd gather me some number of them, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. \n\nHow's that sound?", objectives = "" }
WordHunterWoW_QuestEN[30341] = { title = "Under Watchful Eyes", description = "<He looks down at the dead mogu scout at his feet, looks up at you, then points out out down the lake shore. It seems he wants you to find and kill more of these mogu scouts.>", objectives = "" }
WordHunterWoW_QuestEN[30342] = { title = "Fiery Tongue, Fragile Feet", description = "I was kicking the water for fun again when one of those vicious crocolisks lunged out to try to bite my foot off! Rude! I have proceeded to rest my weary soles a few feet farther from the water, but I already look back on my water-kicking days longingly.\n\nWould you be so kind as to kill a crocolisk or eight for me? I assure you they deserve it for frightening me though.", objectives = "" }
WordHunterWoW_QuestEN[30344] = { title = "The Lost Dynasty", description = "I wonder if I could bother you for another task. My daughter, the good Sentinel Commander Lyalia here, refuses to let me go into the field.\n\nI have spent everyday in that oubliette staring at the ruins to our north, itching to investigate.\n\nIf we are where I suspect we are those ruins could contain the key we need to finding the fabled Pools of Youth!\n\nPlease, {class}! Go to those ruins and salvage any tablets that still have writing on them.", objectives = "" }
WordHunterWoW_QuestEN[30346] = { title = "Where are the Pools", description = "Perhaps these mogu know where the pools are.\n\nOur scouts have reported seeing a commander along the southern side of the Ruins of Dojan.\n\nKill him and take whatever information he is carrying. They should lead you to the pool.", objectives = "" }
WordHunterWoW_QuestEN[30347] = { title = "The Pools of Youth", description = "North! Go north to the Pools of Youth. Get some of the water but be on your guard.\n\nThe mogu list this as a \"high value\" target. Kang Bramblestaff will meet you there if he has not already arrived by your side.", objectives = "" }
WordHunterWoW_QuestEN[30348] = { title = "Immortality?", description = "Something is... off. The water feels strange.\n\nWhen we arrived here I felt the presence of the Light, strong and vibrant, far to the north.\n\nI thought it would be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu magics.\n\nI think it best I try only a sip and we see what happens.", objectives = "" }
WordHunterWoW_QuestEN[30349] = { title = "Threat from Dojan", description = "While you were at the ruins dusting off tablets for my father I lost five scouts to wandering mogu patrols.\n\nThese creatures apparently have little interest in peace and are about as trustworthy as the Horde.\n\nThey are too numerous and we are too weak, however.\n\nGo to the ruins west of here and cull the mogu numbers. They won't be expecting a {class}.", objectives = "" }
WordHunterWoW_QuestEN[30350] = { title = "Squirmy Delight", description = "The hidden master may have to wait. Look at these people, {name}.\n\nThey are so THIN! They must be starving.\n\nYou know what we need? A big steaming bowl of Squirmy Delight.\n\nIf you find yourself near a river, try rounding up some intact skitterer glands and I'll cook up a batch.", objectives = "" }
WordHunterWoW_QuestEN[30351] = { title = "Lotus Tea", description = "The mogu really like their poisons and curses. Mama Bramblestaff always said lotus tea cures any mogu curse.\n\nI saw some imperial lotus plants in the nearby Ruins of Dojan. We should go gather some of their leaves and keep them on hand just in case the mogu get unruly.\n\nAlso, this will give me a chance to introduce my fists to some mogu faces.", objectives = "" }
WordHunterWoW_QuestEN[30352] = { title = "Crane Mastery", description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you to go kill me some carp hunters? You'll find them up and down the river west of here. There are a bunch of them so don't hesitate to hunt while doing other stuff.", objectives = "" }
WordHunterWoW_QuestEN[30353] = { title = "Profit Mastery", description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff.\n\nAnd this jungle is just full of tigers. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.", objectives = "" }
WordHunterWoW_QuestEN[30354] = { title = "No Sister Left Behind", description = "We were searching the ruins south of here when the mogu fell upon us out of nowhere.\n\nSome of us were able to retreat to this encampment but many others were captured. The mogu have also caught a number of the Horde who happened to be in the area as well.\n\nPlease, {name}, rescue any sentinels that you can.\n\nLeave the Dawnchasers to their fate.", objectives = "" }
WordHunterWoW_QuestEN[30355] = { title = "Re-Reclaim", description = "Mogu do NOT use arcane magics.\n\nThey are thugs. They have always been thugs. Only when they ruled their empires in the old stories did they ever know any kind of magic.\n\nBut these mogu are using arcane portals and old artifacts. We need to stop them!\n\n{name}, look for any artifacts the mogu are using to cast their magics with. I saw piles of these items being collected near the Ruins of Korja south of here.", objectives = "" }
WordHunterWoW_QuestEN[30356] = { title = "Sever Their Supply Line", description = "The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing in reinforcements and supplies.\n\nWhat is worse, they are sending their captives through these portals.\n\nGo to the Ruins of Korja and destroy as many of these Korjan Reclaimers as you can find.", objectives = "" }
WordHunterWoW_QuestEN[30357] = { title = "The Stoneplow Convoy", description = "Help me, {name}. These poor pandaren are in need of healing, and my powers are weakened.\n\nI did find an old tome in my collection that allowed me to convert the herbs you collected earlier into a healing poultice.\n\nUse this on the injured pandaren and it should get them back on their feet.", objectives = "" }
WordHunterWoW_QuestEN[30359] = { title = "The Lord Reclaimer", description = "They have my daughter! Brojai... that Lord Reclaimer! I can see him clearly through Lyalia's eyes.\n\nThat foolish girl must have tried to take him head on.\n\nPlease, {name}! Go to the Ruins of Korja and try to free her.\n\nI'll get Kang and try to draw out Brojai from the ruins with a distraction.", objectives = "" }
WordHunterWoW_QuestEN[30360] = { title = "Warn Stoneplow", description = "My father gave me his life. Tyrande gave me her trust. My sentinels gave me their allegiance.\n\nIt is time I repaid them all.\n\nWith Brojai dead we can mop up the remaining mogu. The next threat is the mantid.\n\nGo north to Stoneplow and lend them your help. Tell them I will be bringing what sentinels I can muster to aid in the defense of their city against the mantid.", objectives = "" }
WordHunterWoW_QuestEN[30361] = { title = "The Mantid", description = "The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that.\n\nNow they are preparing to hit Stoneplow.\n\nPlease, {class}, destroy some of these beasts before they get sufficient numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our convoy he should be able to reward you for your help.", objectives = "" }
WordHunterWoW_QuestEN[30363] = { title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nI want you to look for my scout. I sent her to investigate the Crane Temple but she hasn't returned.\n\nGet her report and rendezvous with us at the Sentinel Basecamp further west.", objectives = "" }
WordHunterWoW_QuestEN[30376] = { title = "Hope Springs Eternal", description = "The Shado-Pan are likely dealing with similar outbreaks elsewhere in Pandaria.\n\nSeek out Loon Mai, the Shado-Pan Watch Commander in Stoneplow on the western end of the Valley of the Four Winds. Let him know that we have the situation here under control; the Shado-Pan need not send any aid.\n\nQuite the opposite, in fact - I will be sending many of my followers on pilgrimage, to bring a message of hope to those in need.\n\nThank you again, {name}. Farewell.", objectives = "" }
WordHunterWoW_QuestEN[30384] = { title = "Blind Them!", description = "Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not long before you arrived.\n\nI don't know how he got here but I can guarantee you he isn't alone. They never are.\n\nKill the sunwalker scout before he reports our position.", objectives = "" }
WordHunterWoW_QuestEN[30385] = { title = "Setting Sun Garrison", description = "I offer you my heartfelt appreciation for your aid. Anji awaits you in the Setting Sun Garrison to the west.\n\nMay the day favor you, young {class}.", objectives = "" }
WordHunterWoW_QuestEN[30386] = { title = "A Dish for Ella", description = "A good day to you, neighbor.", objectives = "" }
WordHunterWoW_QuestEN[30390] = { title = "A Dish for Gina", description = "I've been on my feet all day. You'd be surprised how busy this place gets.", objectives = "" }
WordHunterWoW_QuestEN[30396] = { title = "A Dish for Old Hillpaw", description = "My wife used to make the most delicious braised turtle in four counties! I miss that woman.", objectives = "" }
WordHunterWoW_QuestEN[30402] = { title = "A Dish for Chee Chee", description = "Chee Chee work in fields all day, so tired!", objectives = "" }
WordHunterWoW_QuestEN[30408] = { title = "A Dish for Sho", description = "Do not let your strength waver.", objectives = "" }
WordHunterWoW_QuestEN[30414] = { title = "A Dish for Haohan", description = "A good farmer knows when to work and when to eat! You have to enjoy the fruits of your labor, right?", objectives = "" }
WordHunterWoW_QuestEN[30421] = { title = "A Dish for Farmer Fung", description = "I think I hear my stomach grumbling.", objectives = "" }
WordHunterWoW_QuestEN[30427] = { title = "A Dish for Fish", description = "I been climbin' trees all mornin'.", objectives = "" }
WordHunterWoW_QuestEN[30433] = { title = "A Dish for Tina", description = "Please say hello to Farmer Yoon for me.", objectives = "" }
WordHunterWoW_QuestEN[30439] = { title = "A Dish for Jogu", description = "You know what goes with a good drink? A good meal.", objectives = "" }
WordHunterWoW_QuestEN[30442] = { title = "Blanche's Boomer Brew", description = "Brew Blanche's Boomer Brew by Protecting the Brewkegs.", objectives = "" }
WordHunterWoW_QuestEN[30444] = { title = "No Reprieve", description = "We've been granted a brief respite from the mogu attacks as they attempt to recoup near the Five Sisters to our north. I would like you to see to it that they not be granted a similar reprieve.\n\nShow no mercy.", objectives = "" }
WordHunterWoW_QuestEN[30445] = { title = "The Waters of Youth", description = "She is headstrong, my little Lyalia. I should have known she would try to challenge the Lord Reclaimer.\n\nSince her mother died, I forsook much of the time I should have spent with her in search of immortality, insisting that we could live forever, together.\n\nAnd now my obsession has cost my little Lyalia her life.\n\nPlease, {name}, when she wakes, tell her I love her.", objectives = "" }
WordHunterWoW_QuestEN[30457] = { title = "Call Out Their Leader", description = "Clearly, you are a hero come to aid us.\n\nSlay the Bataari Tribe in the Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to appear.  Dispatch him.", objectives = "" }
WordHunterWoW_QuestEN[30458] = { title = "The Scouts Return", description = "{name}, your friends have returned from their scouting mission. They need to see you immediately.\n\nI'm afraid...\n\nWell, I'd better say no more. You will see for yourself.", objectives = "" }
WordHunterWoW_QuestEN[30459] = { title = "All of the Arrows", description = "As soon as their reinforcements arrive, the yaungol are going to overrun our position here. If they do that, the village will be lost.\n\nWould you be willing to retrieve as many arrows off the battlefield as you can carry? I have a plan that just might save us with your help.", objectives = "" }
WordHunterWoW_QuestEN[30460] = { title = "Hit Medicine", description = "Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to the northwest.\n\nTake this liniment.  It is a powerful medicine that has been passed down in my family over the generations.\n\nUse the dit da jow to heal the injured warriors if you do not have healing powers of your own to use on them.", objectives = "" }
WordHunterWoW_QuestEN[30461] = { title = "Into the Wilds", description = "Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", objectives = "" }
WordHunterWoW_QuestEN[30462] = { title = "Into the Wilds", description = "Deep in the wilds rests the  Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", objectives = "" }
WordHunterWoW_QuestEN[30464] = { title = "Going West", description = "Leza now walks with the ancestors of this strange land. I must look now to the living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nTrack him down and lend what aid you can to him. We will join you as quickly as we are able.", objectives = "" }
WordHunterWoW_QuestEN[30465] = { title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nWe are pressing westward and could use your help.\n\nMeet us at the Sentinel Basecamp further west when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[30466] = { title = "Sufficient Motivation", description = "Training these savages has been quite a task, {name}.\n\nFinding ways to motivate them was easy enough; the problem is keeping them motivated.. and focused... and awake.\n\nNow that you're back, you can help me in getting the less disciplined Hozen moving, if you catch my drift. I'll leave the method up to you.", objectives = "" }
WordHunterWoW_QuestEN[30467] = { title = "My Son...", description = "My son - can you find my son?\n\nWhen the Jinyu attacked, he ran off in the confusion. I don't know if they've done anything with him, or if he's still alive, even.\n\nNothing else matters if I can't find him. \n\nI'd ask Mei... but something's wrong with her. She seems too... impulsive since the attack. I just can't trust that she'd bring him back safely.", objectives = "" }
WordHunterWoW_QuestEN[30468] = { title = "Enraged Vengeance", description = "<The Swordmistress does not look well. There's a darkness to her eyes uncharacteristic of the pandaren.>\n\nI don't think I've ever been as... as furious as now. What betrayal!\n\nI fought them off when they attacked, killed a few here, but Merchant Shi is too much of a coward to let me go and finish the job!\n\nYou, do it for me. Kill them. Kill them all.", objectives = "" }
WordHunterWoW_QuestEN[30469] = { title = "Repossession", description = "Of course, the first priority is finding my son. But, if we save ourselves only to starve, then what have we accomplished, in the end?\n\nPlease, I need you to recover some of the supplies that the Jinyu took from our caravan.", objectives = "" }
WordHunterWoW_QuestEN[30470] = { title = "A Gift For Tina", description = "That Tina Mudclaw is in the Halfhill Market today, visiting her sister. She's really nice, but she's really hard to get gifts for!\n\nThere's a little jewel that can be found in the cliffs to the north. It's called a chrysoberyl, and it changes color when you hold it. I'll bet she doesn't have one of THOSE!\n\nLook inside the virmen caves. I bet you'll find one really fast.", objectives = "" }
WordHunterWoW_QuestEN[30471] = { title = "A Gift For Chee Chee", description = "That crazy Chee Chee is actually pretty neat. Mah always said that hozen were nothing but trouble, but... I guess he's just a better hozen then the rest of them.\n\nWe should do something nice for him! Those mountain hozen in the west make some really fancy stir fry, and keep bowls of it inside their little hozen houses.\n\nI bet Chee Chee would love some!", objectives = "" }
WordHunterWoW_QuestEN[30472] = { title = "A Gift For Sho", description = "Sho - that girl who lives up in the mountains - is in town today. I saw her walking toward the Halfhill Market.\n\nSuch a long walk... she must be hungry! And I think I know just the thing that she'll like.\n\nThe hozen up on the Skyrange cook a soup out of fish and apples. It sounds gross, I know... but it's awesome. You'll find it near their big, scary totem.", objectives = "" }
WordHunterWoW_QuestEN[30473] = { title = "A Gift For Fish", description = "That Fish Fellreed is kind of weird. First of all, her name's Fish. That's weird.\n\nOnce you talk to her, though, she's really a nice lady. Did you know that she's an animal lover?\n\nI've got an idea! The Kunzen hozen, in the mountains to the west, make little animal statues and put them in their huts to scare off bad guys. I bet Fish would LOVE something weird like that!", objectives = "" }
WordHunterWoW_QuestEN[30474] = { title = "A Gift For Ella", description = "That poor Ella. She's so shy! I saw her standing in the Halfhill Market, looking really hungry, but afraid to talk to any of the chefs.\n\nWe should bring her some food! And not any boring food - something special.\n\nThe Kunzen hozen make spicy shrimp dumplings from ingredients they've stolen from our farms. I don't like spicy food, but Ella might!", objectives = "" }
WordHunterWoW_QuestEN[30475] = { title = "A Gift For Fung", description = "Farmer Fung is pretty mean, and just a little scary. Mah always said that he was one of the best farmers in the valley, though.\n\nI think I know the perfect gift for a mean, kind of scary guy like him.\n\nThere's some big plainshawks that circle the hills to the west of here. You should get one, find a big piece of meat, and then ask Kol Ironpaw to grill it up!", objectives = "" }
WordHunterWoW_QuestEN[30476] = { title = "A Gift For Old Hillpaw", description = "Old Hillpaw has about a million chickens on his farm... but that's not what he REALLY loves.\n\nI saw. He collects blue feathers.\n\nI don't realy know where to get a blue feather around here, but I do know where to find some blue pearls!\n\nCheck the oysters in Cattail Lake to the northwest. I'm sure a blue pearl will look nice with his feather collection!", objectives = "" }
